/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20211006-4","meetingId":"r03-c-settlement","date":"2021年10月6日","dateIso":"2021-10-06","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件抜き出しています。","topics":[{"id":"topic-01","title":"◯渡部委員長 ただいまより決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","agenda":"◯渡部委員長 ただいまより決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"湯澤委員","kind":"質問・要望","question":"私からは、２７４ページ、健康推進費全般と、２８４ページ、保健予備費、それから２９６ページ、リサイクル推進費の全般から、お伺いさせていただきたいと思います。健康推進費全般についてです。健康について意識し始める年齢は人それぞれだと思うのですが、２０代ぐらいまではまだ健康への意識が低くて、むしろ不健康なことを好んでやっているかと、自分のことを振り返ってもそう思う次第であります。","respondent":"高山健康課長","answer":"メンタルケアという点につきましては、こころの健康の部分になってくるかとは思いますが、例えば保健センターにおける精神保健相談など、様々、保健所機能を通じて、こころに変調を来したような方に寄り添うような形での相談などを実施しています。","id":"exchange-001"},{"speaker":"湯澤委員","kind":"質問","question":"特に若い世代や、自分は健康だ、大丈夫だと思っている方は、知らず知らずのうちに健康被害が出てしまう可能性がありますので、そういった方たちに、自身の健康についてどう考えていただくかというのも課題だと思います。気分転換がメンタルケアにもつながると思いますが、こういった、外で運動することが難しいという方々に対して、区はどのようなアドバイスをしているか、教えてください。","respondent":"高山健康課長","answer":"そうしたものも利用していただくことで、屋内・屋外における運動習慣の定着に努めていただければと考えております。","id":"exchange-002"},{"speaker":"湯澤委員","kind":"提案","question":"例えば東京２０２０大会の区応援競技となった、ホッケー、ブラインドサッカー、ビーチバレーボールの選手や、あとは区内を拠点に活動している、バスケットボール、ダンス、そしてフットサルといったプロスポーツ選手に参加していただくような健康動画を区で作成していただくことで、発信力や影響力も上がって、品川区の魅力発信にもつながるのではないかと思うのですけれども、いかがでしょうか。","respondent":"高山健康課長","answer":"ご提案のオリンピック・パラリンピックのその後のレガシーといいますか、その後の活用という点で申しますと、健康増進部門だけに限られませんけれども、スポーツの部門などでも、様々、動画の活用の可能性というのは非常に高まっていると考えておりますので。","id":"exchange-003"},{"speaker":"湯澤委員","kind":"提案","question":"急な提案でありますが、在宅勤務者や健康にも無関心な方にも響くような動画もぜひ検討していただければと思います。２年に１度を逃した場合は、２年後と延びてしまっているのでしょうか。救済措置があるならば教えてください。ないならば区民の健康を最優先に考えると、何らかの救済措置が必要ではないかと思いますが、いかがでしょうか。","respondent":"高山健康課長","answer":"そもそも健診の間隔については合理的な理由がありますので、健診と健診との間には一定の間隔があったほうがいいということはもちろんのことなのですが、そうは申しましても、健康を確認する意味で必要なことと考えておりますので、その辺は柔軟に対応しています。","id":"exchange-004"},{"speaker":"湯澤委員","kind":"意見","question":"プラスチックごみの軽減とリサイクルの促進を目指しておりますプラスチック資源循環促進法が来年４月より施行されます。品川区のプラスチックごみの回収の現状と、この法律によって、どう取り組んでいこうと考えているのか。国はこの法律を総合的かつ計画的に推進するために基本方針と期間を定めておりますが、品川区でも来年の施行に向けて基本方針や期間を定めているのかも併せてお知らせください。","respondent":"品川品川区清掃事務所長","answer":"現在、どういう方法で進めたらいいかというところは検討中ですが、また国の動きも具体的指針等が出てくれば、それに伴って、どういうふうにしていくかというところは考えていきたいと考えています。","id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問・要望","question":"自治体としての方針は、いずれしっかりと決めていかなければならないと思いますので、他区の動向も研究しながら取り組んでいただきたいと思います。私たち個人も、プラスチック製品の購入を控えたり、また細かな分別が必要となってくると思います。個人がごみを減らしていく、分別をしていく取組みについて、区のお考えをお知らせください。","respondent":"品川品川区清掃事務所長","answer":"ごみの分別ですが、これは非常に難しいところでございまして、区としても、常に区民に対して啓発活動等を行ったり、環境学習等も進めているところです。こういったところを、やはり地道に粘り強く進めていかなければならないと考えています。","id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問・要望","question":"子どもから「なぜペットボトルによって硬さが違うの」と質問されたとき、大変困ったことがありました。企業努力が求められるワンウェイプラスチックが削減されることによって、最初は不便に感じるかもしれませんけれども、製品がなくなれば、私たちがごみを出す必要もなくなってくると思います。最後に、品川区として、企業に求めていきたいと思っているところをお知らせいただければと思います。","respondent":"品川品川区清掃事務所長","answer":"ただ、非常に複雑な分別となると、区民の方にもなかなか伝わらないところ等もあります。いかに分かるような分別を進めていくかというところを、区としても常に研究して進めていかなければならないと考えています。","id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"２８５ページ、予防接種費、２８３ページ、母子健康診査費については、予診票のデジタル化、それから子育てワンストップサービス、子育てノンストップサービス、母子手帳アプリについて伺いたいと思います。２９２ページ、環境対策費、３１３ページ、消費者啓発費については、エコルとごしでの環境講演やサステナブルファッションショーなどについて伺っていきたいと思います。そういうご相談がありました。","respondent":"鷹箸保健予防課長","answer":"現状、２３区統一の中では、すぐには難しい部分があろうかと思いますが、今後の可能性として、あと間違いをなくすという観点からも、十分考えていかなくてはいけない問題かと思います。","id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"ほかの自治体をいろいろ確認しながら、連携しながら、また地元では医師会の皆さんとも協議しながらという形で進めていかなくてはいけない部分かと思いますが、大きい部分では、デジタル庁を含め、行政のデジタル化の大きな流れが今ある中で、具体的なこうしたところについては、先行してやっているところがどういう仕組みでやっているのか、ぜひ積極的に情報収集等をしていただいて、国の大きな流れも含めて。","respondent":"河内環境課長","answer":"こちらにつきまして、ファッションショーなどですが、ファッションロスに関連する団体、例えばリメイクファッションなどを行うような団体と連携いたしまして、エコルとごしの環境講座もございましたが、イベントなどによりまして、衣服分野の環境課題に関する取組みですが。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"環境講演会をやるだけで、人がなかなか集まらなかったり、本当にメッセージを届けたい区民の方に届いていなかったりということにならないような講師の選定というのでしょうか。そういったことも含めてお願いしたいと思います。先ほど清掃作業員の話をしましたけれども、山梨県のある町の環境課に、その地域に住んでいる女性の方が質問したそうなのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（博）委員","kind":"意見","question":"本日は、２８２ページ、乳児健康診査から、４か月児の個別健診について、２８４ページ、保健予防課職員給与費から、保健所職員の受付対応について、２８７ページ、定期予防接種から、ＨＰＶワクチンについてを、順不同でお尋ねしてまいります。よろしくご回答をお願いいたします。歳入審査でも、あくつ委員による見識あふれる質疑応答がありましたが、まず初めにＨＰＶワクチンについてお尋ねいたします。","respondent":"鷹箸保健予防課長","answer":"予防接種法の第２条に、「予防接種とは、疾病に対して免疫の効果を得させるため、疾病の予防に有効であることが確認されているワクチンを、人体に注射し、又は接種することをいう」と定義されておりまして、現在のところ、主に小児を対象として接種努力義務があるＡ類疾病と。","id":"exchange-011"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そしてＨＰＶワクチンは、国が責任を持って接種をお勧めするワクチンであるにもかかわらず、接種をお勧めしないという、わけが分からない、異常な宙ぶらりんの状態が、実に８年間もだらだらと続いているのです。その信頼できるデータについて、簡単にご説明をお願いします。","respondent":"鷹箸保健予防課長","answer":"前提といたしまして、ＨＰＶワクチンは２年前の時点で、世界９２か国で予防接種を実施すべきというプログラムとして取り入れられているワクチンです。","id":"exchange-012"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今、課長からご説明があったように、ＨＰＶワクチンを１７歳未満で接種した場合、子宮頸がんの発病を８８％抑えるというデータがスウェーデンから発表されています。空白の８年の間、ＨＰＶワクチンが子宮頸がんの発病を予防すること、しかも安全なワクチンであることが、今、世界中から続々と報告が積み上げられているのです。","respondent":"鷹箸保健予防課長","answer":"ＩＳＲＲ、予防接種ストレス関連反応ですが、これはＨＰＶワクチンには限らず、予防接種をする、つまり注射をするということそのものに対する不安が高じて起こる様々な症状を表す概念といたしまして、２０２０年１月にＷＨＯが提唱したものです。","id":"exchange-013"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２０２０年１０月、厚生労働省は、ＨＰＶワクチンについての情報を載せたリーフレットの戸別配布を、自治体を経由して始めました。定期接種のワクチンの情報提供に、これは一体どういう意味なのでしょうか。勧奨を行うことに問題があるのなら、なぜ定期接種から外すという議論が起こらないのでしょうか。これについて、区のご見解をお聞きしたいと思います。","respondent":"鷹箸保健予防課長","answer":"ＨＰＶワクチンが定期接種に導入された２０１３年の時点で、ＨＰＶワクチンの接種により子宮頸がんの罹患の可能性が低くなるという明確な根拠がありましたので、先ほどの定期接種の定義に当たるということから、定期接種として導入されたわけですが。","id":"exchange-014"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２０１３年６月に積極的勧奨が中断されてから、リーフレット配布が再開された２０２０年８月までの間、定期接種であるＨＰＶワクチンの情報、子宮頸がんの発病を６０％から７０％予防できるということ、あるいは無料で接種できるということ、法律で保護されているということなどの情報が一切提供されず、接種期間を逃してしまった女性の存在を、区は今どのようにお考えでしょうか。","respondent":"鷹箸保健予防課長","answer":"非常に残念だと言わざるを得ないと考えております。この方々は、１年で１,２００人から１,３００人と考えまして、既に１万人近くになるわけでございまして、この対象の方々がそういう接種の機会がなかったことを考えますと、じくじたる思いを抱くところです。","id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区はワクチンに関して、東京２３区の中でも最も先進的な区であると高く評価されてきました。接種のＨＰＶワクチンは、２価、４価だけでなく、９価も含めることをお願いしたいと思います。なぜならば、９価ＨＰＶワクチンは、子宮頸がんを９５％予防できること、２回接種で十分効果が上がることが分かっているからです。ぜひご検討をお願いしたいと心から思います。区のご見解はいかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"接種勧奨が止まっていた、一番、最高齢だった方は既に２４歳になっているわけで、委員ご指摘の日々の感染の脅威という観点からは、本来、接種対象だったこの方々に対して何らかの対応を考えるということは、今後の重要な課題だと認識しています。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今なお年間１万人の女性が発病し、３,０００人近い女性が死亡しており、健診の結果、９,０００人の女性が子宮を切り取るという手術を受けているという恐ろしい子宮頸がんを撲滅する方法は既に明らかです。これを９０％の接種率に高めること。次に、４か月児健診についてお伺いいたします。ＣＯＶＩＤ－１９の流行下、４か月児健診の集団健診の対象人数と受診人数の推移について、ご説明をお願いいたします。","respondent":"柏木品川保健センター所長","answer":"令和３年度、８月までの実績になりますが、対象者１,４８７名、受診者１,３７０名、受診率９２.１％です。今年度、まだ残り６か月ありますが、今年度も例年同様の受診率ではないかと考えております。","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"コロナ前は大体９５％ぐらいだったと思いますが、集団健診を補完する位置づけで始めた個別健診の受診人数の推移と、個別健診は、家庭のご事情をよくご存じのかかりつけ医で行われるという、非常にメリットがあると思うのですが、今後の見通しについて簡単にご説明をお願いします。","respondent":"柏木品川保健センター所長","answer":"個別健診の推移です。令和３年度２月から始めまして、令和２年度は４名、３年度、今年度は８月までですが、１２名となっております。今後につきましては、コロナの状況を見ての判断になりますが、延長等については柔軟に考えていきたいと考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"３０７ページ、就業支援事業、若者等就業支援事業に関わって、ポケット労働法の配布、２８９ページ、新型コロナウイルス感染症対策、学校でのＰＣＲ検査について伺います。都が発行するポケット労働法ですが、その前書きには、発行の目的についてこう書かれています。伺いますけれども、区はこの冊子を意義あるものとして評価しているのかどうか。区のホームページに記載はあるのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"こちらにつきまして、東京都のホームページなどでも今見られるような状況になっているところですけれども、今、確かに最近、働き方改革関連法の改正などという部分がありますので、その辺について、区としてどういう形で周知するか、あるいはそういう冊子の提供についても。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"かなり積極的な姿勢の現れの一つかと思うのですけれども、ぜひ、中小企業センター内にあるサポしながわ、あるいは区も運営主体者でもある品川区就業センターでの配布、あるいは台東区のように成人式の申請人への配布、それと、今、区に品川区わかもの・女性就業相談コーナー公式ＬＩＮＥというのがありますけれども、そこでのプッシュ型情報提供、あるいは区内の高校や大学もありますので、ぜひ。","respondent":"遠藤商業・ものづくり課長","answer":"事前の理解があればというところがあろうかと思いますので、その辺については、今の委員ご指摘のポケット労働法なども踏まえて、様々な形で検討させていただければと思っているところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"提案","question":"私はガイドラインを受けて、区教育委員会の検査の考え方はどうなったのですか、感染者が１人出たら、学校の判断で、クラス全員を検査対象にすることが可能になりましたけれども、品川区教育委員会としてはやるつもりはないのですかと質問しました。つまり、何も変わることはないということだったのです。ちょっと保健所に伺いたいのですが、区教育委員会はどうしてこういう判断になったのでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"このガイドラインが出ましたけれど、区教育委員会と、どういうふうに扱おうかという打合せなどはなかったということなのでしょうか。伺いたいと思います。ですから、今のご答弁ですと、では、きちんとガイドラインに則って、もう既にそれ以上のことをやっていましたので、クラスで１人感染者が出たとしたら、基本的にはクラスで検査をするということでよろしいのでしょうか。伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"今回、ガイドラインが出ましたとき、即、学務課長と私で協議をし、内容を入念に検討しましたところ、先ほどご答弁申し上げたとおり、既に保健所と学校が、１人感染者の方が出たときに協議した、実施してきた内容と何ら変わりがなく、ある意味。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"ではガイドラインの内容をしっかりと、当然やっていくということで私は理解しましたので、今後は、少なくとも、クラスで１人出たと。それで、子どもや保護者から、希望がなくてもやるべきだと思うのですけれども、希望があった場合、今、唾液等で負担もなくできるわけですから、クラス全員、検査をやると私は理解しましたけれども、それで間違いないでしょうか。伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"必要に応じて必要だと判断した場合に実施しておりまして、これは、希望される生徒あるいは保護者の方を対象に実施するものではありません。希望に応じて、それを受けて保健所が検査するのではなくて、状況を入念に、学校、それから保健所で把握します。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう判断が検査を抑えてきたのです。それで不安にさらされているわけです。ですから私は、無症状の感染者の方が、症状がなくても感染するというのがコロナの特徴なわけですから、いろいろ判断して、やりませんと。ですから私は、学校の子どもや保護者の不安に寄り添って、広く、このガイドラインをしっかりと使って、検査をしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"くにば委員","kind":"提案","question":"衛生費から、２８７ページ、コロナワクチン接種関連について、順不同でお伺いいたします。３月の予算特別委員会にて、プレミアム付区内共通商品券のデジタル化についてご提案申し上げました。本区では、１１月１日から３０日まで、この事業を実施予定で、最大３０％、期間中、上限１万円相当をポイント還元いたします。今回のこの取組みについて、まずは本区での狙いをお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"今回のＰａｙＰａｙを活用した事業ですけれども、こちらは比較的簡易なＱＲコードを店舗に置くだけで実施できるということで、非常にやりやすいという部分がありますので、まず、こちらで試していただくというのも変なのですけれども、ハードルが低いものでやっていただきまして。","id":"exchange-025"},{"speaker":"くにば委員","kind":"提案","question":"こちらの事業、今おっしゃった形で、個店でのキャッシュレス決済は需要が見込まれます。その後、区内事業者のキャッシュレス決済導入の状況について改めて伺いたいのと、それで１つご提案なのですけれども、キャッシュレス決済端末の費用助成を、区で独自で再度行ってみてはいかがかと考えますけれども、ご所見をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"導入補助、キャッシュレスの端末の機械の補助ですけれども、現在、私どもで新型コロナウイルス感染症対応特別助成というものを実施しています。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"事業者もこれはあまり存じ上げないかと思うのですけれども、この点について、これは要望なのですけれども、区民委員会でもよく申し上げているのですが、品川区には様々な支援のメニューがありますけれども、それぞれの助成内容でどういったことに対して補助のメニューを適用できるかというのは、なかなか事業者で分かりづらいという部分があると思います。","respondent":"遠藤商業・ものづくり課長","answer":"品川区、五反田バレー、商店街の連携事業ということで、しながわ商店街応援プロジェクトを立ち上げているところで、商店街はいわゆるＩＴがなかなか進んでいないというところもありまして、五反田バレーの力などを借りながら、より効率的な運営ができないかということで。","id":"exchange-027"},{"speaker":"くにば委員","kind":"提案","question":"そういった五反田バレーでの取組みの中で、例えば私が３月の予算特別委員会で、商店街と連携したデジタルスタンプラリー事業をご提案いたしました。例えばこの事業を、ココシル品川ではなく五反田バレーと連携して実施するなど、改めて検討がどういう状況であるかなどを伺いたいのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"先ほど申しましたデジマ式ｐｌｕｓというイベントを、昨年の１１月に実施させていただきまして、その後、商店街と企業とで何かできないかということを、個別に相談などをさせていただいたところです。","id":"exchange-028"},{"speaker":"くにば委員","kind":"質問・要望","question":"そういった形のデジタルスタンプラリーは、恐らく需要や、今後、スマホを活用したという部分で、確実に進んでいけるような事業だと思いますので、ぜひとも引き続きご検討をお願いしたいと思います。９００万円が決算額となっておりますけれども、こちらもその事業内容等についてお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"それからもう一点の、ＩＴサポーター事業ですが、こちらも昨年度限定というものになりますけれども、ＩＴサポーターと言われている、これは人数が１５名ほどだったのですけれども、こちらが、商店街も回ってはいるのですけれども、各個店を中心に回らせていただきまして。","id":"exchange-029"},{"speaker":"くにば委員","kind":"質問・要望","question":"今、３回目接種というところで言われておりますけれども、一定程度期間が経ったら、抗体価が落ちてしまって、また接種しなければならない状態にもなりますよということを、きちんと広報・告知していただいて、コロナワクチンの接種完了後も引き続き気を緩めないように勧奨して広報していただければと思うのですけれども、ワクチン接種会場でチラシを渡したりする積極的な広報についてお伺いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"はホームページ等々で、接種が終わってもマスクはしっかりしてください、引き続き感染予防にご注意くださいということを広報しつつ、接種会場でできるかどうかということは、もう１・２回目の接種がほとんど終わってきている状態でもありますので。","id":"exchange-030"},{"speaker":"くにば委員","kind":"質問・要望","question":"確かに、２回接種がかなり進んで終わっているので、会場の中でというのは難しいかもしれませんけれども、マスクを外しているのは意外と高齢者の方が多かったりするというのを伺っております。ですので、ホームページでの告知などではなく、例えば、ふれあい掲示板等で、そちらについての広報をするなりして、２回接種後も決して気を緩めないように広報していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"３０６ページの産業経済費から、若者等就業支援事業について伺います。最初に衛生費から伺います。感染症への対応と母子保健への対応の両方を担う中で、この数字をどのように評価して、今後どのように実績を上げていこうと考えるか、保健センターのキャパシティの問題と、それからきちんと健診を受けていただく、その両方をきちんと進めていっていただきたいのですが、見解を伺います。","respondent":"柏木品川保健センター所長","answer":"それと、ほかに、保健センターに対して、やはり妊産婦からの電話相談が昨年度は非常に増えてあります。前年比で５割強も電話相談が増えておりますので、そういう部分では対応できていると考えております。","id":"exchange-032"},{"speaker":"吉田委員","kind":"提案","question":"分かりました。なかなか訪問は難しいということなのですが、一方で、やはりコロナ禍で、孤独に育児をしていらっしゃる方のメンタルなどということも気になりますので、これは具体的な提案はないのです。当事者の方たちに伺うと、やはり制度として使いにくいということをおっしゃいます。要は、障害者の方のかかりつけの歯科医で検診ができるようにしていただきたいと思うのですが、いかがでしょうか。","respondent":"高山健康課長","answer":"基本的には公益事業として進めておりまして、歯科医師会の歯科クリニックの方々がご案内先として適切と考えております。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、そこをもう少し工夫していただきたい。もし何か見解があったら伺います。それから、小規模事業者の廃プラスチックも、プラスチック資源として一括収集することを、市区町村に求める内容が盛り込まれております。先日の特別委員会では、区としての具体策は、区民への啓発しか伺えませんでした。区が率先して発生抑制の姿勢を示す施策が必要だと思いますが、見解を伺います。","respondent":"高山健康課長、品川品川区清掃事務所長","answer":"そういったものも踏まえながら、今後、歯科医師会とも様々協議を重ねながら、こうした制度が有効に活用されるよう、制度の充実に努めてまいります。こういった部分も企業等に啓発していくというところも、やっていかなければいけないところではないかとは思っております。具体的なやり方等については、いろいろと検討していきたいと考えています。","id":"exchange-034"},{"speaker":"吉田委員","kind":"提案","question":"障害者歯科検診のほう、どうぞよろしくお願いいたします。そのほかに、区内の商店に対して、昔ながらの、容器持参の区民に量り売りを推奨するなど、区として提案する施策に取り組むべきと考えます。区としても具体的なリデュース事業に取り組むべきと考えます。あわせて、それを推進するためにも、区として拡大生産者責任の必要性を国に対してしっかり主張することを求めたいのですが、見解を伺います。","respondent":"品川品川区清掃事務所長","answer":"国への要望等につきましては、法律等でしっかりと国が進めてあります。こういった状況を見ながら、自治体としては動いていきたいと考えています。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"国のほうでしっかり進めているということなのですが、私の認識不足かもしれませんけれども、拡大生産者責任の拡大のところは、どうもはっきり明示されていないと感じております。この新しい法律によって、回収が増えるわけですから、自治体の負担増が私には想定されてしまうのです。今後、区として、国に対して拡大生産者責任の拡大を改めて主張するよう求めたいのですが、いかがでしょうか。","respondent":"品川品川区清掃事務所長","answer":"ただ、世の中の情勢として、１つ、素早い動きで対応しているのが、コンビニエンスストアやファミリーレストラン等で、プラスチックスプーンといったものを紙のスプーンに切り替えたり、それからバイオプラスチックというものに切り替えたりということで、様々。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"昨年の決算特別委員会でも同様の質問を致しました。品川・生活者ネットワークとしては、自死、自殺を防止する施策を求めておりますが、職を失った人への支援はその意味でも重要だと考えております。根本解決にはなりませんが、今の状況では、区の事業や作業の中から仕事を切り出して任せられるような、何とか仕事を生み出すということも検討すべきと考えますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"もう一点の、いわゆる仕事の切り出しという部分ですけども、なかなか昨年度は臨時のものが多かったというところで、やらせていただいたところですけれども、既に人員確保した上での新たなものというと、なかなかちょっと、新たに雇うことが難しいというような形ですので。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"就業センターの支援で、きちんとした就職に結びつけば、それがもう一番だと考えています。事業者も、働く人も、両方支援しなければいけないということで、ぜひ何か方法を編み出してほしいと考えています。品川区には、子ども若者応援ネットワークがあります。ぜひそこと連携しながら、各団体の意見も聞いて施策を進めてほしいと考えますが、その辺についてはいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"現在、直接、子ども若者応援ネットワークとのつながりというのはないところですけれども、こちらを所管している各課と会議などを開いてやっているところですので、今後そういう部分も含めまして検討させていただければと思います。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"私からは、２９６ページ、リサイクル推進費、２９８ページ、清掃費、２８９ページ、自宅療養者対策経費、２８５ページ、予防接種費について伺います。それで、昨年７月からレジ袋の有料化が始まったというところであります。そこで、令和２年度の燃やすごみ・資源ごみの、前年度までとの比較で、何か変化があったのか、伺います。","respondent":"品川品川区清掃事務所長","answer":"燃えるごみと資源ごみの割合は、大体、資源ごみも含めて全般的に、品川区で出される量が１０万t、ざっくりですが、そのうち燃えるごみが７万５,０００ｔ、それから資源ごみが２万５,０００tぐらいというような割合となっております。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"そうなのです。これを拝見すると、ほぼ昨年の７月から始まったということなので、６月と７月を比較すると、ほとんど変化がない状況です。それで、６月から７月への変化ということなので、コロナ禍の中にあって、コロナ禍の中でどう変化しているのかというところを見ていけるのだと思うのです。それとも、少なくとも数字上は分からないという結論になるのか、お伺いいたします。","respondent":"品川品川区清掃事務所長","answer":"月別の動向で、１か月の動きがどうかというところは、なかなかその原因について把握しづらいところがあるかと思います。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問・要望","question":"長くなってしまったので、次に移ります。これまでも議会で、自宅療養者の関係は、いろいろ質疑はあったのですけれども、連絡が取れなかった場合の対応のところだけお伺いできればと思います。実際に保健所が連絡を取ろうとしても連絡が取れない場合に、どういう対応をされているのか、お願いいたします。","respondent":"鷹箸保健予防課長","answer":"この間、本当に警察の方のご協力は著しくて、それは夜中、遅い時間になりますので、夜９時や１０時に警察に電話をして、やはり連絡が取れないので来てくださいとお願いすると、一緒に安否確認をしていただいている状況にあります。それは、区内どこの警察、派出所も同じ対応です。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"最後に、もう時間がないので、１つだけ要望というか、もう難しいとは思うのですけれども、高齢者のインフルエンザ予防接種で、去年、２,５００円が無償化されていたのに、今年は東京都がやってくれないということで無償になっていないのですが、他自治体で見ると、千代田区や港区では独自に無償にしているというところがありましたので、もう始まっているものなので難しいとは思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"松澤委員","kind":"確認","question":"私からは、決算書２８７ページ、こころの健康づくり事業、３０９ページ、商店街活性化事業費についてお聞きいたします。こういった社会問題としても取り上げているこの課題ですが、１つお聞きしたいというか確認したいことがありまして、統計でいろいろ原因が出ていると思うのですけれども、亡くなられた方はもうお答えできないではないですか。そういうところを教えていただけますか。","respondent":"鷹箸保健予防課長","answer":"自殺された方の様々な原因ですが、ベースとなっておりますのは、２００７年から１２年の間、６年間かけて、ＮＰＯ法人の自殺対策支援センターライフリンクが実施されました、「自殺実態１０００人調査」という非常に大規模な調査が基になってあります。","id":"exchange-043"},{"speaker":"松澤委員","kind":"質問","question":"令和元年に策定いたしました品川区自殺対策計画における基本施策、自殺対策を支える人材の育成、区民への啓発と周知に基づき、オンラインゲートキーパー研修を、これはＹｏｕＴｕｂｅ配信で、今年の１月２１日から開始されました。約２７分の動画を５つに分けて無料で閲覧できるようになっておりますが、これの作成に至った経緯を教えてください。","respondent":"鷹箸保健予防課長","answer":"こちらの動画ですけれども、内容をご覧いただきますと、品川区のためにということではございませんで、昨年度から人材育成に力を入れる中で、上級者向けのゲートキーパー研修なども委託しております、ＮＰＯ法人ＯＶＡが作られたものを。","id":"exchange-044"},{"speaker":"松澤委員","kind":"質問","question":"やはり、１人で抱えない。研修動画にも書いてありましたけれども、ゲートキーパーも１人で抱えない。でも、先ほど言いましたけれども、ゲートキーパーの悩み、相談機関にきちんとつなげられるかというところでも、要は１つに絞ったほうが、ゲートキーパーも、ではこの悩みはこの相談窓口にというふうに思いやすいかと考えるのですけれども、これについてどう思いますでしょうか。","respondent":"鷹箸保健予防課長","answer":"確かに相談先が多くなっておりますが、先ほどご説明したとおり、いざ、もう死ななくては、もう死ぬしかないと思われた方は、心をかなり病んでいる状態に近くなっておりますので、ここが一番というわけではないのですけれども、本当にどうしようもなくなったときに。","id":"exchange-045"},{"speaker":"松澤委員","kind":"質問・要望","question":"庁内連携がいろいろ行われているということでしたけれども、どこかの窓口に引っかかるような支援で頑張っていきますということで、やはりまずゲートキーパーのほうを見ると、ゲートキーパー支援の部分でも、ゲートキーパーからの相談窓口みたいなものがあるといいかとは思っています。これは要望です。商店街については、次回質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"提案","question":"環境のところから行きます。展示のことについて、気候変動対策はやはり展示のメインとすべきではないかと考えております。以前に委員会の中で、ここを訪れた人が気候変動に対して気づきがあって、そしてその後の行動変容に強くつながるような、危機感を感じられるような展示内容にしてはいかがですかということをご提案したことがありますが、この辺り、今どのような形で進んでいるのか、教えてください。","respondent":"河内環境課長","answer":"気温や天候、季節感など、こういうことが起こったときにどういうことが起こるのかという具体的な展示も含めて、危機感を体感しながら学習効果を上げていきたいと考えているところです。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"そのような形で、今、検討を進めていただいているということですので、どうぞ鋭意、来年の開館を楽しみにしたいと思います。次に、３０３ページ、中小企業経営支援事業費で、持続化給付金・感染拡大協力金申請の相談窓口について伺います。決算の中での事業の目的、そして誰が委託されてこの事業を実施したのか、一体何を相談する窓口だったのか、教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"当初、あまり慣れていらっしゃらないと、それで、国のほうで、特に電子申請というところがあったり、用意するものが分からないというような話を頂いたところがございまして、本来であれば当然、国や都、申請を受けるところが準備するところかとは思うのですけれども。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"趣旨はよく分かりました。やはり、そこで私が首をかしげたところが、今、準備する資料が分からないというお話があったのですけれども、この２つとも、手持ちの資料でできるのです。手持ちの資料でやる。これは見れば分かるのです。我々も一番相談を受けるのはこれなのです。１７回ですから。みんな、そこをやってほしいわけです。何で申請代行ができないのか、やらなかったのか、そこについて教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"いわゆる書類が準備できていた段階ですと、入力の代行ということであれば、国で設置した申請の窓口が全国に置かれたですので、そちらをご案内したです。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２,７００万円の予算を計上して、みんな手持ちの資料を持っていって、これはどうすればいいのですか。ちょっとそこは私は解せない。最後の申請までやれるような仕組みにしてくれませんかということを何度も区にも要望したのですけれども、結局、いまだにそのようになっていない。５０人の方とお話ししたわけですから。きちんとニーズにマッチした窓口をつくっていただきたいのですが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"そうなると、いろいろな資料を持ってきていただいて、中小企業診断士にその中身を確認していただいて、こんなふうですよというような部分もあったかというところで認識しています。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今のご答弁だと、２,７００万円をかけてつくった、委託した事業が、二義的、三次的だったということですか。私はそこが本当に解せないのです。２８７ページの各種がん検診について伺いたいと思います。これはがん対策推進計画にも掲載していただきましたが、品川区もそろそろ、これは必要性を認めるというご答弁を前に頂いていますけれども、これはぜひ実現していただきたいと思いますが、いかがでしょうか。","respondent":"高山健康課長","answer":"最後に、アピアランス支援につきましては、委員ご紹介のとおり、かなりの区で取組みが進んでおりますので、区内におけるがん診療連携拠点病院の相談センターなどと協力して進めてまいります。","id":"exchange-051"},{"speaker":"せお委員","kind":"質問","question":"私からは、２８３ページ、母子健康診査費、２８７ページ、新型コロナウイルスワクチン接種対応経費です。新型コロナウイルスワクチン接種対応経費の主な内訳を教えてください。さらに、国からの補助があると思うのですけれども、このうち区の持ち出しはどのくらいあるのか、教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"２点ご質問いただきました。内訳です。内訳は、およそ３,９００万円が、コールセンターと、それから接種券の印刷経費となります。そして４００万円が、システムの改修費という形になります。こちらは、国からの補助金ということで、全額負担ということになっております。","id":"exchange-052"},{"speaker":"せお委員","kind":"質問・要望","question":"先日の一般質問でも取り上げさせていただきました、コロナワクチンの３回目接種の準備状況についてなのですけれども、国で決定していない話で申し訳ないのですが、検討だけはしておいていただきたいという思いからお聞きします。先日の答弁は、これまでの実施状況や課題を踏まえということでした。これまでの実施状況や課題というのは、具体的にはどんなことでしょうか。お聞かせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今後の課題としましては、集団接種・個別接種の割合等と、それから、今回は３回目１回のみの接種で、かつ８か月後ということが示されており、ある程度、接種する人が重なることがないようなスケジュールを組むことができますので、その辺りを踏まえまして。","id":"exchange-053"},{"speaker":"せお委員","kind":"質問・要望","question":"そんなメリットもあります。３回目の対象者は、報道では、医療従事者、高齢者、高リスクの方などと言われていて、そう推測できますので、個別接種会場のほうは、例えば高齢者のみなど、一部限定した上で、３回目接種の際の会場の準備をしていただきたいと私は考えますけれども、会場設置の考え方といったところについて、今、少しお話があったのですけれども、その辺の細かいところの見解を伺います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"当然、３回目のお話も現在進めているところで、会場設営については、現在まさに協議しています。引き続き、皆様がスムーズに接種できるような体制を取れるように、今後、協議してまいりたいと考えております。","id":"exchange-054"},{"speaker":"せお委員","kind":"質問","question":"初めてのことばかりで大変だったかと思いますが、落ち着いてきた今、これを踏まえて検討や準備をお願いしたいと思っています。次に、母子健康診査費から母子健康手帳についてお聞きします。令和２年度の当初予算を見ると、いわゆる母子健康手帳の１冊の単価は１１０円となっていますが、平成３１年度は１０８円でした。少しではありますが、なぜ上がったのかを、ご存じでしたらお聞かせください。","respondent":"高山健康課長","answer":"母子健康手帳の購入価格の変更理由です。いわゆる消費税が改定になったという点を踏まえて、その辺の部分が単価に反映されているところです。","id":"exchange-055"},{"speaker":"せお委員","kind":"提案","question":"理解いたしました。母子健康手帳に関しては昨年の決算特別委員会で取り上げましたが、今日は３点ほど提案させていただきたいと思っています。ネーミングも含めた母子健康手帳の考え方です。ネーミングに関しては、親子健康手帳としていただきたいと要望します。他区では、墨田区が平成２７年度から、江戸川区が令和２年度から、親子健康手帳としています。こちらの見解を伺います。","respondent":"高山健康課長","answer":"今般におきましては様々なご意見がある中で、家族みんなで受け入れやすい名称をということで、日本全体でもやはりそうしたお話が出てまいりますので、父親なども受け入れやすいネーミングなどは検討すべき時期にはなっているかと考えておりますので。","id":"exchange-056"},{"speaker":"せお委員","kind":"確認","question":"ぜひ前向きに検討をお願いいたします。私が昨年質問した際、比較的廉価で入手できるような標準的なものを、現在、採用していると答弁がありました。母子健康手帳は、胎児の頃から、もう家族みんなが成長を確認しながら、楽しみにして、幸せな気分になれるものです。予算の面でも、少し単価が上がっても、区内産業の支援にもつながりますし、費用対効果は高いのではないでしょうか。こちらの見解を伺います。","respondent":"高山健康課長","answer":"ご提案の、品川区の独自性という面においては、当然、応分の費用負担は発生するわけではありますが、親しみを持って、そうしたものを長く使っていただけるという観点では、貸与するということも十分検討の範囲だと思いますので、それに関しても。","id":"exchange-057"},{"speaker":"せお委員","kind":"提案","question":"母子健康手帳に加えて、小さな成長も大きく喜べるような工夫がなされている手帳があると前向きになれると提案させていただきました。そのような手帳を各団体が作っていて、それをホームページでご紹介してほしいと要望したところ、「より行き届いたホームページの掲載などは、十分に検討する余地があると思います」と答弁がありましたが、こちらの進捗状況をお願いいたします。","respondent":"高山健康課長、柏木品川保健センター所長","answer":"ただ、子ども手帳モデルに関しましては、調べる中ではありますが、様々、廉価なものなども市中に出ているというお話も伺っておりますので、そういったものも１つ採用していくに十分な状況になりつつありますので。私からは、すくすく赤ちゃん訪問での手帳の配布等についてですが、手帳の採用が決まりましたら、その点についても検討はしたいと思います。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、２８５ページから２８９ページにかけて、新型コロナ感染症対策について伺いたいと思います。総務費の質疑で、保健所の体制、残業時間などをお聞きしました。本当に大変な中、本当にお疲れさまでしたと考えています。それから、今は第５波の新規感染者が大変減少しておりますけれども、そういう状況の中で、残業などの働き方は改善されているのか、現在の状況もお聞かせください。","respondent":"鷹箸保健予防課長","answer":"全ての部から応援頂いた結果、平常時よりも３０人ぐらい多い人数で対応しておりましたので、何とか、今回の第５波は乗り切ったところですが、それでも、手伝いに来てくれた応援の職員もかなりの残業になったという現状がありますので、そこの部分につきましては、例えば。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"感染者の推移、年代別の感染状況、重症等の患者の実態、および死亡者の状況、感染源の状況、社会福祉施設での感染の発生状況、ワクチンの接種状況などについて、データを基にして分析がされて、今後に向けた取組みにもつなげているというのが、ホームページの中でも公表されておりますけれども、こういった検証・分析を行い、次につなげていく取組みも必要なのではないかと思いますが、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"第６波に向けて、保健所だけで対応するというのではなく、診断された医者のほうで患者の日々の療養を把握する、あるいは支援するといったことについても、現在、医療機関と調整中でございまして、そこもうまく役割分担ができていけるといいのではないかと考えております。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に、様々な検証・分析というのが大事なのではないかと思います。そこで品川区の状況を伺いたいのですが、品川区の第５波の死亡者・重傷者がどうだったのかということで、亡くなられた方は、感染状況、先ほども課長からもご紹介がありましたホームページを見ますと、亡くなられた方は、８月と９月２６日までで３９名となっております。それから、重傷者が何人かというのが分かったら教えていただきたい。","respondent":"鷹箸保健予防課長","answer":"その１１名のうち、基礎疾患の有無ですが、お一人で幾つも基礎疾患がある方もいらっしゃいますので、そこも含めて基礎疾患がある方が、かなりの方が基礎疾患がありまして、基礎疾患がない方で亡くなったという、申し訳ありません、そこまで統計が取れておりませんが。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう形で、どうしたら重症化や死亡者をなくすことができるかという対策が必要だと思いますけれども、初期の患者へのカクテル療法というのも、墨田区では、保健所が重症化リスクのある人を選び出して、区が確保している、墨田区の優先のベッドを使って、２８人に実施して、経過良好になったと言われておりますけれども、こういう形で品川区でもカクテル療法に。","respondent":"鷹箸保健予防課長","answer":"その違いなども含めて、医療機関のご了解が得られれば、それは不可能ではない部分もありますので、またそこは医療機関とも、常に情報交換できる関係ですので、ご相談しながら考えてまいりたいと思います。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、ぜひ公表に向けて、医師会とも検討していただきたいと思います。ワクチンについて伺います。それからもう一つはＰＣＲ検査なのですけれども、これは唾液でかなり簡単に検査できるので、高齢者施設では今でも定期的に行っておりますが、保育園でも、本当に子どもたちに密接に接しますので、定期的なＰＣＲ検査を改めて求めますが、いかがでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、鷹箸保健予防課長","answer":"保育士への接種についてですが、集団接種会場が開設された当初から、集団接種会場のキャンセル枠の分を、優先的にリストを作りまして接種していくという体制を整えまして、そのリストの方が打ち終わったと報告を聞いております。保育士への定期的な検査については、また今後の課題としていただきたいと存じます。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"特に、リスクの高い職場の方々、区の職員の方もそうですし、それから保育園、幼稚園、それから施設、福祉施設の方々、そして医療従事者も含めて、そういう方々というのは常にリスクがあるわけですから、どのぐらいの抗体価があるのだろうかというのは、やはり考えていくべき時期に来ているのではないかと思いますが、そのお考えをお聞きします。それはどういうふうにお考えになるでしょうか。","respondent":"鷹箸保健予防課長、遠藤商業・ものづくり課長","answer":"ワクチン接種後の抗体検査ですけれども、いつまでワクチンの効果が持続するのかといったことも含めまして、まだ国の方針等も不明確な部分もありますので、今後の知見なども含めて注視してまいりたいと考えております。疲弊はしておられるとは思うのですけれども、倒産までには至っていないと考えているところです。それから、いわゆる国や都の給付金の関係で、おっしゃるとおり課税対象になります。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"簡便な方法が出てきていますので、それも踏まえて考えていただきたいと思います。もらったら終わりにしてしまおうかなどというところもありますので、それは動向を見ていただきたいと考えています。どういう対応を品川区はしているのですかということです。今まで、委員からいろいろな質問をしているではないですか。なぜそれを公に言わないのですか。そこを言っているのですけれども、いかがですか。","respondent":"鷹箸保健予防課長","answer":"これまで厚生委員会では、毎回、保健所の対応についてご報告しているところですが、今、第６波に向けて、なかなか診断まで時間がかかる区民がいらっしゃるというのが、我々は非常に問題だと思っておりまして、それについては、委員ご指摘の部分と重なるのですが。","id":"exchange-065"},{"speaker":"西本委員","kind":"質問","question":"これからは安心です。情報があるとないとでは全然違います。やっているのですから、それをきちんと公表してください。そして、区民の皆さんに安心を持たせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"こんの委員","kind":"質問","question":"私からは、２８７ページ、定期予防接種、同ページで、新型コロナウイルスワクチン接種対応経費、それから２８９ページの自殺予防対策事業からお聞きしたいと思います。さて、この先です。その評価と改善の点、今後の方向性について、集団・個別・施設・訪問といった接種体制について、もう一つが、医師会との連携や接種体制について、まずこの２点をお聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ここにつきましては、今後３回目の接種に向かいまして、今のようなことが起きないようなシステムになるよう、改修もしくはシステムの変更も視野に入れながら、これから検討を進めてまいりたいと考えています。","id":"exchange-067"},{"speaker":"こんの委員","kind":"質問","question":"次にお聞きしようと思いました予約システムのことにも少し触れていただきまして、ありがとうあります。集団、個別、施設、訪問の接種状況も分かりました。次への課題等々も見据えながら、次の手だてを考えていらっしゃることも分かりました。それで、もう一つ聞きたいのが接種券の準備です。もう一つは、当日キャンセルが出た場合のワクチンの活用についてはどんなふうにお考えでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"当日のキャンセルにつきましても、週に１回、医師会、それから薬剤師の皆様、あと委託事業者の皆様等々と協議を進めている中で、どのような運用方法ができるかということも協議を進めていきながら、庁舎の中でも協力を仰ぎつつ検討を進めてまいりたいと考えております。","id":"exchange-068"},{"speaker":"こんの委員","kind":"意見","question":"そうしたことから考えると、接種券をまずは皆さんにお渡しして、それで、必ず２回目以降、８か月後となっていますので、何か早見表みたいなもの、あなたはこの時期に打った、この時期に打った人はこの時期に予約できるのですみたいな、早見表みたいなものも入れながら、全員に一気に配布するというのがいいのではないかと考えるところですが、いま一度、接種券についてだけお答えください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、一括で発送するか、段階的に発送するかというのは、今後の状況を踏まえて検討してまいりたいと考えております。","id":"exchange-069"},{"speaker":"こんの委員","kind":"意見","question":"日本小児科学会からも、そうした百日せきの抗体価の低下について、就学の前に、いま一度、ワクチンをという声があるというのも、私も見て知りました。今後、この体制について区としてどのように考えているか、お答えを頂きたいところですが、一応、時間もないので。そうしたことが分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コロナワクチン接種に関わるところで、医師会の先生方から頂いた要望で、ワクチン接種に関わる経済的負担の支援についての確認をさせていただきたいと思います。医師会の先生方から要望いただいたのですが、それについてはもう実施されているとお聞きしたのですけれども、そこの確認をしたいと思います。これら全てが実施されたということでいいのでしょうか。伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"経済的負担、経費についてのご質問です。両医師会の皆様とは、そういったお金の面につきましても、協議をずっと重ねてまいりました。国からは、真にワクチン接種に必要な経費については、全額負担するというようなお話、補助金のお話が出ております。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、ちょっと細かいところはなかなか聞きづらいですけれども、全てにおいてではないのかとは思うのですが、でもそのための費用は国から出るということでいいのでしょうか。そしてこれは、私たちは７月に要望を頂いたのですけれども、その後、いつぐらいに実施決定がされたのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"国から全額補助金が出るということで、国からは通知を頂いております。医師会とのそういった協議につきましては、夏の間ずっと、新たに発生する費用もありますので、その辺りについてはいろいろ協議を重ねた結果で、お支払いするということになりました。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。今後も、特にやはりコロナの対策においては、様々、要望に応えていただきたいですし、さらに強く連携していただきたいと思います。それで、次にインフルエンザ予防接種のほうですけれども、高齢者のインフルエンザ予防接種は、毎年１０月の時期に開始されていますけれども、１人２,５００円の自己負担があります。全額助成された下での、インフルエンザ予防接種の実施率を教えてください。","respondent":"鷹箸保健予防課長","answer":"昨年のインフルエンザ予防接種ですが、６５歳以上の対象の中で、実施人員８万３,２５６人のうち、５万３,２４２名の方が接種されまして、６３.９％でございました。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"接種率はこれまで大体４割前後で推移していました。ですので、やはり、コロナ禍ということもありますし、そして自己負担ゼロでできるという、この２つがやはり大きく影響しているのではないかと思います。６３％を超えるということで、本当にすごく驚きました。そして、状況は昨年と変わっていないのに、なぜ昨年と同様ではないのか。全額助成が継続されないのはなぜか、伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"昨年の全額助成に関しましては、直前ではございましたが、本来、区が負担するべき費用を、全て都が、重症化予防も含めて負担するという方針を出されたために、全額助成という形に変わりましたが、今年は。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"東京都から出たからやったということでしたけれども、でも状況としては昨年とは変わっておりません。昨年の１０月の感染者数と、今年の１０月の感染者数は、ほぼ変わっていないのです。なので、状況は全く変わっていないと思うのですが、その辺は、品川区から東京都に、そして東京都がやらないのであれば品川区として、全額助成できるのではないかと思うのですけれども、その状況の違いを教えてください。","respondent":"鷹箸保健予防課長","answer":"繰り返しのご説明になりまして恐縮ですが、昨年と今年の違いは、昨年はコロナワクチン接種が始まっていなかったという部分。","id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国や都がやらないのであれば、区独自で、私たち共産党は、誰もが費用の負担を気にせずに安心してインフルエンザ予防接種ができるように無料化を求めてまいりました。先ほど松本委員からも、千代田区や港区も無料でやっていると。ですので、これは品川区でもできることですし、先ほどの６３％という接種率を考えれば、十分、進めていく、実施していく効果はあると思うのですけれども、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"千代田区、港区において６５歳以上全員無料というのは、昨年と今年で変わったということではなく、もともとそれ以前から無料ですので、そこと品川区を比べていただいても検討する土台が違うかと思います。","id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コロナにかかわらず、安心に打てるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"高橋（し）委員","kind":"質問","question":"衛生費全般なのですが、予算の流用についてお伺いいたします。そこで、衛生費の第１項で、これだけ不用額、先ほどの約４億円というものが生じているにもかかわらず、項と項で流用せざるを得なかったという理由をお尋ねします。もう一つですが、同一の項の中において、職員給与費の不足が生じた場合、ほかの目からの流用はできないのか、お尋ねします。","respondent":"黒田財政課長","answer":"人件費につきましても、基本的には１課１目ですので、款の中で人件費を支出ですが、当然、不足する場合もありますので、そういった場合については、基本的には、近いと申しましょうか、性質別予算の中で必要な経費について流用するということでございまして。","id":"exchange-078"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、同一の項の中において、目と目とを流用するということなのですが、今回、第３目の保健予防費においてもこのような状況が見受けられています。ほかの項からの流用があるにもかかわらず、健康推進費にその金額以上、４,０００万円以上を流用しています。このようなことから、当初予算の組み方と予算流用のあり方について、また不一致について、財政当局のお考えをお伺いいたします。","respondent":"黒田財政課長","answer":"今回の場合、流用等が発生した理由といたしましては、新型コロナウイルス感染症の感染状況で、特に年末から年明けにかけての感染急増の中で、年度末までの執行見込みがなかなか立てられなかったと。","id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、少しお話も出てきたのですが、監査委員から、各会計決算審査を通じての意見書の中に付帯意見がございまして、健康センター指定管理料において、利用料収入の減少分を補填するため、１億円を超える事業間流用が見受けられたと。区として予算執行のあり方について、このようなご指摘を受けて、どのようにお考えになっているか、お伺いいたします。","respondent":"黒田財政課長","answer":"予算執行の考え方ですが、当然、執行状況については、各所管で、歳出状況というところで、月ごとに帳簿を閉めて確認しておりますし、企画部でも進行管理という形で確認しておりますので、そういった中で、常に予算の執行状況については把握しておりますが、当然、その動きの中で。","id":"exchange-080"},{"speaker":"高橋（し）委員","kind":"質問","question":"その利用料が入らなかったということで協議したということですが、これは今後も、そういった協議が契約事項などに記入されて、来年度以降もそういうことがあるのでしょうかということが１つ。そこと考えてみると、今回の１億円以上の事業間流用ということに関して、それとの違い、緊急性ということと考えるとまた少し違うのではないかと思うのですが、その点についていかがでしょうか。","respondent":"黒田財政課長","answer":"指定管理者等の事業者との協議という中では、当然、想定にないことは協議ということで、これから年度協定を結ぶ中で、どういった協定を結ぶかについては、各所管で事業者と様々協議がなされるものと認識しております。","id":"exchange-081"},{"speaker":"西村委員","kind":"提案","question":"３０５ページ、産業支援交流施設運営費、３０９ページ、五反田バレーについて、順不同で伺ってまいります。アクセラレーションプログラムに関しましては、例えばマニフェスト大会のようなものをと、以前、芹澤委員も提案しております。実際に、五反田バレーの理事企業から３社、既に上場していると伺っています。ＰＲのためにも、ぜひともここに力を入れていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"昨年、大きく２つの事業をやらせていただいて、１つはデジマ式ｐｌｕｓというイベントになりまして、商店街の課題に対して、各企業、それから五反田バレーの企業などに、課題に対しての解決案といいますか、そういうものを出していただいて、その後、実際に商店街と五反田バレー。","id":"exchange-082"},{"speaker":"西村委員","kind":"質問","question":"商店街と五反田バレーの取組みの中で、今おっしゃった中延商店街ですか、大変面白いと思っているのですが、２０２０年の年末からの指導かと思うのですけれども、実際に今の区民の方々の反響や実績、あと公式ＬＩＮＥアカウント（での発信）などもされていると思うのですが、その辺りも併せてお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"ウェブサイトを運用するにあたって、なかなかうまくできないというようなところが一番あったようです。そういう部分で、実際、中に入って、運用と更新等の、よりやりやすいものというようなことで、運用させていただいたというのが一つ話です。","id":"exchange-083"},{"speaker":"西村委員","kind":"質問","question":"コロナウイルスがまん延する前に、一度、五反田バレーにお話を伺ったことがあるのですが、商店街も変わらないといけないと思っていると思うのですけれどもという温度感だったと私は感じました。実際にやらなければならないという雰囲気に変わったように感じると、先日お話を伺いましたら、おっしゃっておられました。","respondent":"遠藤商業・ものづくり課長","answer":"そういう中において、今度は常に話を運んでこられない場合もあるというところで、ＩＴを使ったものがいろいろできないかというような話があって、そういう部分につきましては、私どもが昨年からやらせていただいているエリアサポーターなどでも話を聞いているところです。","id":"exchange-084"},{"speaker":"西村委員","kind":"質問","question":"どうぞよろしくお願いいたします。次に、産業支援交流施設運営費について伺ってまいります。区内には産業支援交流施設が幾つかありますが、私はいろいろな区民の方からお話を伺いまして、ＳＨＩＰが大変人気だという印象があります。大手銀行の資金調達相談会や個室もすぐに埋まるとか、３Ｄプリンタなどのある工房もコロナ禍で利用者が増えたと、区民委員会で伺いました。子連れで働ける、連れていける。","respondent":"遠藤商業・ものづくり課長","answer":"武蔵小山創業支援センターは当初から、女性に特化した部分ということで、いろいろとやらせていただいているところでございまして、特に、本来いろいろな技術を持ちながらも、なかなか子育ての関係があってできないという方も。","id":"exchange-085"},{"speaker":"西村委員","kind":"質問・要望","question":"本当に、キャッチコピーでもいいぐらい、前面に出していただきたいと考えています。例えば、しながわパパママ応援アプリで、母親層にもＭＵＳＡＫＯ ＨＯＵＳＥを知ってもらう発信を行ったり、保健センターに案内を置いていること、また区内保育園・幼稚園にチラシを配布していくなどもいいと思うのですが、ご意見をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"そういう部分も含めまして、いろいろなセミナー等がありますので、先ほどご指摘を頂きましたしながわパパママ応援アプリ、あるいは各保健センター、保育園等に関係各課と相談しながら、できるだけ周知はしていければと考えているところです。","id":"exchange-086"},{"speaker":"西村委員","kind":"意見","question":"例えばホームページを拝見しておりますと、満員御礼でキャンセル待ちというふうな、マネジャーとの相談会などがございまして、今、武蔵小山創業支援センターで人気のセミナー、満員になるほどのセミナーはどのような内容か、お聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"満員のセミナーというところで、今、コロナ禍というところで、去年から結構オンラインに切り替えたものが多くて、そういう部分については、ある程度の数が確保できるという部分と、それから先日、あれは写真か何かの関係で、Ｉｎｓｔａｇｒａｍなどに上げるとか、そういうので。","id":"exchange-087"},{"speaker":"西村委員","kind":"質問・要望","question":"ですので、そういったミニマムスタートの方を意識して広げてくださったのかと思うのですが、この表現が少々分かりづらいと思っておりまして、例えばなのですが、本当にこれは私の意見なのですけれども、卵でひよこで鶏みたいな、そういったイラストで表現していただくとか、何か、スタートアップの中でもセグメントされますので、ターゲットがもう少し分かりやすいように。","respondent":"遠藤商業・ものづくり課長","answer":"委員の、卵、ひよこ、鶏というところをご提案いただいたところですけれども、いろいろな案が出ようかと思いますので、できるだけ伝わるような、いろいろな表現を考えていきたいと考えています。","id":"exchange-088"},{"speaker":"西村委員","kind":"意見","question":"その表現がいいのかどうかはぜひとも熟考いただいてと思うのですが、ご検討をお願いしたいと思います。もう一点だけ、この間、区民委員会で視察に行かせていただきましたが、西大井創業支援センターのほうです。若者をどうやって西大井に呼び集めてくるかというようなところで、何か戦略がございましたらお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"西大井は、神奈川県からも通いやすいというところがありますので、そういう方が品川区で起業されるようなところも想定して、ちょっと遠くのほうの大学などにも声をかけていきたいと思っているところです。","id":"exchange-089"},{"speaker":"西村委員","kind":"質問・要望","question":"確かに西大井駅には横須賀線も相鉄線も湘南新宿ラインも、いろいろ通っていて便利なのですが、なかなか若者はチラシなどを見ないという現状もありますので、ぜひＳＮＳも戦略に取り入れていただいて、若い方たちに知っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"木村委員","kind":"質問・要望","question":"メードイン品川ＰＲ事業からの質問を致します。これまでにいろいろな品川ブランドがあると思いますが、メードイン品川ＰＲ事業は平成２４年度から始まった事業ですが、幾つの製品が世に出たのか、ご紹介ください。そして、中には世界に誇れるような製品もあろうかと思いますけれども、お聞かせいただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"メードイン品川ＰＲ事業です。こちらは、件数といたしましては、今まで３１件の認定をさせていただいたところです。こちらは、様々な形で企業に使っていただいているところです。","id":"exchange-091"},{"speaker":"木村委員","kind":"質問・要望","question":"区内景況と、新型コロナウイルス感染症に伴う支援についてでありますけれども、現在の区内事業者の状況と、新型コロナウイルス感染症に伴う各企業への影響と支援についてお尋ねいたします。現在の区内企業の景況についてお聞かせいただきたいのと、今後の景況感についてどのように考えていらっしゃるのか、お聞かせいただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"逆に１０月になりまして、緊急事態宣言が解除になったところです。既に、区内といいますか、全般的な景況としては、マスコミ報道という形になりますけれども、かなり動き始めているのかなというところがありますので、このままどんどん改善していけばいいと考えているところです。","id":"exchange-092"},{"speaker":"木村委員","kind":"意見","question":"３０９ページの、販路拡大支援事業の新型コロナウイルス感染症対応特別助成等について、事業者から申請された件数と、助成した金額、また申請された事業者はどのような事業者なのか。例えば飲食業の方からの申請はあったのかどうか。あわせて、今年度も引き続き、こちらの新型コロナウイルス感染症対応特別助成は行われたかと思いますが、今年度の申請状況についてもお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"当初、１期ということで５００件ほどを見込んでいたところ、６００件を超える申請を頂いたところでございまして、現状については少し不足を、予定より多く申請頂いているところでございまして、今年につきましても、比較的使っていただいている事業なのかと考えているところです。","id":"exchange-093"},{"speaker":"木村委員","kind":"質問","question":"そこでお伺いいたしますけれども、昨年度から多くの商店街のイベントが中止となる中、今後、アフターコロナまたはウィズコロナにおいて、商店街のイベントを復活させるためには、どのような課題があり、またどのような対策をされるのかをお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"今後の対策ですが、今年度につきましては、エリアサポーターを中心に、イベント実施に向けて商店街課題解決支援等を行うとともに、今、随時のイベント助成金が可能になります品川区商店街ホリデー・トレーニング事業を、助成率を３分の２から５分の４に引き上げたところです。","id":"exchange-094"},{"speaker":"大沢委員","kind":"質問・要望","question":"２９５ページの項目、品川区立環境学習交流施設を中心に聞かせてもらいます。それと、２９７ページ、ワンウェイプラスチック削減ということで、今日は淡々と質問させていただきたいと思います。このところで、まず環境学習交流施設、来年５月ということですけれども、メインとなるコンセプトやテーマというのは何なのでしょうか。教えてください。","respondent":"河内環境課長","answer":"環境に対して興味の薄い方も関心を持っていただけますようにということで、大型映像施設を用いた展示から、それから興味関心をさらに強めていくために常設の展示などもちりばめまして、あるいは時間の軸の中で、１秒で何が起こっている。","id":"exchange-095"},{"speaker":"大沢委員","kind":"意見","question":"資料等々にも書いてありますが、想定する対象をどのように考えていらっしゃって、中に大型展示施設があると思うのですけれども、これは学習施設だから、おのずと子どもたちが対象になると思うのですが、これについて、彼ら彼女らが余計理解しやすいように、どのような工夫を施すように考えていらっしゃるのか、お願いします。","respondent":"河内環境課長","answer":"中には、大人の方に、環境に対して少しシリアスに考えさせるような内容もありますが、昭和初期から現在までの、歴史的とは言いませんけれども、古い取組みなども扱うなど、お子さんと一緒にいらっしゃった親御さんや、おじい様。","id":"exchange-096"},{"speaker":"大沢委員","kind":"質問","question":"詳しい説明をありがとうあります。ＺＥＢについて少し聞きたいのですけれども、ＺＥＢ以外のネット・ゼロ・エネルギーというのはほかに何があるのですか。教えてください。","respondent":"河内環境課長","answer":"エコルとごしにつきましては、ＺＥＢの中でも７５％以上ということで、Ｎｅａｒｌｙ ＺＥＢを取得しているということで、区内の中でも有数のものですので、こういった魅力を活かしながら、他のＺＥＢについても普及促進に努めていきたいと考えているところです。","id":"exchange-097"},{"speaker":"大沢委員","kind":"質問","question":"最初に聞かなければいけなかったのですけれども、エコルとごしということですけれども、募集方法など、どのぐらい応募があったのか。それでまた、応募された方はいろいろな思いを込めて応募されたと思うのですけれども、その思いについて、課長はどのように捉えられているか、教えてください。","respondent":"河内環境課長","answer":"お子様からの応募も大変多かったという点で、募集方法につきましては、広報しながわ、ホームページなど、あるいは、三木小学校、大原小学校、宮前小学校、戸越小学校、豊葉の杜学園など、近隣の学校と連携しながら、こういった広報を進めたところです。","id":"exchange-098"},{"speaker":"大沢委員","kind":"質問","question":"ぜひお願いします。プラスチック削減についてですけれども、エコルとごしではワンウェイプラスチック削減についてどのような取組みをされるのか、教えてください。","respondent":"河内環境課長","answer":"こういった脱プラスチックといいますか、プラスチックの削減に向けて、非常に大事な取組みだということをお子さんたちにいろいろ伝える必要がありますので、特に海洋プラスチックの面も、お子さんたちに伝えなければいけないことと認識しておりますので、今。","id":"exchange-099"},{"speaker":"大沢委員","kind":"質問","question":"では最後の質問になりますけれども、ハクビシンについて聞かせてください。カラス、外来種、ここは先ほどページ数を言いました２９５ページに入っていますけれども、過日、都内のどこかでサルが大暴れしたということで、品川区内ではハクビシンが増えているということを承知しておりますけれども、目撃件数や捕獲件数を教えてください。","respondent":"河内環境課長","answer":"そういった情報に基づきまして、捕獲というところで、箱わなを設置いたしまして捕獲いたしますが、令和２年１年間で９件、また令和３年では８月末現在で１件です。こういった情報につきましては、平成２８年度より、駆除の総合窓口などを用いまして……。","id":"exchange-100"},{"speaker":"中塚委員","kind":"質問","question":"２９３ページ、区有施設の二酸化炭素排出量分析委託に関わって、品川区有施設でのＣＯ２排出削減を伺います。３１１ページのマイスター店等支援事業に関わって、飲食店支援について、それぞれ伺いたいと思います。区有施設のＣＯ２削減ですけれども、改築、建て替え、大規模改修の際の省エネ、空調の取替えなどに、どのように取り組んでいるのか、伺いたいと思います。","respondent":"河内環境課長","answer":"その際、設備の寿命が来る来ないというところがありますが、設備の改修時期に合わせまして、大規模改修ならびに新築のときに、そういった省エネ機器の検討を行いまして、随時、置き換えていくというようなところをもちまして、まずは省エネに努めてきているところです。","id":"exchange-101"},{"speaker":"中塚委員","kind":"質問","question":"建て替えや大規模改修などのときに、省エネを思い切って活用することは重要だと思います。同時に、そこまでの大規模な工事でなくても、ＬＥＤを含めて、どこでどう電力使用量を減らすことができるのか、日々、探すことも必要だと思いますけれども、現状の取組みを伺いたいと思います。そして、省エネと併せて再生可能エネルギーの普及も、従来の規模を超えて区有施設の活用が必要だと思います。","respondent":"河内環境課長","answer":"再生可能エネルギーの件ですが、特に太陽光パネルの件で新築をというお話がございました。私どもへの太陽光パネルの申込者におきましては、比率として６５％の方が、やはり新築の方がというところで、後から乗せるとなると荷重的な問題もあって難しいという認識です。","id":"exchange-102"},{"speaker":"中塚委員","kind":"質問・要望","question":"区有施設のことを伺っているのですけれども、新規の場合も、従来の施設の場合も、再生可能エネルギーの普及をしっかりと位置づけていただきたいと思います。相次ぐ巨大なオフィスやタワーマンションを造る再開発に対して、気候危機打開の観点からも、新規事業は規制していく、抑制していくという対応が必要だと私は思いますが、いかがでしょうか。","respondent":"小林施設整備課長、河内環境課長","answer":"私から、区有施設の太陽光発電の設置の現状についてご説明いたします。新規施設につきましては、設計等を行っていく中で、太陽光発電システムを乗せられるか乗せられないかの検討については、十分に行っているところです。再開発におきまして、新しい施設というところで、熱源設備など新しい技術を用いますとＣＯ２の削減につながることもあるということで、ストレートに規制というところでは、考えとして持っているものはございません。","id":"exchange-103"},{"speaker":"中塚委員","kind":"質問・要望","question":"飲食店の支援について伺いたいと思います。そこで、例えばテイクアウトについて、品川区も関わって、飲食店を紹介することなどを考えていただきたいと思います。商店街でも様々努力は進んでおりますけれども、コロナの状況の下で厳しい中、テイクアウトを紹介して、お店の売りや味を知っていただいて、コロナ収束後の来店につなげることに期待したいと思いますけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"飲食店の支援という部分ですけれども、昨年の４月からなのですが、品川区商店街連合会と連携させていただきまして、しながわＴＡＫＥＯＵＴ ＭＡＰというアプリを立ち上げまして、それをご利用いただいているところです。","id":"exchange-104"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、いろいろ支援を進めていただきたいと思うのですけれども、レストランやトラットリアやバーやスナックや大衆居酒屋や食堂やラーメン屋や居酒屋の灯を消してはいけないと考えています。それだけに、支援を強めていただきたいと思うのですけれども、飲食店の役割について、品川区はどのように考えているのか、今後の支援の強化もご検討いただきたいと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"いろいろな支援を、民間も含めてやっているところですので、その辺と連携しながら、ぜひ飲食店の灯を消さないような形で施策をやっていくような形で努めてまいります。","id":"exchange-105"},{"speaker":"中塚委員","kind":"質問・要望","question":"食は文化であり、飲食店は社会の潤滑油だと、私も思います。コロナ危機がここまで長期化していて、そもそも飲食店業界というのは１０年後の生存率がとても低いのです。その中で残っているお店が今もう休業または廃業に追い込まれようとしている。それだけに、支援の強化が急がれると思います。ぜひ様々なことを具体化していただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は、２９７ページの資源回収、それから２９９ページのリサイクルショップ運営費、それから３０９ページの商店街活性化事業費でお聞きします。それから、リサイクルショップ運営費は、リサイクルショップ「リボン」です。いろいろ、区で考えがあるという中です。そこには全部は出せないのでしょうけれども、このようなお店が使えますよというのをどのような形で考えていらっしゃるのか、教えてください。","respondent":"品川品川区清掃事務所長、遠藤商業・ものづくり課長","answer":"リボンの件につきましては、これから広報を１０月に行っていきたいと考えています。それで、年間のスケジュールとしましては、今年度末をもちまして閉店というようなスケジュールで進めていきたいと考えています。この店は３０％還元をやっていますというポスターやチラシのようなものを店舗に貼っていただくようになっている部分と、それから当然、アプリを入れていただいていますので。","id":"exchange-107"},{"speaker":"たけうち委員","kind":"質問","question":"そういう中で、やはりもう少し積極的に、ＰａｙＰａｙから情報をもらえないのですか。少し不親切だと思うのだけれど、どう思うか。それから、レアメタルです。ただ、小型家電を目立たないで置いておくよりは、せっかくやっているのだからということで、ぜひ区は、そんなにお金がかからないのですから、ぜひ積極的に、これは早急にやってもらったらいいのではないかと思うのですが、お話を伺いたいと思います。","respondent":"品川品川区清掃事務所長、遠藤商業・ものづくり課長、佐藤企画調整課長","answer":"これにつきまして、東京都と２３区が行っているかどうかというところも１つ確認するところと、それからやはり大切なところとしては。当然、途中でやめてしまう店舗や、あるいはこれから入ってくる店舗もありますので、その場合にどう更新していくか。リサイクルショップ「リボン」跡の活用についてです。委員ご指摘のとおり、周辺環境、建物の状況や、立地や広さも含めて、今後検討を進めてまいります。","id":"exchange-108"},{"speaker":"芹澤委員","kind":"提案","question":"私からは、２９５ページ、環境啓発・推進事業、３０９ページ、販路拡大事業、３１１ページ、商店街にぎわい創出事業についてお伺いします。環境啓発・推進事業でリサイクルについてお伺いします。例えばですけれども、これは具体的な提案になりますが、今、我々の目の前にあるアクリル板のリサイクルをぜひ検討していただけないかという趣旨でご提案します。","respondent":"品川品川区清掃事務所長","answer":"ただ方法となりますと、いろいろと、これはかなり情報を集めてやっていかなければいけないかですので、何かいい方法等がないかというところは、今後研究していきたいと考えております。","id":"exchange-109"},{"speaker":"芹澤委員","kind":"質問・要望","question":"あれは本当に真っ白、透明なグランドピアノなのですが、あれもアクリル樹脂からできているそうなのです。ぜひ、それはもう一度、ご見解をお聞かせいただきたいのと、あと追加で、先ほどのお話のところもそうですけれども、区内の商店街にもやはりこういったもの、先ほどお話しいただいた法人であったり、店舗もかなりの数を持っていて、これも多分いずれ捨てるのだろうと思うのです。","respondent":"品川品川区清掃事務所長","answer":"先ほどお話ししたとおり、リサイクルは非常にしやすい素材ではあるということもありますので、答弁が重なりますが、いろいろな方向から研究は進めていきたいと思います。うまく地域等と絡める方法等といったところも含めて、いろいろと研究していきたいと思います。","id":"exchange-110"},{"speaker":"芹澤委員","kind":"質問","question":"ぜひ前向きにご検討いただければと思います。では、次に、販路拡大事業についてお伺いします。新型コロナウイルス感染症対応特別助成として、かなり、何回か数を分けて、今やっていらっしゃると思いまして、１０月１日から再び募集になっています。新型コロナウイルス感染症対応特別助成という名前で、コロナウイルスが明けた後のこれからの展開というのを、まずご見解をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの助成金です。当初、販路拡大支援助成という名前で非常に分かりづらいというようなことも受けまして、途中から、第２回目からは新型コロナウイルス感染症対応特別助成と名前を変えさせていただいて、広く周知に至ったです。","id":"exchange-111"},{"speaker":"芹澤委員","kind":"質問・要望","question":"まさにそれが私の要望でありまして、まず５分の４の補助金というのはぜひ続けていただきたいという思いがあります。その中で、おっしゃるとおり、これからアクリル板を買うとか、空気清浄機に１５万円、２０万円というのは、少し違うのかと私は思っていますので、ぜひ積極的な、前向きな投資の補助をしてあげる。営業の補助というのですか。改めてご見解をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"先ほどの、新聞販売組合とのポスティングの協定みたいな形になるかと思うのですけれども、そういう部分、実際にどこまでできるかというところはありますけれども、いろいろな形で企業の支援につながっていくような施策を検討していきたいと考えています。","id":"exchange-112"},{"speaker":"芹澤委員","kind":"質問・要望","question":"あわせて、今、個店の支援というようなお話を頂きましたが、商店街単位で、商店街、地域のご支援というのもぜひご検討いただきたいと思っていまして、商店街自体も結構、イベントもなかなかずっとできない中で、どうしたらいいのか分からない、商店街のつながり、もしくは商店街のブランドを守れないというような声もあって、例えば商店街のエリアサポーターの皆さんもやっていらっしゃるのですが。","respondent":"遠藤商業・ものづくり課長","answer":"その中で話が出た段階で、商店街のほうから、こういうものをやっていきたいというときに、専門家を派遣する制度があります。それは費用助成という形になりますので、そのようなものを使って、それぞれの特徴を出しながら、商店街の振興につなげていければと考えております。","id":"exchange-113"},{"speaker":"芹澤委員","kind":"提案","question":"多分、商店街として、目黒区で加盟はしているのですが、その商店街が品川区にも延びているということなのだろうと思うのですが、品川区の商品券の加盟店リストを私が見た限りですと、品川区内の店舗しか存在していなくて、それがどういった基準になっているのか、お聞かせいただきたいのと、あわせて、当然ですが、拡充していただきたいという思いでご提案していますので。","respondent":"遠藤商業・ものづくり課長","answer":"今、意見、お話を頂戴いたしましたので、そこにつきましては商店街連合会に伝えていきたいと考えています。","id":"exchange-114"},{"speaker":"大倉委員","kind":"質問・要望","question":"平成２２年度には最終回ということで、マイスター店を全部選び終わって進んできている中で、この約３００万円は毎年、毎回出てくるのですが、こうした中で、この成果というのは、どのように捉えていますでしょうかということと、現在の店舗数や、その辺を教えていただければと思います。次に、伝統的産業の振興で、これは今、どのくらいの数があるのでしょうか。教えていただきたい。ごみについて伺います。","respondent":"遠藤商業・ものづくり課長、品川品川区清掃事務所長","answer":"今後、ＳＮＳを活用したものが、今、集客という部分で大きいところがありますので、その辺に含めまして、今、検討を進めているというような状況です。ごみの分別です。やはり啓発の部分では難しいところの部分ではないかと考えています。","id":"exchange-115"},{"speaker":"大倉委員","kind":"質問・要望","question":"それで、以前の記事を読むと、商店街を個別支援するという、なかなか結構画期的な取組みだったということを伺ったのですが、コロナ禍で今、商店街や各商店が結構厳しいというお話が、るる、今、決算特別委員会でもお話しされている中で、こうした地域の魅力ある店舗を改めて集めて、こうした形のものをつくっていくというのも、考え方としては１つあるのかなと思うので。","respondent":"遠藤商業・ものづくり課長、品川品川区清掃事務所長","answer":"いろいろな方法があるかと思いますので、今後も検討していきたいと考えています。そういう啓発の一環として、強化月間というのも１つの考えとして参考にしていきたいと考えております。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問","question":"私は、３０３ページ、産業振興経費と、中小企業経営支援事業費についてお聞きしたいと思います。まさに、いつ倒産するか分からない状況にあります。区内産業の実態について、またお聞きしますが、認識を教えてください。そして、今、区がこれを改善するために取り組んでいる有効な、中小規模の商店や事業所への支援は何なのか、教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"現在の産業に関する認識ですけれども、景況調査などをやらせていただいて、あるいは、区ではありませんけれども、ほかのところの情報などを見る限り、なかなか現在においても感染症の影響が出ていて、厳しい状況ではあるというところは認識しています。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"実際、様々な支援、また助成金で、産業振興事業費助成金、それから中小企業経営支援事業費、そして雇用確保支援事業、それから産業支援交流施設運営費等、あと就業支援費ですか、様々なものを支援しています。コロナによって、品川区が様々な支援事業をすることが、これはかなり、意味が、完全に効果がなくなったのではないかと思うのですが、その辺についてご見解をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"そちらがなかなか難しいということで、こういう助成をさせていただいた結果、雇用が引き続き保たれたというような場面もあろうかと思いますので、そのほかにつきましても様々いろいろありますけれども。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"本来、企業は、営業活動、また商売をやるにあたって、何が一番、産業振興になるかということは、最初はあれですが、実際、コロナ感染をできるだけ拡大させないように工夫して、商売が継続できるようにすることではないでしょうか。ですから、最優先として、商売が継続できるようにするような方向に、この支援金、そして様々な助成云々のほうに予算を投入すべきだったのではないでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"ただ一方で、まずそれをやらない限りは現状維持ができないということで、融資なども拡充させていただいたところです。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"これは仕方ないことだと思います。情報はあったと思うのですが、これを認証するように都が動いていることに対して、品川区は何か支援をしてきたのでしょうか。例えば１軒ずつ回って、改善をしてください、感染リスクを減らすように努力してください、そういう対応をしたのでしょうか。商業・ものづくり課で、この制度に際してどのような協力・対応をしたのでしょうか。ご見解をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"今も順次、都で回っているですので、引き続き、何らかの形、いろいろな方向で、こちらを推奨するような形で努めていきたいと考えています。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"本来なら東京都がやるべき仕事なのかもしれないのですけれども、私は、やはり東京都から予算を頂いて、地元、身近な自治体として、品川区が各商店街を、回れるかどうかはあれですが、１軒ずつ回る。改善させていくべきだったのではないのでしょうか。その辺について、もう一回ご見解をお聞かせください。でも、これだけでは駄目なのです。入店の際、ワクチン接種証明や陰性証明を提示する。","respondent":"遠藤商業・ものづくり課長","answer":"その部分も含めて、認証店等の制度につきましても、都でいろいろ検討されてつくられたものでございまして、正直、その内容について私どもも特に東京都から伺っているわけではなく、どちらかというと、こちらでホームページを見ながら。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"すみません。やはりお客さんがどうなのだと。そして、先ほど、東京都のほうなので、なかなか区のほうの我々が関わることは難しいという話ですが、実際、学校でも庁舎でも、様々な区有施設で、それなりの感染対策を実行しているではないですか。だったら、小さな、中規模の商店に対しても、産業振興として、経営支援として、しっかりやるべきだったのではないのでしょうか。ご見解をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"それにプラスアルファして、いわゆるワクチン接種証明書を用いるなどというのは、なかなかこちらでそこまで推奨するというのは難しいのかなとは思っているところですが、いろいろな店舗で考えていただければと思っているところです。","id":"exchange-122"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、先ほどからお話が出ていますけれども、ワクチン接種が全世界に行き渡るまで、コロナは５年、１０年かかるわけです。恐らく終息しないかもしれない。この間、コロナが変異している以上、日本でもそういうことがありますので、私は末永く共存するということを考えて対策をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"のだて委員","kind":"質問・要望","question":"一般質問で、共産党区議団として、持続化給付金、家賃支援給付金の２回目の支給を国に要望するよう求めましたが、区は、特別区長会から国に要望しているとして、区として要望する考えはないと答弁しました。既に半年が経っていますが、いまだに実現していないのに、なぜ改めて区として国に要望することを考えていないのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"持続化給付金の再度の要請というお話かと思います。なかなか持続化給付金、当初、国に対して特別区長会で要望させていただいたところです。その後、状況等も変わったところもあって、今は特別区長会からも要望などをしていないような状況だったかと認識しております。","id":"exchange-124"},{"speaker":"のだて委員","kind":"質問・要望","question":"特別区長会が求めたのは、令和３年度、今年度の予算要望ということで、それでまだ実現していないという状況です。しかも、令和４年度、来年度の予算要望では、特別区長会は持続化給付金を求めていません。なので、やはり区として２回目の持続化給付金、家賃支援給付金を求めていただきたいと思いますが、いかがでしょうか。２回目の支給で、区内の事業者を助けることになるとは思わないのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"直接給付というところについては、一定程度、終わったといいますか、収まっているのかというところがあります。そのほかの給付金がありますので、そちらで十分というわけではございませんけれども、そちらで対応いただく形になろうかと考えているところです。","id":"exchange-125"},{"speaker":"のだて委員","kind":"質問・要望","question":"給付だと経済を回せないというようなご答弁がありましたけれども、そんなことはないと思うのです。事業者の方々が給付を求めているというのは、やはり収益が出ていないということだと思うのです。そうすると、やはり結局、貯蓄を切り崩したりということで、消費はしなくてはいけないわけです。なので、経済は回ると思うのです。給付もぜひ、区として考えていただきたいと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"例えば私どもの新型コロナウイルス感染症対応特別助成であれば、ほかの何かを購入するという話になります。","id":"exchange-126"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ直接給付を考えていただきたいと思うのですが、経済が回らないということはないと思います。昨年の持続化給付金のような大きなお金が欲しい。９割以上が休業となり、苦しい。特定の業種にかかわらず、様々な影響が出ていますし、やはり給付を求めているという声が、この中にも出ていると思います。こうした困っている中小企業へさらなる支援が必要だと思わないのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"そういう部分では、私どもといたしましては、広く全ての業種が使えるような施策といいますか、支援を考えざるを得ないかというところで、かなりの金額になりますけれども、融資あっせんなどを大幅に拡充して、恐らくほかの区と比較しましても。","id":"exchange-127"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用した支援策で一番多いのが持続化給付金で５８.９％、２番目が国の家賃支援給付金で３３.９％です。多くの方が利用されて、つまり助かったということだと思いますので、２回目の実施が求められていると思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"繰り返しになりますけれども、現在、既に緊急事態宣言が終わりまして、今後は経済をより前向きに向けていくというような支援が望まれているところだと考えていますので、持続化給付金について国に要望する考えはございません。","id":"exchange-128"},{"speaker":"のだて委員","kind":"質問・要望","question":"持続化給付金を支給したら前向きではないということはないと思いますので、ぜひ区としても要望していただきたいと思います。一般質問では、区独自の月次支援金の上乗せも求めました。先ほど、声も紹介しましたけれども、現在の支援で十分だと考えているのでしょうか、伺います。負債が少なければ出てこないということです。なぜ月次支援金の上乗せをしないのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"月次支援金ですけれども、こちらは国の制度ですけれども、東京都がさらに上乗せを給付されているですので、そちらのほうで足りているのかと考えているところです。","id":"exchange-129"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は地域の商店の方にもお話を伺いました。貯金を崩しながら何とかやっていると。５０％も売上が落ちたらやっていけないのだということで、支援の拡充を求めていました。やはり、こうした状況で、貯金を崩しながらやっているわけですから、続いていったら閉店にもつながるということになるのです。都も対象拡大などもやっています。そうしたところで、区もぜひ上乗せをしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２９３ページ、省エネルギー対策事業、２９５ページ、アスベスト対策事業、３０７ページ、商店街店舗ＩＴ導入支援について、お聞きしたいと思います。初めに、２９３ページ、省エネルギー対策事業の中の、太陽光発電システム設置助成についてお伺いします。３５件がどういう内訳になっているかをお聞きしたいと思います。お願いします。","respondent":"河内環境課長","answer":"業務用については、令和２年度１件です。同様に、家庭用の令和３年ですが、９月末現在で８件、業務用が２件という状況です。おのおの、kW数が、３kWと５kWの上限を設けておりまして、そういう運用をやりながら、温暖化防止に努めているです。","id":"exchange-131"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。やはり、地球温暖化対策ということで、これからもっと啓発していかなくてはいけないという中で、当然、コロナ禍でなかなか啓発もできないと思うのですけれども、特に家庭を中心にするのか、あるいは事業所、両方だと思うのですけれども、そこが事業所なのか、ご家庭に対しての啓発を重点的にやるのかというところを教えていただきたいと思います。","respondent":"河内環境課長","answer":"家庭、事業者ともに、両方とも非常に大切だと思っているところではありますが、役割が少し異なってきているという認識です。","id":"exchange-132"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ぜひとも、また継続して取り組んでいただきたいと思います。２９５ページ、アスベスト対策事業についてお伺いします。その助成なのですけれども、除去の助成は、令和２年度はゼロということだと私は認識しておりますけれども、これは昭和６０年以前に建築された建物というのは、まだまだ相当数存在していると思うのです。","respondent":"河内環境課長","answer":"東京都の資料によりますと、そういったものが、令和１０年をピークにしながら、トータルで８,０００件から９,０００件というようなところで予想されているところでございまして、今後もきちんと対応していきたいと考えているところです。","id":"exchange-133"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。調査助成もあると思うのですけれども、調査は業者に委託されておられると思うのですけれども、そのとき所管の職員も、当然同行はしていると思うのですけれども、いかがでしょうか。","respondent":"河内環境課長","answer":"幅広く迅速にやるために、まず業者の派遣、それからその報告を受けまして、必要に応じて、例えば防護服を着た職員が行くなどといった形で、多くの数がこなせるようにということで、工夫しながら対応しています。","id":"exchange-134"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。続いて３０７ページ、午前中も質疑があったかと思うのですけれども、商店街店舗ＩＴ導入支援についてお尋ねしたいと思います。先ほどのご答弁ですと、令和２年度限定で、ホームページ改修などというのがあって、個店を中心にして４４０件の応募に対して、私が間違えていたらすみません、抽選の結果、５０件ということだったと思うのですけれども、もう一度教えていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは、ＩＴサポーターは１５人いたのですけれども、そちらが各商店を中心に回って、４４０店を訪問させていただいたところです。その中で、いろいろ御用聞きなどをさせていただきながら、特に支援を希望される５５軒に対して、個別の支援を行わせていただいたというものです。","id":"exchange-135"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。これは２点お聞きしたいのですけれども、令和２年度限定というのは、今年はなぜやらなかったのかということと、当初予算の２２５万円に対して、決算が９００万円ということなので、これは大幅に増えたということで理解はしているのですけれども、そこの２点を確認させていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"予算につきましては、こちらは当初、２２５万円のほうは、商店街店舗の事業を、実際にＩＴを導入した場合の助成金として計上させていただいたところなのですけれども、こちらは例の新型コロナウイルス感染症対応特別助成金を補正予算で頂きまして、こちらと中身が同じ。","id":"exchange-136"},{"speaker":"塚本委員","kind":"質問・要望","question":"エコルとごし、今、建設が進んでおりますけれども、この建物自体をＺＥＢという、環境に配慮した建物で、まず建物自体をＺＥＢ化して、環境への啓発・理解を広めていくという狙いを持っているということですけれども、地中熱というものを活用して、ＺＥＢというものをどのように実現していくのか、地中熱の活用というのは一体どういうものなのかということで、初めにお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"施設建設の技術的なご質問ですので、施設整備課でお答えいたします。地中熱ですが、地盤内に存在する熱のエネルギーのことを示します。大気中の温度に対しまして、地中の温度というのは、一定の深さになりますと、年間を通じて非常に温度の変化が見られなくなるものです。","id":"exchange-137"},{"speaker":"塚本委員","kind":"質問","question":"私もホームページなどで調べたのですけれども、地中熱による、いわゆる空調ですか。幾つか方式があるみたいで、ヒートポンプシステムという中で、クローズドループや地下水を使ったオープンループ、それぞれ多分、メリット、デメリットとあるのでしょうけれども、どういった方式を採用しているのか、また採用した理由等は何なのかなど、もう少し詳しく説明していただけますでしょうか。","respondent":"小林施設整備課長","answer":"様々な方式があるところではありますが、今回、設計を進めていく中では、地中熱や、あるいはＺＥＢなどに対する、ある程度、一定の経験がある設計事務所からいろいろな提案をされた上で、今回一番効率的な方法ということで、クローズドループを使わせていただいたところです。","id":"exchange-138"},{"speaker":"塚本委員","kind":"質問","question":"地中熱によって空調を賄うと、もちろんＣＯ２の削減、電力の削減になるのですけれども、またメリットとしては、エアコンの排気熱というものが出ないというところがあるので、ヒートアイランドと言われている都市部でこういったものが広がっていけば、このヒートアイランド現象を抑制する、解消するというところにもメリットがあるというようなことがあるということですけれども、区内に今後、区有施設や。","respondent":"小林施設整備課長","answer":"今回、環境学習交流施設は比較的、区有施設の中でも中小規模の建物でございまして、この活用というのは、区の施設の中でも初めての取組みですので、まずは施設完成後の利活用の状況や実績、それから効果等を検証して、今後の施設づくりに活かしていきたいと考えています。","id":"exchange-139"},{"speaker":"塚本委員","kind":"質問","question":"環境学習交流施設につきましてはＺＥＢというところで、過去の議論の議事録などを見ると、７５％でＮｅａｒｌｙ ＺＥＢというところで、７５％を、ある意味、省エネしているという形で運営するというようなことになっていますけれども、残りの２５％はなぜ残ったのか、できなかったのか、あるいは２５％のところを１００％にし得なかったところというところを、最後にお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"設計をしていく上で、１００％を目指したいという気持ちは、やはり我々技術職としても思っていたことです。","id":"exchange-140"},{"speaker":"塚本委員","kind":"質問・要望","question":"今回、１０月になって、緊急事態宣言が解除されたのですけれども、休業していた飲食店等が、宣言解除後に人員というものを、なかなかすぐに確保できないということで、人が集まらないというか、人をもう解雇しているというか、いないので、急にフルな形で開業できないというような声も幾つか伺いました。最初に、雇用環境整備事業助成はどういった内容の事業であったのか、お伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"雇用環境整備事業助成金の内容ですけれども、昨年の４月１日から実施させていただいた事業でございまして、基本的にはテレワークの導入に係る経費、それから休暇や時差出勤などの規定整備、就業規則の改定です。","id":"exchange-141"},{"speaker":"塚本委員","kind":"質問・要望","question":"業態の変更というのは、特に大事な視点かと思うのですが、そういった業態変更等の支援について、特に広く知見を求めるような形で、いろいろな方々から、なかなか今までの商業・ものづくり課の中だけでの検討では及ばないような知見を求めていかないと、ニーズにきちんと合った支援策というのはなかなか出てこないのかなとも思いますので、そういった点も含めての、今後の支援策の検討。","respondent":"遠藤商業・ものづくり課長","answer":"当然、中小企業診断士が経営相談にも乗らせていただいて、どのような形でやっていくのかというところで、ある程度、知見は持っているところですけれども、今、委員からご指摘がありました、今回特別なといいますか、新たな部分があるかと思いますので。","id":"exchange-142"},{"speaker":"渡辺委員","kind":"質問","question":"２９５ページ、環境啓発、それと３１１ページ、商店街エリアサポーターの２点を伺います。その中で、長期基本計画の中での環境を取り上げているページ、これが策定されたのが、昨年、令和２年の４月だったのです。恐らく世代、性別、職種で、ちょっとニュアンスが違うかもしれませんが、環境保全という観点で、やはりターゲットを絞るべきと私は思っていますが、その辺の考え方をまず教えてください。","respondent":"河内環境課長","answer":"そういったときに、その時点の当事者になる子どもたちについて、しっかりとした認識の中でやっていただきたいということで、そういったところを太くしていきながら、メッセージを届けてまいりたいという考えで、今、進めているところです。","id":"exchange-143"},{"speaker":"渡辺委員","kind":"質問","question":"今年、報奨金の増額などが行われて、現場からの感謝の声がモチベーションにあったかと思います。これはどう言ったらいいのでしょう。やはり今、いろいろな数値目標がある中で、もっと協力者が増えてほしいはずだと思います。すごく使命感と、あと年齢も含めて頑張っていらっしゃる姿があるのですが、何か大きな仕掛けも含めて、担い手不足を突破できるようなことの対策、ヒントでもあれば教えてください。","respondent":"品川品川区清掃事務所長","answer":"こういうところも進めながら、集団回収を行っていきたいと考えています。","id":"exchange-144"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それと、環境省の動き。でも、ここに載っていた中で、想定されるポイント対象となる５分野、それは住まいであったり、食であったり、衣類であったり、循環、移動であったりと、今日もいろいろな質問が出ていました。何が言いたいかというと、国は国だけど、このキーワードを基に、品川区がもう一段かませられないかというところで伺います。方向性を教えてください。以上、この辺を伺えればと思います。","respondent":"品川品川区清掃事務所長、河内環境課長","answer":"それと、繰り返しになりますけれども、報奨金を上げたところで、その状況についても検証していくことが必要かと考えています。こういったところを委託化も含めまして検討していきながら、まず全体の５分の１が再生可能エネルギーと言われているところがありますので、今後増えるといいながらも、排出係数と価格について。","id":"exchange-145"},{"speaker":"渡辺委員","kind":"質問","question":"導入して初年度なので、テスト的な意味合いもあって、どうしても初年度というのは、いろいろな効果や検証をしなくてはいけないと思っています。というのは、もう丸々１年間、コロナ禍で対応に追われた年度なので、相当、事業目的上、難儀したと思います。これは１年で終わる話ではなくて、当然ながら、事業の中には、３年物、５年物とか中長期があると思います。その辺のあらましを教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"エリアサポーター事業を昨年度から実施させていただいて、本来ですと１０の商店街のモデル地区を選定して回るということで進めていたところですが、コロナで全て疲弊したということで、全部回るというような形で、それぞれサポーターが伺ったところで、やったことといたしますと。","id":"exchange-146"},{"speaker":"渡辺委員","kind":"質問・要望","question":"よく企業のＣＳＲと言われますが、企業ではなくてまさに地域の個人個人が地域貢献をしている最たる例だと思います。ぜひとも来年、まだ検証が追いついていない部分もありますが、大規模なモデル実施、あるいは検証の年に、それはなぜかというと、コロナからの、ウィズコロナなのか、コロナからの脱出なのか、大きな節目の年なので、これは本当に重点事業にしていただきたいと思いますが、答弁をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは私どもも力を入れている事業です。商店街連合会も、こちらは非常に前向きに取り組んでいただいているところですので、しっかり検証して、ここにつなげていきたいと思っているところです。","id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/685794?Template=document&Id=1506#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":121470,"voices":336}},{"id":"r03-20211011-4","meetingId":"r03-c-settlement","date":"2021年10月11日","dateIso":"2021-10-11","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"意見","question":"おはようあります。私からは、決算書３１７ページ、道路安全施設費、３３１ページ、不燃化１０年プロジェクト、３５１ページ、防災関係組織経費、３５５ページ、避難所管理費、時間があれば、帰宅困難者を聞きたいと思います。道路安全施設費の中にあります未就学児移動経路等の安全施設整備工事、この事業についてご説明をお願いいたします。","respondent":"溝口道路課長","answer":"この令和元年度に行った安全点検に基づきまして、その中でも緊急性の高い安全対策が必要な１１６か所については令和元年度に、引き続きまして残りの９６か所ありまして、それを令和２年度に工事を実施したものです。","id":"exchange-001"},{"speaker":"松澤委員","kind":"意見","question":"警視庁は、平成２８年から令和２年に起きた交通事故を分析したところ、歩行中の小学校の死者、重傷者はこの５年間で２,７３５名に上ります。学年別ですと、最も多いのが小学校１年生で７０８名、学年が進むにつれて減少し、最も少ないのは小学校６年生の１９１名となっております。この数字を交通安全担当はどのように考えていますか。お聞かせください。","respondent":"川口交通安全担当課長","answer":"やはり安全な道路の歩行と横断、また併せて、基本的な交通ルールをしっかりと理解してもらって安全に行動していただく、その判断能力を小学校入学時にしっかりと養ってもらうことが必要ではないかなというふうに考えております。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"このキッズ・ゾーンというのは保育関連になりますので、ここではゾーン３０ですか、交通安全の新しい取組みと記載がありました。要は、警察が担当しますそういったソフト面、道路課が担当しますハード面、この両面が重なってこそ、危険である地域は安全に変わるものではないでしょうか。道路への注意喚起というものを含めて、ソフト面、そしてハード面、それぞれのご見解をお聞かせください。","respondent":"溝口道路課長、川口交通安全担当課長","answer":"今後も、地域の声、または学校関係者、そういったところの様々な意見を聞きながら、必要な交通安全対策はしっかりとやっていきたいと考えていますし、警察、または交通安全担当を含めて、ハード、ソフトを合わせて。併せて、ハード面の対応がなかなか困難な場所につきましては、引き続き、委員もお話ございました、例えば注意喚起の看板等の設置を、区といたしましても警察と連携をして実施してまいりたいと考えております。","id":"exchange-003"},{"speaker":"松澤委員","kind":"提案","question":"そういったものに代わる方法があるのか、教えてほしいのが１つ。しかし、私たち大人向けの交通安全教室が全くないです。そういった部分でご提案したいのが、ちょっと難しいと思うのですけれども、鮫洲試験場の練習場などで、年代とかスポットを絞って、私たち大人に、いま一度安全を見てもらうという部分で交通安全教室を開くのも新しい試みかと思いますけれども、ご見解をお聞かせください。","respondent":"川口交通安全担当課長","answer":"２つ目の大人向けの交通安全教室のお話ですけれども、大人の方で運転免許を保有されている方は、運転免許の更新時に、それぞれしっかりとした更新時の講習を受けていただくということとあわせて、区では、それぞれ、例えば親子の自転車教室ですとか。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問・要望","question":"確かにそうですね、免許のない人に対してどういうふうに普及していくのかが課題だと考えています。次に、不燃化１０年プロジェクトです。私も含めまして、各議員の皆様より、この制度の延長、そして新たな地区の追加を要望しまして、令和３年度は、西品川一丁目、大井二丁目、西中延三丁目を新たに対象地区に追加して、地区の事業を５年延ばしていただいたことには感謝申し上げます。","respondent":"五十嵐災害対策担当課長","answer":"木造住宅密集地区での火災の消火活動とその苦労についてですが、消防職員としての一般論になりますが、まず、老朽化した木造住宅が林立している上で、隣棟間隔が狭く延焼拡大しやすいこと、街区内に空地がなく十分な消防活動スペースが得られず不自由であること、また。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"やはり木密というのは、プロの方でも相当なストレスがあるということが分かります。それでもこれだけ被害をとどめていただいたことには本当に感謝しております。そこで、対象地区を除く地区、要は、木密の対象地区において、危険と思われる木密地域、これは消防と連携して行政が把握しているのか。品川区は、この木密の基準を見て地域を絞っていくと思いますけれども、そこら辺を教えてください。","respondent":"森木密整備推進課長","answer":"不燃化１０年プロジェクトの対象地域につきましては、総合危険度と、それから不燃領域率などを勘案しまして、集中的に強力に進めているところです。今後もそれぞれの地域におきまして不燃化を進めるべく考えていきたいというふうに思っております。","id":"exchange-006"},{"speaker":"松澤委員","kind":"確認","question":"今のお話ですと、東京都がチェックをして、品川区の木密整備推進課でそれを確認するというお話でした。しかし、この不燃化特区以外、この前の小山もそうですけれども、不燃化特区以外のスポット的な地区を重点的に、助成金がないですけれども、啓発してやっていく、さらなる地域の拡大、そういったお考えがあれば教えてください。","respondent":"森木密整備推進課長","answer":"そこにつきましては、木密整備推進課で行っております事業等はなかなか難しいのですけれども、一方で、荏原地域を包含するかなり大きな地域の中では、建築課の旧耐震の木造建築物に対して耐震除却助成も実施しています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひその建築課との連携等も含めて、どんどん啓発を進めていただきたいと思います。この制度は、燃え広がらない、燃えないまちにすることを目的とした制度です。次に、この木密に関連して、同時多発火災防止につなげていきたいと思います。品川区の地震想定では、どれくらいの火災について想定しているのか、教えてください。ほかの地域と比べると、その数字をどのように感じているのか、教えてください。","respondent":"山本防災課長","answer":"火災被害の想定についてのお尋ねです。首都直下地震が発生した場合の火災による住家の倒壊被害は約２万戸、それから死者数を５２０名と想定しています。この数字を近隣区と比較しますと、比較的被害規模が大きい傾向にあるというふうに感じてあります。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"ほかの地区と比べると、やはり品川区は大変多いことが分かりました。でも、品川区は２３区で比べると地域防災には大変力を入れている区だと認識しております。しかし、地域防災力を上げる、区民消火隊などでも高齢化でできないなどの声も上がっていますが、それに対して行政としてどういうような対応をしているのか、教えてください。","respondent":"山本防災課長","answer":"隊員の減少、高齢化などにつきましては、区としても大きな課題として認識はしていますが、まだ具体的な解決策をお示しすることができてございません。今後、区民消火隊の負担軽減につながるような対策も含めまして検討していきたいというふうに考えてあります。","id":"exchange-009"},{"speaker":"つる委員","kind":"確認","question":"火災救護班が３班編成されていて、それぞれに班長がいらっしゃると思うのですけれども、やはり今回の場合はシルバーセンターに入ったときに、例えば消防隊の方が戻れるかどうかの状況をお伝えするというタイミングだとか、防災課の方が一人ひとりにちゃんとお名前を確認しているとか、町会の方が食事を用意してくれるとか、あと、布団が幾つあるのかとか、全体を俯瞰的に見渡すような指揮官が。","respondent":"五十嵐災害対策担当課長","answer":"委員、先日の火災対応、ありがとうございました。火災り災者支援の現場指揮官についてのお話ですが、防災課では、要綱、手引書に従い、区内で発生した住宅火災の支援として、小災害援護班、１班六、七名で、３班編成で現場対応しております。","id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"今後、再整備、それはＯＪＴとありました。火災がないことがいいわけで、火災がないとＯＪＴにはならないかもしれないですね。なので、先日も遠慮しながらだったのですけれども、職員の方に逐一確認をさせていただきながら、「布団が今ここは３セットしかないですよね、５人の方がいらっしゃるのですよね、どうしましょうかね」と言ったら、「じゃあ、予備のものをどこかからとってきます」と言うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３１５ページ、違法駐車防止対策、３１９ページ、立会川緑道整備、３２５ページ、下水道管改修事業、３４５ページ、歴史的・魅力的建築物調査活用事業についてお伺いいたします。最初に、３１５ページの違法駐車防止対策についてお伺いいたします。これは指定４路線ということで、池上通り、区役所通り、八ツ山通り、補助２６号線が対象となっております。","respondent":"川口交通安全担当課長","answer":"指定４路線以外ですが、こちらにつきましては、それぞれ警察のほうでも、警察署としての取締りの活動ガイドライン等もありますので、そちらに対してもそれぞれ交通安全運動の機会を通じて、放置駐車の防止のキャンペーン等を実施しています。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問","question":"いろいろな啓発をしていただいているというところで、これは旗の台駅の南口のところの区道、これは心身障害者福祉会館に向かうまでのところに視覚障害者用の誘導ブロックがあります。これは荏原警察署が所管になると思うのですけれども、区としては、これも啓発しなければいけないと思っているのですけれども、どういうふうにお考えになるか、お聞きしたいと思います。","respondent":"川口交通安全担当課長","answer":"これは参考ですけれども、今度の１５日には、旗の台駅の商店街の皆様方と警察と、また、区の関係者も一緒になって、駐車の取締り等の指導の、取締りの啓発等のキャンペーンを行う予定です。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３１９ページ、立会川緑道整備についてお伺いいたします。この立会川緑道整備は、三間通り、中原街道から第二京浜国道までのこの道の入り口からが、第１工区が終了し、今度、３工区が１０月半ばから進められるということです。３工区も、地域の意見、いろいろ要望があるかと思うのですけれども、今までの計画と、何か改善点があったら教えていただきたいと思います。","respondent":"溝口道路課長","answer":"物理的といいましても、やはり注意喚起も必要になってきますので、道路の巡回等を行いながら、見つけ次第、どいていただくように、注意喚起も引き続き行っていきたいというふうに考えているところです。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これ、３工区が１０月の半ばから令和４年４月までということで、この工程は、天候にも左右されると思うのですけれども、この３工区は、カーブになったりとか、車道にするにも、歩道にするにも、工事の施工部分においても結構大変なのかなと思っているのですけれども、この工事の安全を含めて、歩道は多分できないと思うので、地域にどういうふうに注意喚起しているのかどうか、教えていただきたいと思います。","respondent":"溝口道路課長","answer":"利用については、少し慣れていただく必要があるのかもしれませんけれども、看板等も含めて設置しながら開放していきたいというふうに考えておりますので、今後、通行者の方から、何か分からない点、不明な点、そういったものがあれば、それはそれに対して注意喚起を促す。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ぜひ整備していただいて、もう少しなので、よろしくお願いいたします。続きまして、３２５ページ、下水道管改修事業についてお伺いいたします。下水道は、平成６年度末に、２３区では１００％普及の概成をしました。そこで、下水道の老朽化対策に向けた取組みと、これは東京都の取組みで、品川区ではこの事業を受託して対策を進めていると聞いておりますけれども、この工事の内容についてお伺いいたします。","respondent":"栗原河川下水道課長","answer":"具体的な工事の内容ですが、下水を排除する能力が不足している下水道管につきましては、道路を掘削して下水道管の太さを太くするために管の交換を行い、また、能力は不足していないが老朽化しているような管につきましては。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問","question":"工事内容については分かりました。今後ともよろしくお願いいたします。先日も都内で大きな地震がありました。上水道管の耐震化について、これは、すみません、上水管なのですけれども、東京都には２万７,０００kmあって、水道管の耐震化率がまだ４０％でとどまっているということです。引き続き計画的に進めていただければと思うのですけれども、その事業の計画、そして目標時期についてお伺いいたします。","respondent":"栗原河川下水道課長","answer":"比較的整備年代の新しい目黒川を挟んで南側のエリアにつきましては、第２期再構築エリアとなっておりまして、日常の維持管理や管路内調査で発見された傷んだ管の補修を行いながら、本格的に再構築を行うのは。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"引き続き、計画的に工事を進めていただきたいと思います。最後に、３４５ページ、歴史的・魅力的建築物調査活用事業についてお伺いいたします。ツアーのみの１日限りのイベントを開いたということです。ところが、新型コロナウイルスの感染によってイベントが中止になった中、今年度はツアーとして開催するのか、あるいは延期にするのか、今後どういう状況なのか、教えていただきたいと思います。","respondent":"長尾建築課長","answer":"そういった声を踏まえまして、今年度につきましては、これまでに公開した建物や、実施したツアーの様子をコンテンツとした動画配信を、今、企画しています。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"動画でこれから配信をしていくということで、この配信が、今いろいろやられておられると思うのですけれども、いつ頃に広報しながわとか、掲載の時期を含めて、視聴できるようになるのか、お聞きしたいと思います。","respondent":"長尾建築課長","answer":"動画配信につきましては、これまで行っていなかった活動になりまして、新たなチャレンジをしているところです。動画配信の予定時期としましては、年度末近くになると考えております。","id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"確認","question":"そうすると、今まで３回やって、公開建築物が３０弱ぐらいあるのですか。それをピックアップしながらやっていくということかどうかを確認したいと思います。お願いします。","respondent":"長尾建築課長","answer":"建築物の公開という形ではなくて、ツアーの中で、外から外見だけ見てという建物も加えますと、もう少し多くなりますので、そういったところを建物の所有者や管理者のご協力をまた改めて確認しながら進めていきたいと考えております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"３２９ページ、航空機騒音測定委託に関わって羽田新ルート、３３３ページ、広町地区整備検討委託等、３３５ページ、品川駅南地域周辺まちづくり事業について伺います。その区に聞きたいのですが、１つ目、区は都営住宅をなくすことも検討の１つの選択肢だと考えているのか、伺います。２つ目、区は東京都に対し、都営住宅の移転を要望しているのかいないのか、以上２点、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"地域といたしましては、そういったことを踏まえまして、まちづくり検討、こちらは都営住宅も含めて検討が進められているです。区としましては、品川浦や旧東海道など、地域資源を生かしたにぎわいを創出するとともに、良好な住環境を確保していくことが重要と考えています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"良好な住環境の確保という話もありましたけれども、結局、そこの良好な住環境という中に都営住宅の確保というのはちゃんと入っているのですかということも含めて、品川区が東京都に対して都営住宅の移動とか移転、こういうものを要望しているのかいないのかを私は伺ったので、ちゃんとお答えいただきたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"都営住宅につきましては、まずは東京都と地域の方が意見交換をして、しっかりと調整すべきと考えています。区としましては、地域の方々と東京都が良好な関係が築けるよう、情報共有などについて側面的な支援をしていきたいと考えています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区がビジョンをつくっているわけですよね。ですから、地域住民と都が意見交換を、側面支援と言いますけれども、議事録とかを読むと、品川区も東京都に要望していきますみたいなことを言っているのです。その要望の中身について私は伺っているので、もう一度だけ、東京都に対して区は何を要望しているのか、要望しているのかしていないのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"区としましては、東京都に対しまして、良好な住環境が保てるよう、お話をしているものです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、良好な住環境の確保という中に都営住宅は絶対必要だと思います。次に、広町開発について伺います。それぞれの面積について伺いたいのですが、旧劇団四季、旧ひろまち保育園の区有地の面積。それと、その区有地と区画整理で換地後に区が手にする区有地の総面積、そのうち新庁舎建設候補地の面積、これは８,３００m2だと認識しているのですが、その３つのところを伺います。","respondent":"多並都市開発課長","answer":"今後の新たな換地後の面積のところですけれども、これにつきましては、現在、都市計画決定を進めている段階で、その後に事業計画を定め、その後に仮換地指定ということで、その中で決定していくものですので、その面積につきましても、鑑定評価を必ず行い。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"もう都市計画手続に入っていますよね。土地区画整理事業が、もう説明会でも説明されているし、今、意見書を募っているわけですよね。確定していないかもしれないけれども、おおよそどれくらいというのでも教えてください。","respondent":"多並都市開発課長","answer":"具体的な今のご質問の内容につきましては、換地といいまして、その後に事業計画に基づいて適正な評価のもとに仮換地という手続になりまして、その後に確定するものです。したがいまして、現時点で何m2かというご質問については、お答えする数値がないというのが答えです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"いや、ひどい話だと思います。それすらも示さないで、説明しないで、どんどん都市計画決定手続、今月には都市計画審議会をやりますよね。本当にすごい手続だと私は思います。伺いたいと思うのですけれども、駅前一等地をそのまま生かして、区有地や新庁舎の建設地に充てるという検討は、一度でもされたのでしょうか。それとも、一度もされなかったのでしょうか。いかがでしょうか。","respondent":"多並都市開発課長","answer":"検討したことがあるかというご質問ですけれども、これにつきましては、様々ないろいろな角度から以前から検討してきて、一番いい最適な方法ということで現在に至っているという考えです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとはっきりお答えいただきたいのですけれども、検討したのかどうか。何か今の答弁だと、したということだと思いますけれども、それでいいのか。その中で最適なものが今載っていますと、私は最適ではないのではないかと思うのですけれども、もう一度、そこら辺をはっきりお答えください。","respondent":"多並都市開発課長","answer":"このままで行うとどうなるかというのは、もちろん考え方の１つです。まちづくりを行わなかった場合、行った場合ということで、今回は、大井町の広町地区の土地利用により合った形で検討していくということで現在に至っているところです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"今のままでどうなのかということも検討したということだというふうに捉えましたけれども、私は、やっぱり庁舎は区民の財産なわけですから、なぜそういうことを密室で、何も知らせずに、最後に、この案しかないと出すのですか。そうしたことも含めて区民に出してください。ぜひこれは検討を一旦中止していただきたい。第４回固定化回避検討会について伺います。１２の飛行方式から２つが選定されました。","respondent":"鈴木都市計画課長","answer":"ただ、この新ルート、時間をかけて国は検討してまいったわけですが、これが５年、１０年、今後、固定化することがないように、継続して、管制技術ですとか、飛行の運用ですとか、そうした様々な諸条件を取り入れて、継続し。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"本格運用が昨年３月２９日です。第１回固定化回避検討会の開催は６月３０日。運用開始後僅か３か月で、この推進した当事者が、とにもかくにも見直しを口にせざるを得なくなると。これは住民世論の反映だと思いますけれども、これは前代未聞の欠陥計画、住民にとっていかに悪い影響がある計画であるかを国自らが認めたものにほかならないのではないですか。いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"繰り返しになりますが、管制技術ですとか、新たな飛行方式等々を踏まえて、継続し検討していくと。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"国も欠陥計画だということを事実上認めているわけですから、区は、即時中止して、この新ルートを海上ルートに戻すことを品川区から国に求めるべきだと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"３４１ページ、公衆便所について、まずお伺いしますが、この数を教えてください。だから、もう「便所」と言うのをどうにかならないですか。そして、３３５ページ、公園・児童遊園維持管理費で、品川区内に品川区が所有している樹木はどのぐらいあるのでしょうか。３１７ページ、道路安全施設費ですけれども、オレンジ色のカーブミラーは品川区内にどのぐらいあるのでしょうか。","respondent":"高梨公園課長、溝口道路課長、長尾建築課長、竹田住宅課長、森木密整備推進課長、川口交通安全担当課長、栗原河川下水道課長、鈴木都市計画課長","answer":"統一的な名称については、今後、検討していきたいと考えているところです。今年度の４月１日現在ですが、区内、２,１９７か所にカーブミラーを設置しています。品川シェルターについてのお問合せですが、令和２年度の実績としましては０件という結果になっております。区民住宅におきましては、４住宅におきまして、やはりエレベーターが止まりまして、翌日には復旧しています。私からは、不燃化１０年プロジェクトの実績と課題についてお答えしたいと思います。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"もうこの事業はゼロなのだから、実質０円でできる施策なのに、もうやらなくなってしまっている方が多いのではなくてやらないのですから、もうこの施策は考えたほうがいいと思うのですけれども、いかがでしょうか。カーブミラー。そこを確認してくださいということと、それと、４つの角、四つ角というのでしょうか、どちらかが止まれで、どちらかが優先的な道路になってしまっているではないですか。","respondent":"長尾建築課長、森木密整備推進課長、高梨公園課長、稲田土木管理課長、溝口道路課長","answer":"そういったところをご負担と感じられている方向けに、高齢者の方等にシェルターを準備しておりますので、そちらの耐震化支援事業と併せて。不燃化１０年プロジェクトの助成につきましては、全国で様々な災害が起きている中で、しっかりと不燃化を進めていかなければいけないということで。便所の構造についてですけれども、男性便所が外から見られるような構造の部分があるといったところですが、現在。根っこが隣の土地に回った場合というような話ですが、民法上は隣地の竹木の根が境界線を越えるときは。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"道路管理者なのですけれども、やっぱり区民、特に小さいお子さんの生命を守るという意味では、もうそろそろ両面止めると、これでやっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"３３３ページ、都市開発費、３４３ページ、水とみどりの基本計画・行動計画改定経費、３４５ページ、コンクリートブロック塀等安全化支援事業、３４９ページ、居住支援事業について伺います。２０１９年の決算特別委員会で、武蔵小山の再開発を例に、再開発などのまちづくりでは、子どもが遊べる公園・広場をつくるよう求めていました。今回の事例を踏まえて、改めて計画策定を求めますが、見解を伺います。","respondent":"多並都市開発課長","answer":"調査につきましても、今のように、再開発を進める際は、地域の皆さんで考えていただきながら、この町はどうしたらいいかと考えていただいて、調査をしながら組合の中で検討していただいた現時点の考え方で整備まで進んでいるという考えです。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"この公園については、公園の新設計画の作成は強く求めたいと思います。計画を伺います。小山三丁目の再開発について伺います。区の指導、助言後に改善がされたかを区はどのように確認しているのか、伺います。これまで再開発の説明会でそのようなことを求められたことはありません。区として、参加者の名前がある議事録を求めたのでしょうか、伺います。","respondent":"多並都市開発課長、高梨公園課長","answer":"小山三丁目第１地区につきましても、９割を超える方の賛成があって、総会として適切に区に提案があったもの、また、小山三丁目第２地区につきましては、参加する方の１００％の合意で提案していただいているというところで。こちらにつきましては、現在策定を進めております品川区水とみどりの基本計画・行動計画の中で、その素案の中に、木密地域への防災広場の設置であるとか。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"個人情報の議事録について、区は求めていないということでした。参加者からすると、区に不信感を抱く不適切なことであり、改善させるべきと考えますが、見解を伺います。区が目指すまちづくりの基本的考え方からもずれている現状にある小山三丁目の計画は、地域住民の周知が進むまでは、区として都市計画に進めさせない、認可しない選択をするのは可能であり、すべきと考えますが、改めて区の見解を伺います。","respondent":"多並都市開発課長","answer":"それに向けて、法令に準じた形で規定を設け、その中で合意形成をしていただいているところでありますので、区としましては、適切な方法で進めていただいているというふうに認識しています。","id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"見解を伺います。そして、これから区内のどこかでまちづくりの検討が始まるときには、これはマスタープランに書いてありますから、地域住民が積極的、主体的に参加できるよう、遅くとも準備組合ができたときには、区として地域住民に準備組合に関わるよう広く周知し、参加を募る支援をすること、そのときには準備組合は任意団体であることを知らせるべきと考えますが、見解を伺います。","respondent":"多並都市開発課長","answer":"その内容につきましては、地域のニュースであったり、または、まとまった段階で、先ほどご紹介していただいた事業者説明会であったり、いろいろな形で地域の方にご説明してプランをまとめていくということで、段階を踏んでやっているところですので。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほども言いましたけれども、準備組合は、本来、土地を持っている、建物を持っている人だけではなく、そうではない地域住民の方も入れることが大前提です。まちづくりとしての大前提なので、ぜひ区として、準備組合にきちんと規定を、ルールをつくっていただきたいと思います。要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"私は、３１５ページの中ほどにあります駅周辺等放置自転車対策事業、４億６,９７５万円余からの質問ですけれども、毎年、巨額の予算を組んで行っているこの事業ですけれども、一向に減らない路上の放置自転車の事業です。この費用の削減方法は、区民の皆さんに協力していただかないと解決策はありません。ここ数年、放置自転車の増減がどのように推移をしているのでしょうか。お聞かせください。","respondent":"川口交通安全担当課長","answer":"区といたしましては、それぞれの放置自転車対策を引き続き重点に沿って実施していきたいというふうに考えているところです。","id":"exchange-039"},{"speaker":"木村委員","kind":"質問・要望","question":"努力はしていただきたいと思いますけれども、なかなか、これはあくまでも目標はゼロということになるわけですけれども、先が見えない目標ですから、ゼロに近づくためには、区民の皆様には、行政側としてどのようにお願いをするのでしょうか。どのような規則をつくればやっていただけるのか、お聞かせください。","respondent":"川口交通安全担当課長","answer":"区民に対する放置自転車防止のための周知の部分ですけれども、こちらにつきましては、１０月に実施をする駅前放置自転車クリーンキャンペーンにおきまして、広報しながわにもしっかりと書かせていただいているとともに、また、今はコロナ禍の影響で。","id":"exchange-040"},{"speaker":"木村委員","kind":"質問・要望","question":"３２１ページにあります無電柱化推進事業についてお伺いいたします。そこで、今後も引き続き無電柱化を推進していく必要があると思いますけれども、区の今後の取組みについてお伺いいたします。","respondent":"溝口道路課長","answer":"さらに今年度につきましては、より早期に事業の着手が見込める２路線の設計も併せて進めているところです。今後も引き続き、この計画に基づきまして、無電柱化を推進していきたい、そのように考えているものです。","id":"exchange-041"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひ頑張っていただきたいと思いますけれども、無電柱化推進計画に基づくこの事業については、着実に進めていただきたいと思います。一方で、無電柱化を進めていくためには、多額の費用や工事期間が大変長いといった課題もあろうかと思います。そこで、事業を始めるに当たり、この課題についてどのように対応していくおつもりなのでしょうか。区のお考えをお聞かせください。","respondent":"溝口道路課長","answer":"事業実施に当たりましては、国または東京都の取組み状況、または、補助制度の充実等も行われておりますので、そういったところの動向を捉えながら、無電柱化の着実な実現に向けて今後も引き続き取り組んでいきたいというふうに考えているところです。","id":"exchange-042"},{"speaker":"木村委員","kind":"質問・要望","question":"少しでも早く道路上から電柱がなくなり、安全で良好な都市景観の実現に向けて、ぜひ無電柱化を進めていただきたいと思います。次の質問に移りますけれども、決算書３２３ページ、水辺利活用事業の舟運通勤等社会実験実施についてお伺いいたします。お聞きいたしますけれども、舟運通勤社会実験の内容をお聞かせください。","respondent":"栗原河川下水道課長","answer":"令和２年度につきましては、オリンピック・パラリンピックの期間中に実施する予定で舟運事業者等と調整を進めてまいりましたが、オリンピック・パラリンピックの延期、また、新型コロナウイルス感染症拡大防止の観点で。","id":"exchange-043"},{"speaker":"木村委員","kind":"質問・要望","question":"新型コロナウイルスの感染拡大防止に向けて、人流を抑制するという観点から延期となったこともあろうかと思いますけれども、昨今の状況から仕方がないと思いますけれども、コロナの収束と合わせて、ぜひ社会実験の実施に向けて検討を進めていただきたいと思います。社会実験の結果をどのように航路の実現につなげていくのでしょうか。最後にお答えください。","respondent":"栗原河川下水道課長","answer":"社会実験では、利用者へのアンケートを実施する予定でございまして、その結果などを踏まえまして、東京都や舟運事業者の皆様とともに、採算性や運航方法といった航路の実現に必要な検討を進めてまいりたいと考えているところです。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"本日は、３１５ページ、交通安全啓発費について、３３７ページ、公園・児童遊園整備費について伺います。交通安全啓発費ですが、最近、区内でも電動キックボードに乗った方をよく見かけます。電動キックボードに実際に乗ってみました。一方で、６月には、大阪で電動キックボードによるひき逃げ事件が発生し、被害者は首の骨を骨折しているというような事故も起こっています。お願いします。","respondent":"川口交通安全担当課長","answer":"当然、安全対策についても説明がございましたので、法令に準じた適用の範囲内でやっていくという中と、併せて、その実証実験には、いわゆる一定の要件で、例えば自転車通行帯等の通行もできますので、その辺のところの把握はしていたところです。","id":"exchange-045"},{"speaker":"松本委員","kind":"確認","question":"確認ですけれども、事故では、今の物損というか、物件の事故が１件で、人損は特にないという理解でよろしいでしょうか。もう１回お願いします。","respondent":"川口交通安全担当課長","answer":"委員ご指摘のとおり、物件事故のみの１件です。","id":"exchange-046"},{"speaker":"松本委員","kind":"質問・要望","question":"この周知、警察と協力してというお話も先ほどあったかと思うのですけれども、やっぱりこの電動キックボード、結構見るように少しずつなってきているので、できれば区としても、ルールとかの周知をしていただきたいと思うのですが、まず１つは、広報しながわでの周知もあると思いますし、あと、やっぱりこれは若い人たちが使っているので。","respondent":"川口交通安全担当課長","answer":"電動キックボードの必要な免許やルールの周知につきましては、今、委員ご指摘のとおり、今、うちの担当でも、ＳＮＳによる各種交通安全に関する情報発信をやっているところですので、そちらのほうは実施を前向きに検討したいというふうに思っております。","id":"exchange-047"},{"speaker":"松本委員","kind":"質問","question":"これは民間のほうも自分たちの安全対策はこれだけやっているのだというふうな広報にもなるし、一方で区としても、乗るときはこういうことを気をつけてくださいねというふうな広報にもつながると思いますので、この辺りは民間の事業者と組んで、試乗会、安全講習会も企画してはいかがかと思いますが、いかがでしょうか。","respondent":"川口交通安全担当課長","answer":"その辺の民間事業者との連携ですけれども、こちらにつきましては、今後の区内における電動キックボードの走行状況、あと普及状況、こちらのところを見ながら注視をしてまいりたいというふうに考えております。","id":"exchange-048"},{"speaker":"松本委員","kind":"質問","question":"新しい交通手段がいろいろあって、規制が拡大してしまうというのも、それはそれでちょっと利便性がもったいないなというふうなところを思いますので、率先してやっていただければなと思います。次に、公園・児童遊園整備費について伺います。子供の森公園ですけれども、児童相談所の整備で工事が始まっているというところです。","respondent":"高梨公園課長","answer":"スケジュールといたしましては、下水道の工事が令和６年度までかかる予定となっておりますので、それまでの間に、公園としては、基本計画であったりとか、設計作業、当然その作業の中では、利用者であったり。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"この公園自体ではなくて、全体的なお話でお伺いしたいのですけれども、一応今の区の公園条例を見ると、指定管理については特に定めがないので、やるのだったら、都市公園法第５条の管理の許可という形で公園の管理を民間にお願いしたりするということは可能なのかと思いますので、実際のところ、今、民間にそういった公園の管理をお願いしている事例は、区内ではどの程度あるのでしょうか。","respondent":"高梨公園課長","answer":"今後の公園の管理のあり方につきましては、現在、他自治体等でも行われている民間活力を利用したところは、品川区におきましても前向きに検討していきたいというふうに考えているところです。","id":"exchange-050"},{"speaker":"松本委員","kind":"質問","question":"よくＰａｒｋ－ＰＦＩが話題になって、本区議会でも、つる委員が、もう２０１８年には取り上げていたかと思うのですけれども、せっかくこれから再開発を行うということで、子供の森公園、こちらで検討してはいかがかと思いますが、最後にいかがでしょうか。","respondent":"高梨公園課長","answer":"その点も含めまして、前向きに検討していきたいと考えています。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、時間の関係で、３つまとめて質問します。予算特別委員会款別審査、また総括質疑の確認なのですけれども、長年にわたる地元の悲願でありました青物横丁駅前の国道１５号にかかる歩道橋へのエレベーター設置につきましては、本年２月の国会の予算委員会で、地元の要望として取り上げていただいたことをご紹介させていただきました。続けて質問します。３点目です。３つお聞きします。","respondent":"鈴木都市計画課長、五十嵐災害対策担当課長、山本防災課長","answer":"まだ具体的な第１回目の日時については連絡は来てございませんが、今年度、恐らく、会を設置して、意見交換、調整・検討していくという認識です。その結果、近隣ホテルの空き状況のあっ旋の延長で、大規模災害時の災害時協力協定締結ホテルや旅館の活用がよいとの考えに至ったところですが。都営住宅との覚書についてのお尋ねです。令和３年４月１５日付で東京都との間で大規模な水害時における緊急避難に関する覚書を締結しています。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それぞれありがとうございました。これは病院や学校へ向かう皆様が駅から滞留してしまうことから同様のご要望をいただいておりますが、最近では、北品川駅の高架化に合わせて、国道を渡った学校、病院側の地域とともに一体的に考えて歩道橋の整備をすべきではないというご要望も地域の皆さんから伺っているところですが、これについての品川区の考えを教えてください。併せて、最後の質問をします。","respondent":"中道まちづくり立体化担当課長、山本防災課長、竹田住宅課長","answer":"関係者からは、地域の確保や維持管理などの課題があるということは聞いてありますが、区としましては、様々な課題に対して、研究、検討していきながら。近隣自治会への周知ですが、今後、住民理解が深められるように、津波避難施設の重要性であったりとか、また。区内のマンションに住む人口の件ですが、平成３０年度の住宅土地統計調査によりますと、マンション等の共同住宅にお住まいの世帯が１８万１,４００世帯。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前段の質問につきましては、それぞれ進めていっていただきたいと思うのですが、最後のマンションのところです。今、区民の約８３％の世帯の方がお住まいだという、これは分譲とか賃貸、ここでいうところのマンションというのは分譲のことなのですけれども、そういったところの策定については、ぜひお願いをしたいと思うのですが、いかがでしょうか。どのようにお考えなのか、教えてください。","respondent":"竹田住宅課長","answer":"誰がという点ですが、マンション管理適正化推進計画には適合しているかどうかの審査の一部を指定認定事務支援法人に委託することが可能とされておりますが、委託先の適合性については、国よりまだ具体的なものが示されておりませんので、示され次第。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"意見","question":"ちょっと私、最初のほうを聞き逃したかもしれないのですけれども、自治体としてのマンション管理適正化推進計画と指針については、これは区のほうで任意なのだけれども、つくっていくという方向なのか。つくってほしいのですけれども、そこについてもう１回ご答弁をお願いしたいと思います。","respondent":"竹田住宅課長","answer":"マンション管理適正化推進計画および管理計画認定制度の策定が必要と考えておりますので、策定していく方向で検討しております。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"ぜひ品川区のほうで、こうした計画、また指針、またそういった制度、認定制度をしっかりつくっていただいて、マンション管理組合への支援のさらなる強化をお願いしたいと思いまして、本日の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"芹澤委員","kind":"質問","question":"私からは、３３１ページ、都市防災まちづくり事業費、主に防災のことを何点か、あとは３４３ページ、水とみどりの基本計画・行動計画改定経費についてお伺いします。都市防災まちづくり事業費ということで、防災についてお伺いします。先ほど、あくつ委員から、マンションの割合についてお話がありました。","respondent":"山本防災課長","answer":"エレベーターに関して、エレベーターの閉じ込め事故であったり、あとは、高層階にお住まいの方の移動負担、その辺りが１つ課題というか、対策をしなくてはならない部分だというふうに考えてあります。","id":"exchange-057"},{"speaker":"芹澤委員","kind":"質問","question":"家具転倒防止に関しては、それぞれのご家庭でやれることなのかなと思うのですが、エレベーターやトイレというのは、自分だけの対策ではなくて、マンション全体で１つのコミュニティとして対策をしていく必要があると思っています。分譲マンションでないといけないとか、いろいろあると思いますが、その条件の１つに、町会加入というのも１つの条件として補助をご検討されてはと思いますが、いかがでしょうか。","respondent":"山本防災課長","answer":"マンションへの防災資機材等の助成につきましては、他の自治体でも既に取組みを行っているところでございまして、区としてもその対応等を今検討しています。区といたしましても、そういった他の自治体の取組み等を参考に、今後、考えていきたいというふうに思っているところです。","id":"exchange-058"},{"speaker":"芹澤委員","kind":"質問・要望","question":"やはりおっしゃっていただいたとおり、そのマンションの１つのコミュニティで終わらせずに、町会とか、さらに地域のつながりを広げていただければと思います。この家具転倒防止、まず、認識の確認で、住宅全て、マンションも使えるのかどうかをお聞かせいただきたいのと、あとは、オーナーではなくて賃貸の方も利用できるのか、まずお聞かせください。","respondent":"竹田住宅課長","answer":"家具転倒防止器具の件ですが、対象としましては、全ての住宅を対象としておりまして、賃貸も含んでいるものです。","id":"exchange-059"},{"speaker":"芹澤委員","kind":"意見","question":"賃貸マンションも使えるということで、ありがとうあります。この家具転倒防止の取組みというのは、多分このネジを差すような大きな工事だけではなくて、下に何かかませたりとか、あとは突っ張り棒であったりとかというものもあると思うのですが、まず、それが項目として入っているのかをお聞かせください。","respondent":"竹田住宅課長","answer":"突っ張り棒等の簡易なものについては、ご本人が行うことが多いものですから、こちらの制度につきましては、専門業者に依頼して工事費がかかるものについて、取付け費用を助成しています。","id":"exchange-060"},{"speaker":"芹澤委員","kind":"質問・要望","question":"併せて、なかなか件数が伸び悩んでいるというようなお話も以前いただいていまして、これ、例えば、家具の転倒防止ということになると、恐らく引っ越しとかが一番のタイミングなのかなと思っていますので、転入の際に、家具転倒防止をあらかじめご案内をして、物を運んでくるときには、最初から転倒防止を取り入れられるような制度にしたらどうかなと思うのですけれども、ご見解をお聞かせください。","respondent":"竹田住宅課長","answer":"私どものＰＲがまだまだ不足していたところがあったかもしれません。転入の方を含めて、多くの方々にご利用いただけるように、ＰＲ、周知に努めていきたいと考えております。","id":"exchange-061"},{"speaker":"芹澤委員","kind":"提案","question":"改めてマンションの防災に戻りますが、マンション防災、既に取り組んでいるところもたくさんあって、やり方もいっぱいあると思うのです。認定をしていって、補助を継続して、そのマンション同士の取組みを横で共有できるような仕組みをつくってみてはどうかということを１つご提案します。","respondent":"山本防災課長","answer":"ハンドブックの作成のところですが、今現在、改訂の予定はございませんが、確かにマンション防災、様々な技術もありますので、その辺りを反映できるよう、今後検討していきたいというふうに考えてあります。","id":"exchange-062"},{"speaker":"芹澤委員","kind":"質問","question":"防災について引き続きお伺いします。防災協定のことでお伺いしていきます。事前に資料を伺って、１７０近くもう既にあるのかなと思っていて、非常に心強いなと思っています。ただ、これ、一方で、古いものだと昭和に締結されて、特に内容も変わっていないというようなものもあって、協定を締結した後の見直しの取組み、もしくは検証の取組みについて、何かルールづくりがあればお聞かせください。","respondent":"山本防災課長","answer":"協定内容を見直す体制、仕組みですが、こちらにつきましては、今、区としてそういった体制とか検証方法は確立されてございません。今後、より実効性のある協定が結べるように、そういった部分もしっかり整えていきたいというふうに考えてあります。","id":"exchange-063"},{"speaker":"芹澤委員","kind":"質問・要望","question":"例えばですけれども、行政書士会であればり災証明であったりとか、あとはトラック協会とか、いろいろなところの防災協定があると思うのです。使わなくても、職員で対応できるけれども、あえてそれを回して、ここに改善点があるねとかというのを、ぜひ見つけ出していただきたいと思いますが、そちらのご見解をお聞かせください。","respondent":"山本防災課長","answer":"実際に災害が起きた場合には、連携して対応ができるよう、しっかり体制等、連携強化を図れるようにしていきたいというふうに考えてあります。","id":"exchange-064"},{"speaker":"芹澤委員","kind":"意見","question":"例えばそういったもの、人であったりとか、物を貸してもらうところは、ぜひどんどん使っていって、ここに課題がある、例えば物を運搬するにしてもルートに課題があるとか、人に関しても、この知識をどうやって継承していくのかとかというところも、マニュアルを作るだったりとか、回してみて、もちろん訓練もしながらですけれども、回してみて分かることもたくさんあるかと思いますので、例えば。","respondent":"山本防災課長","answer":"１０年というご提案がございましたが、区といたしましても、そういった協定先とのふだんからの連携は強めていかなければならないというふうに考えてありますので、様々な協定先から、区でもご意見をいただきまして。","id":"exchange-065"},{"speaker":"芹澤委員","kind":"質問","question":"防災の情報発信についてお伺いします。避難所での防災発信について伺いますが、避難所は着のみ着のまま来る方もたくさんいらっしゃると思います。スマホを持っていないとか、タブレットを持っていないような方々がいらっしゃるときに、やはりラジオの環境整備が非常に大切だと思っていまして、まず、避難所でラジオを聞く環境が整っているのかをお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"避難所におけるラジオについてのお尋ねです。委員ご指摘のとおり、スマートフォンやタブレットがない方々につきまして、災害時の情報収集手段としてラジオは非常に有効なものと考えています。このため、災害時には、各避難所に少なくとも１台はラジオを設置しています。","id":"exchange-066"},{"speaker":"芹澤委員","kind":"質問","question":"もう既に環境が整っているということで心強く、ありがとうあります。実際の防災、災害時には、手話通訳者の対応が、なかなか今、難しいのかと思うのですが、そういった、今、手話通訳者の派遣をされている団体ともしっかりと協定を結んで、災害時に避難所等で手話通訳、手話も言語の保障をできるような環境をつくってみてはいかがかと思うのですが、いかがでしょうか。併せてご見解をお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"外国人対応についてのお尋ねです。災害時には、様々な言語をお話しする外国人の避難が考えられますことから、円滑な対応のため、防災タブレットに翻訳アプリをインストールすることについて検討してまいります。","id":"exchange-067"},{"speaker":"芹澤委員","kind":"質問・要望","question":"前向きなご答弁をありがとうございました。情報発信についてで、以前、一般質問で、ケーブルテレビ品川やＦＭしながわについて、大規模災害のときに区が主体的に情報発信できるような協定の見直しを求めさせていただいたと思いますが、その進捗、また内容をお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"現在でもこの協定文の中で実施できることから、災害時には、この協定を基に緊急放送を実施することとしています。","id":"exchange-068"},{"speaker":"芹澤委員","kind":"提案","question":"そこで提案なのですけれども、ケーブルテレビ品川の割り込みする放送と同じ内容をケーブルテレビ品川ではなくて、例えば区の公式ＹｏｕＴｕｂｅチャンネルのライブ配信とかを利用して、それぞれのスマートフォンもしくはタブレットでケーブルテレビ品川の割り込み放送を災害時に見られるというような体制整備を求めますが、いかがでしょうか。","respondent":"平原防災体制整備担当課長","answer":"これを踏まえまして、災害時におきましても、広報広聴課と連携させていただきまして、媒体でありますとか、あるいは方法、そういったものについての研究をしてまいりたいというふうに考えてあります。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、３２６ページの都市計画費に関わって、リニア中央新幹線について伺いたいと思います。それから、多くの区民が納得していない中で強行するのではなくて、家屋調査もやることになったし、また様々な影響を与えることも外環道で明らかになったわけですから、地域ごとに説明会を開くよう、区としても求めるべきではないかと思いますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"地域ごとの説明ですが、調査掘進が終わりましたら、本掘進に行く前に、現地でどうだったかといったことを丁寧に地域住民に説明するということを聞いてありますので、また地域ごとにやるのか、合同で説明会を開くのか。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、調査掘進の結果の説明会は、必ず地域ごとにやるようにということで区のほうからも強力に求めていただきたいと思います。そういうところでは、ぜひ調査掘進の結果の説明会は地域ごとにやるようにということで区から求めていただきたいと思うのですが、いかがでしょうか。それから、家屋調査についてなのですけれども、品川区のルートそのものが何ｍあるのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"家屋調査はいつまでにですが、この前の説明会では、令和３年度中に品川区内全て、家屋調査を行いたいというふうに聞いてあります。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明会を開いていると言っても、７,０００軒も対象になるにもかかわらず、説明会に参加されたのは１００数十名という、ごく一部しか参加されていないわけですから、これは本当に地域ごとに丁寧にやっていただきたいと思います。それから、もう１つお聞きしたいのが、先日、地震もありましたけれども、南海トラフ巨大地震の影響のことを伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"そうしたところで地震に強いものをつくるというのもそうなのですけれども、やはり地震があった後に、どういうふうな安全対策をするかといった複合的な考えで進めていくことが重要と考えています。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこれは本当に重大問題だと思うのです。トンネルになるわけですから、活断層が幾つあるかも分からないということは、私はあり得ないと思うのです。品川区はとにかくど真ん中を通って始発になるわけですから、私はこれはＪＲ東海がやっていることだというふうに言って済ませる訳にはいかないと思うので、ぜひ品川区としても、安全というふうなところでも検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"こんの委員","kind":"提案","question":"初めに、大森駅歩道橋エスカレーター修繕工事に関連して、大森駅と大井町駅のバリアフリー化、そして、利便性向上という観点から、これまで何回かお聞きしてきましたが、その後の進捗状況などを確認していきたいというふうに思います。その後、調整はどのように進んでいるのでしょうか。現状をお聞かせください。いかがでしょうか。ご見解と併せて、現在の大田区、ＪＲとの調整の進捗状況もお答えください。","respondent":"鈴木都市計画課長","answer":"これが１つ継続して行っているところですが、委員ご指摘いただいたように、さらなる利便性の向上では、ホーム階へのエレベーターとのセットがよりよい方向性だと思うのですが、ご指摘のとおり、エレベーターがＪＲ側につかないとしても。","id":"exchange-074"},{"speaker":"こんの委員","kind":"質問・要望","question":"現状、分かりました。いろいろと課題があるところであるというのは理解をするところですが、商業施設の建て替えというタイミングも伺えるという、こうした観点もご説明がありましたので、いろいろなタイミングを見ながら利便性向上を図っていただきたい、このようにお願いしたいと思います。","respondent":"鈴木都市計画課長","answer":"ＪＲからの回答としましては、課題としては認識しているものの、１つは、今、コロナ禍ということで、非常に全国的に利用客が減っているというところでの課題というところと、それから、これは本件のエレベーターは平成１４年に区の助成。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問・要望","question":"歩行者の信号機が青であることを視覚障害者に知らせるため、擬音やメロディーなどの誘導音を鳴らす視覚障害者用交通信号付加装置、いわゆる音響式信号機ですけれども、これは現在区内に何基設置されていますでしょうか。この音響式信号機は、青信号のときに常に音が鳴るタイプと、押しボタンを押したときだけ音が鳴るタイプと２種類あると思いますけれども、その設置割合はどれぐらいでしょうか。","respondent":"川口交通安全担当課長","answer":"区内におきます音響式信号機の設置状況ですけれども、本年の９月現在で、区内７９か所となっております。現在、押すタイプまたは鳴動の時間関係ですけれども、そちらにつきましては警察のほうからの情報提供がないものですから、把握をしておりません。","id":"exchange-076"},{"speaker":"こんの委員","kind":"質問","question":"把握はされていないということですが、設置はあるということで理解しました。現在、音を止めている時間帯は何時から何時までなのでしょうか。併せて、騒音の苦情などの声がありましたら、それは主にどのような場所に設置されている信号機にそうした苦情などが上がってきているのか、その辺も少し教えてください。","respondent":"川口交通安全担当課長","answer":"地域の設置場所におけます、例えば、視覚障害者の皆様方の団体の要望とか、併せて、そういう利用される方々の交通量を踏まえて、そのような時間等にしています。","id":"exchange-077"},{"speaker":"こんの委員","kind":"質問・要望","question":"音を止めている時間帯に信号を渡る視覚障害者のための安全対策を何とか図っていただきたいと思うところなのですが、障害者団体の方からは、せめて渡るときだけでも起動していただけないかと、こういう声があるわけで、そうした声については具体的な対策をとっていただきたいと思いますが、いかがでしょうか。","respondent":"川口交通安全担当課長","answer":"その鳴動に関しても、今後いろいろな形で、新しいシステムも開発されているところです。そのような導入が今後も図られるように、区としても情勢を注視してまいりたいというふうに考えております。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"これによって鳴動時間外の障害者の方々の安全性が高まることが期待されるというふうに出ておりましたけれども、こうしたことを、今ご答弁いただきましたが、そのシステムも調査・研究していただいて、品川区においてもこれが導入できるように、警察と協議をしていただくなどして進めていただきたい、このように思いますが、いかがでしょうか。","respondent":"川口交通安全担当課長","answer":"今後の設置状況につきましては、警察と、引き続きどのような場所で設置・運用ができるのかということは注視してまいりたいというふうに考えております。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひそうしたシステムが開発されていることを障害者団体の方々のお声を聞きながら進めていただければと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"３１５ページの交通安全啓発費に関連して２点ほど。１つは、車椅子です。それから、ママチャリです。事故が多いということと、それから、その場を離れないということで、ぜひ啓発活動をお願いしたいというふうに思っておりますが、それに対してのご意見をお聞きします。私はその動きが理解されていないのではないかと、メッセージ性がやっぱり弱いのではないかと思いますが、いかがでしょうか。","respondent":"川口交通安全担当課長、稲田土木管理課長、多並都市開発課長","answer":"２つ目のいわゆる幼児を乗せた自転車の関係なのですけれども、こちらにつきましては、道路交通法でも幼児を保護する責任のある方については。シェアサイクルと違法駐輪の関係なのですが、今、シェアサイクルもだんだん活用はされてきているところなのですけれども、違法駐輪との関係等々。もう１つの再開発の合意のあり方ということで、マスタープランともというお話がありましたけれども、これにつきましても。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"車椅子の件は本当にありがとうあります。再開発です。伝わったときには、もう遅しという状況になることが往々にしてありますので、そうならないように、しっかりメッセージを当初から、品川区のまちづくりはこう考えているのですよ、ただ、そこですぐ始まるというわけではないという仕組みで、準備組合ができてというその仕組みをちゃんと説明していただきたいと思いますが、再度お願いいたします。","respondent":"多並都市開発課長","answer":"委員のご指摘のとおり、やはりまちづくりをしっかり進められるように、地域の方と一緒に進めていく。そのためには、今のお話のような、分かりやすい仕組みというか、お伝えしながら進めていきたいと思っているところです。","id":"exchange-082"},{"speaker":"大沢委員","kind":"質問","question":"３２５ページ、排水施設建設事業、３３３ページの武蔵小山のことです。３２５ページ、排水施設なのですけれども、先ほど来、下水道、河川ですから、都の委託事業ということで伺っておりますけれども、ここの中で、歳出が２０億円余、都からの収入は２１億円余ということで心得ておりますけれども、その相差は１億円弱ということ、この１億円弱の中には、やはり人件費等々も計上されてくるということ。","respondent":"栗原河川下水道課長","answer":"下水道事業の受託に関してですけれども、区内の下水道事業の整備を促進する観点から、昭和６２年度より事業の一部を東京都から受託して整備を進めているものです。","id":"exchange-083"},{"speaker":"大沢委員","kind":"質問・要望","question":"歳入として入ってきているということは分かっておりまして、決算ですから出と入はこれに出ている。その中で１億円弱のこのお金の使途、どのようなものに使われているのか、その説明を今求めているわけでして、そこら辺のところの説明をお願いします。","respondent":"黒田財政課長","answer":"受託収入等で歳入がある場合につきましては、一般財源として使用する場合につきましては、人件費等に充当しています。","id":"exchange-084"},{"speaker":"大沢委員","kind":"質問","question":"この人件費等々においても、人件費というのは、この委託事業であると、都から人件費もさらに経費として入ってくるのではないのですか。この中でほかに充当するのではなくて、その相差の部分プラス人件費としてさらに委託費として入ってきているような流れというのはないのですか。","respondent":"黒田財政課長","answer":"いわゆる事業に関わる歳入ですので、事業にかかる事務費、かかる経費と人件費に充当しているものです。","id":"exchange-085"},{"speaker":"大沢委員","kind":"質問","question":"話がかみ合わないのでやめます。ご存じのように、一昨年、令和元年１１月５日に今の駅前のところができて、竣工というか、お客様に披露して、本年の６月に、今度、隣の駅前通り地区ができたということで、区では、この２つのまず先行して行われたまちづくりをどのように捉えられているのか、教えてください。","respondent":"多並都市開発課長","answer":"両事業を実施することで、土地の共同化や土地の高度利用を図ることで、品川区の西の玄関口、また荏原地区の中心核としてふさわしいまちづくりということで進められたということで成果として考えているところです。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問","question":"今度においては、一般質問にも、また区長にご答弁いただいたように、武蔵小山の第１地区、第２地区についての計画が、今、動こうとしているわけです。この皆さんが不安に思われている事実、区はどのように把握していらっしゃるのか、どのように考えているのか、教えてください。","respondent":"多並都市開発課長","answer":"区といたしましては、やはり地域の方で一生懸命、今後どうしていくべきかということでご検討いただいた成果として捉えさせていただいて、今後それが実現するように、都市計画手続をしっかり進めていくべきということで思っているところです。","id":"exchange-087"},{"speaker":"大沢委員","kind":"意見","question":"地権者の方、あるいはマンションの方、安心してこの課題というか、この地域課題に向き合っていけるように、払拭していただけるということですけれども、地権者の方は、今後の人生、あるいは、いろいろな人生設計に大きな大きな影響を与える問題でありますので、権利者の皆さんが安心してこの事業に参画できる、参加できるような形をとってもらいたいと思いますし、権利者の皆さんに少しでも不安の軽減を。","respondent":"多並都市開発課長","answer":"気軽に、このようなことはどうなのだろうということをコミュニケーションがとれるような状態を、もっともっと今よりもしていただいて、より安心して進められるような事業ということでできないかということで、日頃よりそれ以外も指導させていただいていますけれども。","id":"exchange-088"},{"speaker":"大沢委員","kind":"質問・要望","question":"行政にはこれからもしっかりと指導していただいて、連絡が通じていなかったとか、そういうことがないような形にしていっていただきたいと思うのです。あくまでも住民の方、小山に住んでいる皆さんの意向が反映されるような開発事業であってもらいたいと考えていますけれども、ここのところをどのようにお考えになりますでしょうか。お答えください。","respondent":"多並都市開発課長","answer":"ただし、その事業を検討していく段階で、今、委員からご指摘もありましたように、一般の方が詳しい情報をご存知であるわけでありませんので、区として、やはりその地域の方がどういう思いで考えて開発を進めていきたいのだということは、しっかり捉えることがまず重要であり。","id":"exchange-089"},{"speaker":"大沢委員","kind":"質問・要望","question":"最後のお願いですけれども、選挙みたいになってしまった。お願いなのですけれども、事業協力者と地権者、あるいは住民の皆さん、住民の皆さんが知らなかったということがないように、事業協力者あるいはコンサルタントの間にしっかりと入っていただいて、点と点を結んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"おくの委員","kind":"質問","question":"私から、３２６ページ、都市計画費に関わって、小山三丁目第１地区再開発について質問いたします。この９割を超える賛成とは、参加した方が再開発の結果としてのご自分の権利と、また、負担を具体的に説明を受けた上で明らかにされたのでしょうか、伺います。その点、伺います。","respondent":"多並都市開発課長","answer":"その議決の前の説明のあり方のご質問かと思いますけれども、これにつきましては、その当日にも説明ということで、資料だけではなくて説明もされているのですけれども、都市計画の内容の考え方を示してあることと、先ほどの答弁と重なりますけれども、今後の事業の進め方。","id":"exchange-091"},{"speaker":"おくの委員","kind":"質問","question":"そうでなければ、本当の意味での合意があったとは言えないのではないでしょうか。十分な説明もないままでは、私は合意とは言えないと思います。その点、いかがでしょうか。部屋がどのくらい、結局は狭くなるのだと思うのですけれども、部屋がどのくらい狭くなるかとか、それから修繕積立金などが実際に示されるのは一体いつなのでしょうか。区の都市計画審議会にかかる前なのか後なのか、この点を伺います。","respondent":"多並都市開発課長","answer":"市街地再開発事業の進めていく流れについて改めてご説明いたしますけれども、まずは、どういう開発をしていきたいかという考え方のもとに、それを考えたところで都市計画の手続をしていきます。","id":"exchange-092"},{"speaker":"おくの委員","kind":"質問","question":"しかし、こういうふうに、部屋の広さとか、固定資産税、修繕積立金、こういった負担が結局、十分に示されないままに計画が進んでいる、それが法律だとおっしゃいますけれども、そういう実態、実質から言えば、十分な説明がなされないままに手続を進めているのと同じことだと私は思うのですけれども、いかがでしょうか。私は言えないと思うのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"それができた段階で、具体的な建物についての検討をしていく、そういうステップを踏むものですから、一遍にやるものではなくて、段階的に進めていくステップという考え方と捉えていただければと思います。","id":"exchange-093"},{"speaker":"おくの委員","kind":"質問・要望","question":"結局、住民の参加と合意がないのだと思います。中止を強く求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"たけうち委員","kind":"質問","question":"３２９ページ、地域交通検討経費、３４７ページ、空き家等対策事業、３５３ページ、防災行政無線管理費で伺います。当初は２３区は震度５というようなことで言われて、実際に体感ではそれくらいあったのかと思ったのですが、あとで震度４に引き下げられましたけれども、いわゆる震度幾つ以上になったら、ああいう形で流すのかどうか、教えてください。","respondent":"鈴木都市計画課長、竹田住宅課長、平原防災体制整備担当課長","answer":"委員ご紹介いただきましたように、現在、大井ルートについて、試行運行開始を目指して検討を進めているところですが、大井ルートは、西大井駅を出発して。この２つが大部分を占めておりまして、それ以外にも、小動物が住みついてしまうというようなケースもあります。今回の地震は震度４でございましたけれども、品川区に設置の計測震度計で震度４以上を計測した際には防災行政無線を鳴らすということになってあります。","id":"exchange-095"},{"speaker":"たけうち委員","kind":"質問・要望","question":"こういったことについて、気の利いた方は、また、いろいろ余裕のある方は、業者に頼んでやっていただいているわけですけれども、なかなかそういうことができないと、また、その都度、その都度、地域から声をいただいて、また連絡をとって対応するという、こういう繰り返しになってしまうのかと思うのですが、そうした管理サポート事業みたいなもの、これ、業者を紹介するというのはあるのですけれども。","respondent":"鈴木都市計画課長、竹田住宅課長","answer":"コミュニティバスにつきましては、試行期間の４年間、その中で収支率５０％という目標を定めて実施していきたいですが、一方で、ご指摘いただいたように、コロナ禍の状況を踏まえますと、バス関係、昨年度ですと。空き家は、それ以外にも、リフォーム、土地の管理、それから建物の管理、相続等、様々な問題を秘めておりますので、そういったことも含めて、専門業者を活用して。","id":"exchange-096"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私からは、３３５ページ、公園・児童遊園費、それから３４１ページ、公衆便所費、３４８ページ、防災費全般についてお伺いします。公園についてです。うちの近くの公園にもユニバーサルデザインの遊具を入れてほしいという要望を受けたこともありますので、それだけ公園のあり方について、世の中の意識が少しずつ変わってきているのだなというふうに思っております。","respondent":"高梨公園課長","answer":"それと、公園の新設ということで、旗の台地区におきまして、公園のない町会に公園用地が確保できたといったところで、地域の悲願といったところもお聞きいたしておりましたので、地域の方が集まってワークショップを開催したという２件を実施したところです。","id":"exchange-097"},{"speaker":"湯澤委員","kind":"質問","question":"これは事前に課長から理由はお伺いしておりましたが、やはり設置をしたいという住民の声があったからということでありますが、私も近隣や隣接する方からトイレはあったほうがいいのかなというような質問を受けておりましたので、設置することに決定が変わったことはよかったのかなと考えていますが、一度決まったことが。","respondent":"高梨公園課長","answer":"コロナ禍での開催ということで、リモートでの実施等を検討したのですけれども、なかなかリモートの設備が整っていない方がいらっしゃったりということで、難しいということで書面開催になったところです。","id":"exchange-098"},{"speaker":"湯澤委員","kind":"質問・要望","question":"最終判断は、設置をするということだったということで理解しました。コロナ禍でもワークショップに参加する人が理解や納得をした上で行えるように、一層工夫をしていただきたいと思います。汲み取りまでのおおよその日数、それから、臭いや衛生面の取組み、劣化の心配について、３点お知らせいただきたいと思います。","respondent":"高梨公園課長、山本防災課長","answer":"区内の公園・児童遊園には、特に防災広場を中心として３７の公園・児童遊園に、１７３基のマンホールトイレを設置しています。し尿の収集運搬についてですが、発災後およそ３日以降、順次、収集運搬をするというところで想定をしています。","id":"exchange-099"},{"speaker":"湯澤委員","kind":"質問","question":"なので、防災資機材倉庫の備品にも、石灰や香料など、臭いや腐敗を防ぐものも加えてはいかがでしょうか。そして最後に、公園内での飲酒について伺います。区への苦情などは入っているのでしょうか。区民の憩いの場である公園での複数での飲酒は、コロナが収束するまで、また、緊急事態宣言が発令されている期間は禁止すべきかと思いますが、区のご見解をお知らせください。","respondent":"平原防災体制整備担当課長、高梨公園課長","answer":"今後につきましては、必要なものについての備蓄を検討して速やかに対応してまいりたいというふうに考えてあります。今は緊急事態宣言は明けましたけれども、今後、不適切な飲酒の状況等は、日々の巡視、夜間の巡視等も含めて、しっかりと見回りながら声かけをしていきたいと、このように考えているところです。","id":"exchange-100"},{"speaker":"湯澤委員","kind":"質問・要望","question":"緊急事態宣言が発令中とかは、ぜひ貼り紙とか注意喚起をしていただければと考えています。次に、防災のほうに移ります。そこで、暗渠部分を含めた立会川の浸水エリアに居住している区民がどのくらいいるのか、また、そういった住民に対して、命を守るためにどういったお願いをしているのか、教えていただきたいと思います。","respondent":"山本防災課長","answer":"周知に関してですが、風水害時、平時における区民への周知、啓発とかは非常に重要だというふうに考えてあります。ハザードマップを作成して戸別配布等を行っているところです。その辺りについて、引き続き力を入れて啓発等をしていきたいというふうに考えてあります。","id":"exchange-101"},{"speaker":"湯澤委員","kind":"質問・要望","question":"最後、り災証明についてお尋ねいたします。災害があった場合には、全ての区民にり災証明を取っていただきたいと考えていますが、なかなか知らなかったり、パニックで忘れていたりということがあるかと思います。過去の議事録からは、領収書があれば遡って助成が可能ということですけれども、それはどのぐらい遡れるのか。ほとんどが通るのか、どのぐらい遡れるのかをお知らせいただきたいと思います。","respondent":"平原防災体制整備担当課長","answer":"具体的にどのぐらいで、例えば効力が切れるのかとか、そういったことは、今、手元に持ってございませんけれども、一般的に、被害を立証するようなものがあれば、災害から日が経っていても証明することはできるというふうに考えてありますので、何らかの形で。","id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問","question":"３２５ページ、立会川溢水防止板設置工事等と、３２９ページ、立会川・勝島地区まちづくり検討経費、同じく３２９ページ、八潮地区の将来像検討経費ということです。立会川のほうからお願いします。今年２月の建設委員会で、立会川・勝島地区都市再生整備計画についてご報告がありました。この調査等の、現地調査というのでしょうか、それについて、どのような状況なのでしょうか。","respondent":"溝口道路課長","answer":"勝島人道橋につきましては、道路課のほうで設計を進めておりますので、私のほうからお答えをします。今年度、地域のほうにビラ等を配布させていただいた調査の件です。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"質問","question":"人道橋についてを中心にご説明いただきました。その残り２つの基幹事業についての進捗というか、検討状況をお尋ねします。それともう１つは、今、もうすぐパブリックコメントですけれども、水とみどりの基本計画にもこの勝島運河についての記述があり、そことの関連を踏まえて、どのようにお考えか、お願いします。","respondent":"鈴木都市計画課長、溝口道路課長","answer":"都市再生整備計画、委員ご質問のとおり、基幹事業を、人道橋以外にも複数ということが条件になってくるというところでございまして、エリア内、区有の公園もございまして、それから、１つ候補として検討しているところが。今回、仮称でありますが、勝島人道橋を建設することによって、さらに回遊性を高めるものにつながるものだと考えていますので、当然そういった上位計画、または都市再生整備計画。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、大変大きな周辺の回遊性、しながわ花海道、しながわ区民公園とつながるということで大きな事業になるかと思うのですが、その建設委員会での報告で、補助事業として国費の補助が上限４割ということなのですが、金額としては多額なものになると思うのですが、ほかに東京都やそのほかの補助というか、そういった関連のものは、現在、まだ計画が立っていないところで答えにくいのかもしれませんが。","respondent":"鈴木都市計画課長","answer":"都市再生整備計画を策定しまして、国費４割を入れながらというところで検討を進めてまいりましたが、人道橋を含めて、人道橋をつくった後の、どういう形で区として管理をしていくかというところで、今、様々検討している中で、１つ。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"八潮地区については、令和２年度に検討をしていただいたのですが、令和３年度は予算化されていませんが、今後のまちづくりの検討はどのような形になるのでしょうか。設置後、台風や大雨で被害はあったのでしょうか。今年度、立会川護岸点検がありますけれども、その点検状況と、老朽化しているところなどの補修といいますか、補強といいますか、それらはどのような状況でしょうか。","respondent":"鈴木都市計画課長、栗原河川下水道課長","answer":"八潮地区のまちづくりですが、区としましては、これまで委託費をつけまして様々検討を進めている中で、地域でワークショップを行いながら、最終的には、区あるいは地域、建物所有者、事業者が、共通した目標、目的を持って。併せまして、昨年実施いたしました溢水防止板設置の際に、立谷川の護岸に隣接する住民の方から、護岸の劣化が心配とのお話があったことから、今年度、点検、詳細な調査を予定しておりまして、現在、調査項目等を検討しています。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"意見","question":"八潮のほうは、ガイドライン策定、よろしくお願いします。立会川のことは、安心という成果がありましたので、今度は安全に向けて、さらに今の点検状況、護岸のチェックをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３２６ページの都市計画費に関わって、補助２６号線と踏切について、３３３ページの大井町駅周辺地区再開発事業に関わって、東大井五丁目のＣ地区について質問します。踏切のほうです。荏原第五地域センターの横にある住吉踏切は、補助２６号線道路の工事に伴って踏切をなくし、歩道橋を架ける計画になっています。周辺住民の意見を聞いているのかどうか、伺います。","respondent":"鈴木都市計画課長","answer":"それを安全に渡れるように、歩道橋、これは自転車も押して渡れるような形でスロープつきの、それとともにエレベーターつきの陸橋ができるというふうに聞いてありますので、やはり地域住民の方々、利用者の安全性を第一に考えて、東京都が踏切を除却するという判断をしたと。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問","question":"周辺住民の意見を聞いているのかどうかということでお伺いしたので、お答えいただければと思います。","respondent":"鈴木都市計画課長","answer":"踏切除却について、意見を聞いた上で検討したかということは聞いておりません。基本的には聞いておりませんが、区の受け止めとしては、そういう地域の声を聞いた上で検討しているというふうには聞いてございませんので、安全性を第一に考えたというふうな受け止めです。","id":"exchange-109"},{"speaker":"のだて委員","kind":"質問・要望","question":"ですけれども、混雑していなければ、すっと地域センターなどに行くことができます。エレベーターは設置されますけれども、お年寄りにとっては、大井町に行く際に、歩道橋を上がって、また下りてということになると、１つハードルができる。利用者が便利なように踏切を残していただきたいと思いますが、残すことはできないのか、伺います。なぜこの区間に歩道を設置しない構造になったのか、伺います。","respondent":"鈴木都市計画課長","answer":"委員にまさにご指摘いただいたように、すっと渡れる、そこが最大の危険でありまして、遮断機が下りているところにも渡れるのではないかと思ってすっと踏み出すというのが一番危険な状態ですので、区としては、やはり区民の安全性を考えれば、踏切の除却は一定理解するところです。","id":"exchange-110"},{"speaker":"のだて委員","kind":"質問","question":"Ｃ地区について伺います。先日行われた説明会でも、広町地区が周辺のまちづくりを牽引すると説明されました。区議会にも多くの方からＣ地区の計画を進めないでほしいという陳情が上がっています。広町地区が周辺のまちづくりを牽引するとのことですが、牽引する対象にＣ地区は入っているのか、伺います。まちづくり方針でＣ地区が位置づけられている活力創造ゾーンとは何か、伺います。","respondent":"多並都市開発課長","answer":"一方、再開発を心配する会という会の皆さんも検討されているということで、区としては、やはりいろいろな方のご意見をお伺いして、このまちの将来の進め方は、最終的には皆さんで考えていただいて、それをまとめていくということが考え方でありまして。","id":"exchange-111"},{"speaker":"のだて委員","kind":"質問・要望","question":"この牽引する対象にＣ地区も入っているということですが、進めてほしくないという方々がいるもとで進めるべきではないと思います。やはりこうした生活が奪われるということを生み出してはならないと思います。そして、広町地区の整備によっても波及効果を生み出すということなのですが、Ｃ地区には波及させないように、計画を進めないようにしていただきたいと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"は地域の皆様の声をお聞きして、それをどのような形で進めていくべきかということで、皆さんで考えていただいて、その方向性を決めていくということが一番重要なことかと思います。","id":"exchange-112"},{"speaker":"のだて委員","kind":"質問・要望","question":"安全性などの問題があるということですが、そうしたことをちゃんと解決しながら、超高層再開発にならないように、区として支援をしていっていただきたいというふうに思います。やはり住民合意のないままに計画が進められるということがないようにしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"３２３ページの河川管理費からお聞きしたいと思います。ということで、この令和２年度の浚渫した場所、それから、なぜ例年に比べて極端に少なかったのか。それから両岸から２ｍのそれぞれの範囲を品川区が分担するという取決めになっているという記述がありますけれども、この分担の意味は、お金のこととか、いわゆる浚渫そのもののことなのか、ここら辺の意味をお知らせいただきたいと思います。","respondent":"栗原河川下水道課長","answer":"昨年度の浚渫量が少なかった理由と、実施した場所についてですけれども、昨年度は、浚渫の工事を一度発注したところ、契約が不調となりまして、それで年度内の残工事を考慮し、再起工した結果、実際に浚渫をする時期が短くなってしまったということで。","id":"exchange-114"},{"speaker":"若林委員","kind":"質問","question":"続けて、水質改善のほうを伺いたいと思います。把握されているならば、それに基づいて、今後どのような水質改善の浚渫等々、様々な手法があると思いますけれども、そういったものを今後取り入れていこうとしているのかについてお聞きしたいと思います。","respondent":"栗原河川下水道課長","answer":"区といたしましては、先ほどお話ししました継続的に川の浚渫を実施するとともに、東京都や上流部である世田谷区、また目黒区と協力いたしまして、目黒川のさらなる水質改善に取り組んでまいりたいと思います。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほどの３つの要素の汚れの原因等とともに、この黒い塊、ヘドロなのですか、そういったところの水質浄化といいますか、汚れの除去といいますか、そこら辺の解消に向けての、もう一度、今後に向けてのご答弁をいただきたいと思います。それも一応聞かせてください。今見てもないのです。ということで、どうなっているのかということをお聞かせいただきたいと思います。","respondent":"栗原河川下水道課長","answer":"引き続きまして、品川区では、東京都や目黒区などとともに、目黒川水質浄化対策検討会の中で、水質悪化の原因、それから対策を検討いたしまして、先ほど申しましたように、堆積した泥の浚渫、また下水道局に対しましては。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"環境課が把握をして対応されているということでございました。それはそのとおりだというふうに理解いたします。ぜひ河川下水道課としても取り組んでいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"大倉委員","kind":"質問","question":"不動前、八潮の保管所の件ですが、今までお話を聞かせていただいて、放置自転車が増える中で、新しく平成１５年から不動前の保管所ができたということで、４,５００台と、そして１,５００台、６,０００台近くが受入れができるというところで、今までも放置自転車の減少については、午前中、木村委員からも質疑がありましたが、減少傾向にあって、保管率も、以前の質問だと、大分下がっていて。","respondent":"川口交通安全担当課長、平原防災体制整備担当課長","answer":"八潮北の保管所につきましては、返還率が、自転車につきましては６３.８％、バイクが４４.９％で、小計で６３.４％となっております。不動前は自転車のみです。こちらにつきましては７８.９％です。ただ一方で、それ以外のところにつきましては、同時に発報した場合には、やはり音がかぶる可能性はありますけれども、時間帯がずれていれば、そんなに聞き取りづらいというようなことはないのかなというふうに認識しています。","id":"exchange-118"},{"speaker":"大倉委員","kind":"質問・要望","question":"以前からお話をしていますが、不動前の保管所、あの辺は、目黒と不動前の間に大きな開発があって、これからまたさらに人口が増えていく、また、商業施設なども入ってきて、かなりにぎわいを見せるのではないかと、まちのあり方、まちづくり、地域の町会とかも含めて、様々変わっていくところもあるのかなと思う中で、放置自転車の保管所として、平成１５年からですからもう大分経っているという中で。","respondent":"川口交通安全担当課長、平原防災体制整備担当課長","answer":"今、不動前の保管所につきましては、先ほどご説明させていただきましたように、返還率が非常に高いというところもありまして、それぞれ開発等もありますけれども、一方では、多分、自転車の利用も増えるというところがございまして。聴覚障害の方の文字についてですけれども、防災行政無線で放送します緊急放送につきましては、仕様上できないごく一部のものを除きまして、それ以外全てを。","id":"exchange-119"},{"speaker":"大倉委員","kind":"質問・要望","question":"防災行政無線なのですが、この間の地震については、ＬＩＮＥも、多分メールも、どちらからも地震の発生等のご報告がなかったと思うのです。そういった災害時の報告が文字でも分かるようにしていただきたいと思いますので、よろしくお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"私は、防災全般なのですが、そのうちの特に３５５ページ、帰宅困難者対策経費についてお聞きしたいと思います。１０月７日、午後１０時４１分頃、首都圏で地震がありました。この品川区においても、さっきの報告で設置をされたということですが、何か所設置して、何人分用意されたのですか、教えてください。地震発生時から設置して開設するまで、何時間ぐらいかかったのか、教えてください。","respondent":"平原防災体制整備担当課長","answer":"ただいまご質問のございました１０月７日の地震における品川区の対応ですが、私ども品川区におきましては、一時滞在施設の開設準備までは進めたところですけれども、状況の確認を行いまして、実際には一時滞在施設の開設は行いませんでした。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"すみません、先ほどの質問なのですが、このたびに対して、一応用意しますよね。使う使わないは別なのですが、こういうときに、大体何人分ぐらいを用意されるのですか。さっき、東京都の想定数は申し上げましたが、実際どれぐらい用意されて、実際、設置するまで、開設するまで、実際に人は使わなかったのですが、どれぐらい時間がかかったのですか、教えてください。","respondent":"平原防災体制整備担当課長","answer":"一時滞在施設の開設ですけれども、例えば先日のような地震、人もそんなにいなかったということもございましたので、想定している全ての一時滞在施設というよりは、直ちに対応できる区有施設を中心に考えたところです。そういった意味で対応も早かったといったところです。","id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"それはすばらしいと思うのですが、ただ、すみません、一応何人分用意されたのかを再度教えてください。港区、足立区では、準備するまでに大体５時間かかったそうです。今、課長がお話ししたとおり、民間というのはなかなか難しいというところもありますが、すみません、もう一度だけ、どれぐらいの人数を想定してつくられたか、教えてください。","respondent":"平原防災体制整備担当課長","answer":"今回、１０月７日の地震に対しましては、３か所を考えたところでございまして、合計の受入れ想定人数といたしましては２５２名の施設を用意させていただいたところです。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"今回は品川区は震度４でしたが、実際、このような大規模な地震が起きたときには、もちろん交通機関も麻痺するでしょう。そのときに、実際この品川区内で、こういう一時待機場所をつくれる職員は、近辺に待機しているのでしょうか。住んでいるのでしょうか。もしそういうことがなければ、いざというときには全然対応できないということではないですか。その辺についてご見解をお聞かせください。","respondent":"山本防災課長","answer":"職員の参集についてのお尋ねです。区では、業務継続計画を策定しておりまして、その中で時間別の参集職員の数等を算出しています。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"そういうことを考えると、私は、３０年以内に大地震が起きると言っているのですから、この区内に、ワンルームでいいのですけれども、職員が１００人、２００人待機できる場所を、滞在できるところを確保する、そういう時期に来ているのではないかというふうに思うのです。もうはっきり明言している中で、なぜそういう対応をとれないのか。でも、その間に、いろいろ被災した方は待っていられるのですか。","respondent":"山本防災課長","answer":"震災発生時の初動というのはとても重要だというふうに考えてあります。区では、職員待機寮を設置しておりまして、そこに今、大体１００名弱ぐらいいるかと思いますけれども、毎月訓練等も行いながら、様々な初動対応をできるような体制をとっているところです。","id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"区役所にすぐ飛んでいけますか。家族の身の安全を守るのではないですか。そうではないのですか。そのうちの３分の１の人は動くに動けないかもしれない。そのときに実際に動けるのですか。そうしたらどうするのですか。待っています。では、今、区のやることは何ですか。いざというときの臨戦体制に備えて、そういう待機施設を用意しておくというのが当たり前のことではないですか。ご見解をお聞かせください。","respondent":"山本防災課長","answer":"初動の対応ですけれども、もちろん区だけでなかなか対応は難しい部分もありますが、例えば避難所ですと、防災区民組織主体で開設と運営を行うこととなっていますので、そういった地域の方、それから区職員等々、あと事業者の方といったところで連携しながら。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問・要望","question":"マグニチュード８クラスの大地震が起きたときに、ブロック塀や家屋の倒壊など、火災また延焼など、人命救助が緊急に求められた場合ですが、こういうときは、区の職員の方は、現場で救助作業に参加できるのですか。生身の人間です。でも、それでもし出てしまったら、後方支援というのは一切、また、命令系統も途絶えてしまうと思うのですけれども、その前にこういうことができるのですか、教えてください。","respondent":"山本防災課長","answer":"緊急の救助活動ですが、基本的には消防等が行う役割だというふうには考えてありますが、区の職員が参集場所に参集する途中でそういった場面を見ましたら、救助を行うことは当然だというふうに考えてあります。","id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"最後にお聞きしたいと思います。実際、先ほども通行が遮断された場合に、私は、各地域にやっぱり備蓄倉庫がもう必要な時期ではないかと思うのです。様々な地域センターにも用意されています。それからもう１つ、避難所ですけれども、このコロナ禍では、課長、圧倒的に足りないですよね。でも、このコロナ禍では実際はできないではないですか。私は圧倒的に足りないと思うのですが、ご見解をお聞かせください。","respondent":"平原防災体制整備担当課長、山本防災課長","answer":"私からは、備蓄倉庫のことにつきましてお話しします。委員ご指摘のとおりでございまして、各学校の備蓄倉庫以外に、区内２５か所に分散して備蓄倉庫を用意させていただいているところです。コロナ禍の避難者の受入れですが、確かにコロナ対応ということで４割減になってしまいますけれども、ホテル旅館組合等にご協力をお願いしていますし、あと、在宅避難等を推奨しておりますので。","id":"exchange-128"},{"speaker":"中塚委員","kind":"質問","question":"３２１ページの都市計画道路に関わって、補助２６号線における今年９月１８日の道路冠水について伺います。次に、３５１ページの防災対策に関わって、ホテルを借り上げた避難所について、それぞれ伺いたいと思います。そして、この排水システムは、雨量が何mm対応なのか、それぞれお伺いいたします。","respondent":"鈴木都市計画課長","answer":"何cmぐらいの冠水かというところまでは確認がとれませんでした。それから３点目、排水のポンプがついているわけですが、基本的には１時間６０mmの雨量に対応できる設備となっているです。","id":"exchange-129"},{"speaker":"中塚委員","kind":"質問・要望","question":"ポンプが稼働する前だという説明でありました。車は、３０cm水がたまるとエンジンが止まるというふうに伺っております。そこで、今回、東京都道ということになりますので、排水システムの強化、この６０mm対応ではなく、もっと強化をすることや、冠水した際に、素早く車両の進入を止めるための対策の強化を東京都に求めていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"その後、供用開始されまして、局所的に６０mmを超える豪雨が降りそうだというときの対応等も含めて、これは東京都にしっかり、その場、その場に合わせて対応していただけるのだというふうに思っているところです。","id":"exchange-130"},{"speaker":"中塚委員","kind":"提案","question":"東京都が考えることとおっしゃいますけれども、その６０mm対応を超える豪雨の際に、事故が発生しないように強く東京都に求めていただきたいと思います。私の提案は、この従来計画を変更して、災害発生後にホテルを借り上げ避難所にしていただきたいということです。従来の計画を変更して、ホテルを借り上げ、避難所として活用していただきたいと思いますが、いかがでしょうか。","respondent":"山本防災課長","answer":"ご提案いただいているホテルの利用につきましては、あくまでも避難所での受入れができない場合の補完的な利用を区としては想定しています。","id":"exchange-131"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり避難所の受入れができないときの補完的なものだということですが、この計画をなぜ変更することができないのか、改めて伺いたいと思います。私は、体育館があふれたときのホテルの活用ではなくて、発災後に、学校から借り上げたホテルに移動して避難所とすることにしていただきたいのですけれども、なぜこれができないのか、伺います。","respondent":"山本防災課長","answer":"できない理由ですが、考え方として、ホテル旅館組合と災害時協力協定を結んですが、協定の趣旨からすると、区で対応が難しい場合に事業者の力を借りる、そういったことかと考えていますので、区で対応できる場合は、当然区で責任を持って避難所を開く、そういう考え方です。","id":"exchange-132"},{"speaker":"中塚委員","kind":"質問・要望","question":"現状がそういう協定であるならば、その協定の中身を変える必要があると思います。こうした中、品川区も避難所環境の改善へということで、この間、パーテーションなどの備蓄も１,２００人分用意しておりますけれども、やはり避難所を学校の体育館からホテルに変更することで、避難所の環境を大きく改善することができると私は思いますけれども、協定の変更も含めて、ご答弁いただきたいと思います。","respondent":"山本防災課長","answer":"感染症対策等も実施していますので、区民の皆様には安心して避難所のほうに避難いただければというふうに考えてあります。協定の見直しについても、今のところ考えてございません。","id":"exchange-133"},{"speaker":"中塚委員","kind":"質問・要望","question":"協定の変更は考えていないとご説明がありましたが、ぜひ変更を検討していただきたいと求めたいと思います。次に、ホテルを避難所として運営する場合の経費についてお伺いいたします。熱海市では、ホテル避難所の経費が４億７,３００万円ということで、国、県、市が共同して設置、運営をしたと伺っております。補助制度というのか、経費の負担についてご説明いただきたいと思います。","respondent":"山本防災課長","answer":"品川区の場合でですが、こちらが、人口等によって、いろいろ変わってくるのですけれども、品川区に当てはめますと、住家の滅失が１５０世帯以上ある場合であったり、あと、住家の滅失世帯が都内で２,５００世帯以上、かつ区で７５世帯以上等。","id":"exchange-134"},{"speaker":"中塚委員","kind":"質問・要望","question":"災害救助法が適用された場合ということで、後半のほう、様々条件があってよく分からなかったのですけれども、満たせば適用されるということですが、つまりは、ホテルを避難所として品川区が借り上げた場合、国、東京都、品川区も、それぞれが経費を分担するということになるのか、その条件に品川区は合うのか合わないのか、ご説明いただきたいと思います。","respondent":"山本防災課長","answer":"品川区が条件を満たすかどうかというところですけれども、先ほどちょっと申し上げましたけれども、例えば住家の滅失、全壊が区内で１５０世帯以上ある場合、あと、住家の滅失世帯が都内で２,５００世帯以上あった場合で、かつ、区内で７５世帯以上の滅失。","id":"exchange-135"},{"speaker":"中塚委員","kind":"質問・要望","question":"被害の状況によって災害救助法が適用されるかどうかが決まるということで、つまりは、災害救助法が適用される場合については、品川区がホテルを借り上げての避難所の経費は、国、東京都、品川区の３者が、それぞれ負担をするということでよいのか、この点、改めて確認させていただきたいと思います。ぜひ品川区でも実施をしていただきたいと思いますが、改めていかがでしょうか。","respondent":"山本防災課長","answer":"区内の場合で法の適用があるかですが、この辺りは国のほうで事務取扱要領等が出てございまして、災害救助法の救助項目で１つ、避難所の供与というところがございまして、それに関しては補助が出ることになってありますが、その中で避難所での避難生活が長期にわたる場合において。","id":"exchange-136"},{"speaker":"中塚委員","kind":"質問・要望","question":"今までは避難所、また避難生活というと、学校の体育館をいかに改善していくかということで、私自身もそう思っておりました。ぜひこの経験を品川区でも活かしていただきたいと思います。従来の考え方を変更して、ホテルの活用を重ねて検討していただきますよう要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-137"},{"speaker":"せお委員","kind":"質問","question":"私からは、３１５ページ、交通安全啓発費、３１７ページ、道路点検システム費についてお聞きします。初めに、道路点検システム費です。このシステムはどのようなものなのか、教えてください。そして、このシステムによって、どのような効果というか、利点があるのかも併せてお聞かせください。","respondent":"溝口道路課長","answer":"そういった中で、日頃からしっかり安全点検をして保全型の道路維持管理をすることによって、区民からの苦情が減ってきたというのが１つの大きな効果だと考えているところです。","id":"exchange-138"},{"speaker":"せお委員","kind":"質問・要望","question":"こちらに加えて、区は、今年の６月から東京都が試行を始めていた「My City Report for citizens」という、スマホアプリを使って道路の損傷や不具合を簡易に投稿することができる道路通報システムの試行を始めました。そこで、まだ始めて４か月ほどしか経っていませんが、このアプリの利用状況をお聞かせいただきたいのと、今後の方向性をお聞かせください。","respondent":"溝口道路課長","answer":"今後ですが、今、４か月間使ってみて、特に不具合等があるわけではありませんし、また、職員としては、今回のシステムの中では、通報を受けたものから処理経過までを含めて一貫して返せるようなシステムになっておりますので、かなり事務の軽減が図られたというところ、また。","id":"exchange-139"},{"speaker":"せお委員","kind":"質問","question":"まだ少し通報が少ないかもしれないのですけれども、有効な取組みだと思うので、全体的に、まず周知をお願いしたいと思います。例えば、商店街だったり、あと町会・自治会などで、代表の方がアプリを取り込んで利用していただくといったお知らせをするのはいかがでしょうか。そういった積極的な今後の取組みについても見解をお願いします。","respondent":"溝口道路課長","answer":"やはり利用者の拡大、まずはこの制度を知ってもらう、このアプリを知ってもらうことから始まると思いますので、委員ご提案の件も含めて、さらに周知を図っていきたいというふうに考えているところです。","id":"exchange-140","title":"町会・自治会支援"},{"speaker":"せお委員","kind":"質問・要望","question":"積極的に周知をお願いしたいです。さらに今年の予算特別委員会で、公園の遊具を少し取り替える程度だと、利用者などにはご意見を伺っていないとお聞きしました。公園においては、損傷や不具合などとともに、それぞれの公園に対するご意見も伺えるようなアプリを取り入れていただきたいと思っています。区民の方の声を伺えるとともに、公園課などの職員の負担も軽減できると思います。","respondent":"高梨公園課長","answer":"２６８の公園・児童遊園等がありますけれども、異常だけではなくて、そういった利用者の声がいただけるといったところは、区の公園管理にとっても非常に有益だというふうに考えておりますので、システムの中身等、十分確認しながら、公園・児童遊園についても。","id":"exchange-141"},{"speaker":"せお委員","kind":"質問・要望","question":"これはまだ検討もされていないわけですから、１点、要望だけお伝えしますが、今後は、アプリ内などで、例えば、「おむつ替えがスムーズにできる公園」というところをタップすると、その公園一覧が出てくるという、設備からの検索機能も欲しいです。なので、先ほどお話ししたような公園に関するアプリが実現すれば、このような機能も取り入れていただきたいと今は要望で終わらせます。","respondent":"川口交通安全担当課長","answer":"令和２年度中に、それぞれ区では警察などと連携をいたしまして、例えば大井町でありますとか、武蔵小山などの自転車の多い駅等での安全利用のキャンペーンや、また、各区立学校等において、自転車シミュレーター等を活用した交通安全教育等も実施しております。","id":"exchange-142"},{"speaker":"せお委員","kind":"質問","question":"そこで、自転車運転免許証を品川区が作成することも１つの手段ではないかと思っています。法的な効力はないですが、講習会や実技、筆記試験を行って交付すると、気持ちが引き締まると思います。意識づけの問題だと思います。そのほかにも自治体独自の免許証を発行している区市町村はあります。今ご紹介したような様々な取組みや、民間活用も含めて、今後の自転車の交通安全対策について見解をお願いします。","respondent":"川口交通安全担当課長","answer":"品川区では、自転車の交通安全教室を実施する際には、参加していただいた方に、交通安全の講習会の修了証ということで、これは反射材を兼ねたシールを配布させていただいて、安全意識の啓発に努めているところです。それぞれ、今いろいろなご意見をいただいております。","id":"exchange-143"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、３１５ページ、交通安全啓発費で、これは補助２６号線の開通に関わってということです。それから、３２５ページの治水対策推進助成事業とか、３５５ページの集中豪雨等対策費、この辺に関連して、防災対策としての流域治水ということに関してお伺いしたいと思います。側道工事というのはどういうものかということです。","respondent":"鈴木都市計画課長","answer":"それから２点目の自転車の走行ですが、今現在、大崎高校側は、一部供用開始されたトンネル内に歩道と色分けされた自転車走行レーンが整備されて、そこが供用開始されてありますが、基本的には、１０月２２日に供用開始される車道部分につきましては。","id":"exchange-144"},{"speaker":"塚本委員","kind":"質問・要望","question":"自転車はトンネルのところに来たら脇に、今後整備される側道等も、そういったことに関しては通れるような形にうまく誘導できるといいますか、間違って車道に入っていかないような、そのような工事がなされるのだろうというふうに思います。その当日については、警備体制等は、警察官の方が出張られるのか、警備の方々が出張られるのか、何かそういう対応はとられるというふうに聞いていますでしょうか。","respondent":"鈴木都市計画課長","answer":"当日は、開通記念式典的なところは行わないというふうに聞いてありますが、時間に、午前１１時になりましたら、両サイドから警察の、これは白バイなのかどうかはあれですが、まず一般車両を入れずに。","id":"exchange-145"},{"speaker":"塚本委員","kind":"質問・要望","question":"１０月２２日以降の待望の開通ということで、区民の皆さんが安全に利用できるようにということで、お願いしたいと思います。次に、流域治水のことについてなのですけれども、大型台風とか、線状降水帯とか、水害の危険性が高まっておりますけれども、水害というのはあらかじめ予測ができるというところで、適宜適切な対応が求められていると思います。","respondent":"栗原河川下水道課長","answer":"協議会の中では、流域治水プロジェクトとしてまとめた河川や下水道の整備内容に合わせまして、区で行う雨水浸透の対策や避難体制等の強化につきまして情報を共有いたしまして、先ほどご説明のあった、国の中でも計画が策定されたところですが。","id":"exchange-146"},{"speaker":"塚本委員","kind":"質問・要望","question":"この流域治水の行動計画ですか、４つの柱があるのですけれども、その１つに、流域全体を俯瞰した総合的かつ多層的な対策というような柱がございまして、その中にるるいろいろ書いてありますけれども、特にその中から情報発信というか、情報の管理というか、そういったところについて少しお伺いしたいのですが、この行動計画の中で、マイ・タイムラインの取組拡大、防災アプリと連携した避難行動の支援。","respondent":"山本防災課長","answer":"併せて、マイ・タイムラインのところですが、作成を通じまして、それぞれの避難場所等、こちらのほうの確認をついでにしていただけるよう、こちらも改めて平時における啓発というところで力を入れていきたいというふうに考えてあります。","id":"exchange-147"},{"speaker":"塚本委員","kind":"質問・要望","question":"例えば、今後の流域治水に関わる情報の提供というのですか、やっぱり正確に適宜、また、その地域に即した情報というようなことで、しっかり発信していくというようなことで、これは現段階ではなかなか具体化というのは難しいかもしれませんけれども、ビッグデータとか、ＡＩとか、そういった技術を駆使しながら、様々な防災アプリ等を活用するなどして。","respondent":"山本防災課長","answer":"情報発信につきましては、区民の方の適切な避難行動につながるよう、新しい技術等を活用しながら、区といたしましても、迅速かつ適切な情報提供を行っていきたいというふうに考えてあります。","id":"exchange-148"},{"speaker":"石田（秀）委員","kind":"提案","question":"初めに、東品川海上公園の、いろいろこれから、桟橋、艇庫というような話でありますけれども、これは本当に我々としては待ちに待ったというか、お願いをずっとしてきたわけでありますけれども、これは確認なのですけれども、やる方向でいって、管理は民間でやっていこうということでいいかと思っているのですが、そういう形でいいのであれば、１つ、これで提案をしたいのは、艇庫の辺りというか。","respondent":"栗原河川下水道課長、高梨公園課長","answer":"１点目、東品川海上公園の桟橋ですけれども、現在、東品川海上公園の公園拡張整備に伴いまして、桟橋の整備を今年度実施する予定で、請負業者が決定したところで、現在、工事の着手に向けて。区といたしましても、地域の方々が求めている形の活用のためには、どういったことができるかといったところ、積極的に関わってお話をさせていただければというふうに考えているところです。","id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"質問","question":"それからもう１個、公園のことでお願いをしたいのだけれども、都立みなとが丘ふ頭公園、これ、珍しく港湾局が管理をしているところなのだけれども、いろいろ地図を見ると、例えば野球場とか、サッカー場とかをやれるというと、品川区で見ていると、もうあそこぐらいしかないのです。それからもう１個は、公園で、さっき四季の花という話をしたのだけれども、紅葉をどう考えているのかなと。モミジの赤。","respondent":"栗原河川下水道課長、高梨公園課長","answer":"景観につきましても、現在まとめております水とみどりの基本計画・行動計画の中でもうたっておりますけれども、陸側からの水辺景観だけではなくて。しっかりと受け止めさせていただきたいと思いますが、紅葉だけにとらわれずに、例えば遊具の色であったりとか、そのほかのもので、これからは特徴ある公園づくりといったものが求められるということも考えておりますので、総合的に見て。","id":"exchange-150"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"水族館なり、レストランだって、例えばそれは飛行機の問題も夜便だとしたら、やっぱり午後１０時ぐらいまでは開けていないと、もう１つの話は、総務費でやったからいいけれども、そういうインバウンドの人とかも含めると、やっぱり夜間営業は必要なのではないのかなと、そういうことも含めて建て替え計画を出してくるべきと考えていますので、最後にそこだけ伺いたいと思います。","respondent":"高梨公園課長","answer":"営業時間の周辺との兼ね合い等もありますので、そういったところの周辺への丁寧な説明を踏まえて、今後のしながわ水族館の営業時間のあり方についても、しっかりと検討していきたいと考えております。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/685794?Template=document&Id=1508#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":120356,"voices":354}},{"id":"r03-20211012-4","meetingId":"r03-c-settlement","date":"2021年10月12日","dateIso":"2021-10-12","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を146件抜き出しています。","topics":[{"id":"topic-01","title":"◯渡部委員長 ただいまより、決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","agenda":"◯渡部委員長 ただいまより、決算特別委員会を開きます。 それでは、令和２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"おはようあります。私からは３６７ページ、オリンピック・パラリンピック教育推進事業、時間があれば、成果報告書４６ページの学校ＩＣＴ活用経費についてお伺いします。１点目、オリンピック・パラリンピック教育推進事業の中で、オリ・パラ教育について、何点かお伺いしたいと思います。オリ・パラが閉会いたしまして、この開催の可否であったり、実施の内容、紆余曲折あって、今回の形に進んだと思います。","respondent":"工藤指導課長","answer":"オリンピック・パラリンピック教育につきましては、特に令和２年度からのコロナ禍におきましては、体験や講演などをオンラインによって実施することで、ねらいとした学びは一定程度達成できているものです。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問・要望","question":"特に、障害者理解に関しては、オリ・パラ教育の大きなレガシーの１つになると思っていまして、ぜひ続けていただきたいという思いで質問していきますが、このオリ・パラが閉会して、これまでのオリ・パラ教育は、国や都の補助金もたくさんあって進めてきたところがあると思うのです。この補助金の今後の見通しで何か聞いている情報があればお聞かせいただきたいと思います。先にその２点お願いします。","respondent":"工藤指導課長","answer":"引き続き、パラスポーツの体験やアスリートとの交流を継続し、障害者理解などの資質を高め、オリンピック・パラリンピック教育のレガシーとして取り組んでまいりたいと考えています。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"提案","question":"補助金が非常に厳しいというお話をいただきました。私個人としては、いつもボッチャを推していまして、以前も区民大会や区の公式スポーツにボッチャをというご提案もさせていただきました。パラスポーツで学ぶではなくて、交流をするというのが１つ大きな事業になるのかなと思いますので、そちらもあわせてご見解をお聞かせください。","respondent":"工藤指導課長","answer":"これまでも区立学校におきましては、ブラインドサッカーの体験教室、また、ボッチャ体験、あるいは車いすバスケットボールのパラアスリートとの交流などを実施しており、児童・生徒の感想の中には、やはり相手の立場や気持ちを考えることの大切さを学んだ。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"ぜひ前向きに障害者とともにパラスポーツを通じて、遊んだり、競い合えたりという働きかけをお願いいたします。次の質問、５つの資質の中の国際的な視野についてもお伺いします。国際交流というところで、英語教育についてお伺いします。初めに、今、小学校から英語学習をしていると思います。その意義をお聞かせてください。","respondent":"工藤指導課長","answer":"小学校から英語学習を行います意義につきましては、やはり、現在小学校１年生から繰り返し英語の音と文字に慣れ親しむとともに、英語というツールを用いて相手のことを知り、思いやるなどのコミュニケーション能力を高めていくために。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"提案","question":"国際的な視野、国際交流というところでいうと、ぜひ会話の能力を養っていただきたいと思っていまして、英語で会話するということを主にした授業の取組を継続的に取り組んでいただきたいなと思っています。ポートランド、オークランド、ジュネーブの３都市のどこかで、ぜひ子どもたちとＺｏｏｍを通じて英会話の交流というのをご提案させていただきたいと思いますが、ご見解をお聞かせください。","respondent":"工藤指導課長","answer":"英語学習として成果は期待できるものの、相手となる学校の選定につきましては、時差の問題など、調整しなければいけないことが多少あり、今後、研究が必要であると考えています。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"意見","question":"まさに時差の問題があって、調べると、ジュネーブやポートランドは非常に時差があって、なかなか難しいのですが、オークランドに関しては４時間程度プラスになるということで、こちらが１０時だとあちらが１４時など、ちょうどいい時間になるのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"３６３ページ、人権尊重教育推進経費と、３６５ページ、市民科・各教科充実経費。３８１ページ、給食運営費、食器購入等については、強化磁器食器以外のお箸、スプーン、フォーク、トレーなどについて伺います。人権であります。そうしたことも含めて、この人権教育プロジェクト、「わたしたちの権利」日本語版教材の活用を提案というか、求めたいと思いますが、区の教育委員会の見解をお知らせください。","respondent":"矢部教育総合支援センター長","answer":"人権関係の資料のご提案です。本区としましては、人権教育は大変大事だと考えております。様々、いい資料も作成してあったり、また、それぞれの情報提供をいただいておりますので、ぜひ内容をしっかり確認して、教員研修等での活用等を研究してまいりたいと思います。","id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"ぜひ積極的に活用していただきたいと思います。これについては、また機会を捉えていろいろと確認等をさせていただければと思います。昭和６３年の第２回定例会で、会派の先輩議員が当時、食育という視点も含めて、陶磁器を提案しています。木材は木材。それから、ステンレスについては、８０％以上がしっかりリサイクルをされると伺っておりますが、そうした中で、破損による取替えが年間約２,０００万円弱。","respondent":"勝亦学務課長","answer":"こちらについては、丈夫で劣化しないという、メリットが非常にあるものではありますけれども、裏を返しましたら、リサイクルや廃棄が難しい。そういった自然に帰らない素材という課題があります。そういった部分につきましては、今後、研究を重ねてまいりたいと考えております。","id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"これは、私もいろいろ確認をさせていただいて、ここについての課題というのは、これまで学校給食の食器等を提供している事業者も、いろいろな工夫をして、いろいろなトレーを提案しているというのも理解しています。別の機会で伺いたいなと思いますので、その辺りも頭に入れておいていただきたいなと思います。図書館としてのコーナーの支援や、まさにその資料提供について、その辺りを教えてください。","respondent":"吉田品川図書館長","answer":"とある小学校では、寄贈された関連書籍４６冊につきまして、学校図書館のコーナー内に設置しているところです。複数の学校で、教科学習においてＳＤＧｓの関連図書を活用しまして、また、選書の際に考慮している様子が報告されているところです。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"そこは、さらに推進していただきたい。全体として、各学校でもそういった書籍に触れる機会をこれまで以上に増やしていただきたいと思います。最後、時間があればご答弁いただきたいと思いますが、図書館について、２学期が始まって、コロナに関連して積極的に学校に行かないというお子さんもいらっしゃったりして、それが相当数出たとあります。最後、時間の限りでご答弁いただければと思います。","respondent":"吉田品川図書館長","answer":"図書館員につきましては、平日の昼間、図書館にいる子どもを見かけましたら優しく声をかけるなど、居場所としての図書館として、様子を見守ることとしています。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３６５ページ、市民科・各教科充実経費、３６７ページ、体力向上推進事業、同じく３６７ページ、グローバル人材育成塾についてお伺いいたします。最初に、３６５ページ、市民科・各教科充実経費に関連しまして質問をさせていただきたいと思います。具体的に、この片づけの授業をされているのかどうか、確認させていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"片づけの指導の内容です。基本的に、児童・生徒はたくさんの荷物、教材を持って生活しておりますので、４５分や５０分、その授業の中で１つ１つ片づけを指導します。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"片づけの授業はされておられるということで確認をさせていただきました。それで、片づけというのは、家庭でも行わなければいけないという部分を当然私も認識していますけれども、やはり学校でも、特に小学生、低学年から高学年、全学年含めて、定期的に片づけの授業をしていただきたいと思います。整理整頓ができず、片づけができていない職人と、きちんとできている職人。お願いします。","respondent":"矢部教育総合支援センター長","answer":"片づけの今後についてですが、先ほど言い漏らしました、市民科の中でも単元がありまして、そこでも指導しますので、これは全校で取り組むことになっています。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、３６７ページ、体力向上推進事業についてお伺いいたします。現代の子どもたちの運動離れ、体力低下というのは、学校教育の１つの課題だと思っています。６年生の男子の全国平均、長座体前屈が３４.９ｃｍに対して、品川区は３６.２ｃｍ。女子も、全国が４０.３ｃｍに対して、品川区では４１.９ｃｍ。この結果を踏まえて、今どのように捉えているのか、お尋ねしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"ただし、昨年度は、コロナの関係で体力調査が希望校のみになっておりまして、正確な数値を全体的に比較できないのですが、一昨年までは伸びているということを踏まえた上で、今後のことについて捉えも含めてお話しします。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"やはり、いろいろ取り組んでいる結果の表れが、この体育の数値にも反映されていると考えています。ありがとうございました。続きまして、同じく３６７ページ、グローバル人材育成塾についてお伺いいたします。グローバル人材育成に関わる取組について、私がご紹介というか、述べさせてもらったのですけれども、本当に具体的でいいのですが、取組内容を教えていただきたいと思います。","respondent":"工藤指導課長","answer":"直近で、今年度も令和３年度から令和４年度までのところで、９月から開始しておりますが、現在２６１名が学んです。外国人講師との英会話レッスンを通しながら、実践的な英会話能力を身につけるというところで取り組んでいる取組です。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、今年の１１月６日の土曜日に「SHINAGAWA GLOBAL DAY」を実施するということで、これは午前の部が各学校における学校公開。そして、午後の部は、オンラインで動画を配信するということなのですけれども、学校公開ということで、それぞれ学校単位でやることだと思うのですが、具体的な内容がもう少し分かれば教えていただければと思います。よろしくお願いします。","respondent":"工藤指導課長","answer":"本年１１月６日土曜日に予定しております「SHINAGAWA GLOBAL DAY」のお尋ねです。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"確認","question":"よく分かりました。これは、各学校によって公開授業をやるわけですよね。それを確認させてください。これは、それぞれ学校ごとに、英語教育や市民科、オリ・パラ教育をやるということでよろしいのでしょうか。","respondent":"工藤指導課長","answer":"万が一、コロナ禍によって、直接授業参観ができなくなった場合、そういった動画配信によって授業の様子を見ていただき、子どもたちの様子を参観いただければと取り組むものですので、各学校の時間割については、各校ホームページで確認いただければと考えています。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"３５９ページ、校外授業費、移動教室・修学旅行、ページはありませんが学校でのコロナ対策ＰＣＲ検査、３８１ページ、普通教室増設工事等に関連して３５人学級について伺います。今年度は、第５波で１度は中止になってしまった移動教室や修学旅行ですが、感染状況を見定めつつ、改めて実施できるように各学校を支援していただきたいのですが、いかがでしょうか。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"現在、緊急事態宣言が解除されましたので、今後、こういった貴重な機会、特に今の６年生は昨年度も日光に行けていないので、今年、このまま卒業しますと、日光に行けずに卒業してしまうことになってしまいますので。２月、３月にも６校予定してございまして、１校は代替のもので変えていくですが、時期がずれたことによって、もう一度下見をしたり、保護者にしっかり理解を得たり、また、宿の方との連携をしたり、学校としても工夫しながら。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"ぜひご支援よろしくお願いしたいと思います。ＰＣＲ検査なのですが、まず、今年度の学校の児童・生徒の感染者数、教職員の感染者数は何人なのか伺います。","respondent":"勝亦学務課長、工藤指導課長","answer":"今年度の児童・生徒の陽性の判明者数につきましては、昨日までの累計で３４７名となっています。令和３年度４月以降、教職員の感染者数につきましては、昨日現在で３８名です。","id":"exchange-018"},{"speaker":"安藤委員","kind":"確認","question":"衛生費のほうでガイドラインについて伺ったのですが、濃厚接触者と判定されなくても、感染者が発生した同じクラス、同じ部活等の全員に、学校の判断での検査の実施を可能とすると、８月２７日付の文部科学省ガイドラインの区の対応について伺ったのです。保健予防課長の答弁は、通知が出る前からそのような対応をしていて、何ら変わりないという感じの答弁だったのです。","respondent":"勝亦学務課長","answer":"学校内で陽性者が出た場合につきましては、その児童・生徒の学校での行動の状況、給食の時間や体育の時間も含めまして、時間ごとにマスクの着用があったか、クラスでどのような行動をしていたか、そういったものを１つ１つ確認いたしまして、濃厚接触の疑われる者に対して。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"濃厚接触者が疑われる、濃厚接触者と断定しなくてもということで、少し広く考えているということだと思うのです。伺いたいのですが、先ほど、今年度の学校の子どもの感染者は３４７名ということでした。では、実際に行政として実施した検査は、子どもと教師、どちらとも聞きたいのです。今年度は何人に実施されたのか。人数を伺いたいと思います。","respondent":"勝亦学務課長、工藤指導課長","answer":"ＰＣＲ検査についてです。先ほど申し上げましたように、必要な方に必要な検査を保健所と相談しながら実施していますけれども、ＰＣＲの検査数は、今年度につきましては、１,８９４人に実施しております。教職員の今年度の検査数につきましては、１７２件です。教職員につきましては、品川区に限らず、居住地域の保健所等の指示によって受けているものがありますから、そういったものも含まれているとご理解いただければと思います。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"よろしくお願いしたいと思います。決算書には、普通教室増設工事等の事業もありますが、芳水小学校と第二延山小学校の１・２・３年生について、来年４月から学校が法律どおり３５人の学級編制を実施すると決めた場合、現在、それに対応する教室は既に確保されているのでしょうか、伺います。受入可能な環境をつくるため、区教育委員会としてはどのような措置、対応を行ったのでしょうか、伺いたいと思います。","respondent":"勝亦学務課長、有馬庶務課長","answer":"そういった中で、３５人編制の義務標準法が改正されておりますので、経過措置を含めて、３５人学級および経過措置にしっかり対応しています。具体的な教室の確保ですけれども、芳水小学校、第二延山小学校とも、多目的室を普通教室に変える、第二延山小学校は、やむを得ず、今回は和室を普通教室化するというところで教室を確保して、来年に備えるという対応をしています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"教室を確保している。先ほども質疑がありました。伺いたいのですが、少なくとも子どもの日常の教育条件に直結する学級規模については、これがいいだろう、３学級で行ったほうがいいだろうと、学校だけで決めるのではなくて、きちんと保護者、子ども自身に十分に理解できるような説明も行って、さらに意見を聞いて、その意見を踏まえて決めるべきだと思うのですけれども、そこについてはいかがでしょうか。","respondent":"勝亦学務課長","answer":"学級編制のお問合せです。法律的に、学級編制につきましては、区が責任を持って行うことになっております。そういった中で、各学校の状況、学校の意見を聞きながら、編制してまいりたいと考えております。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"その学校の意見を聞きながらというのは当然だと思うのです。私が伺ったのは、学校が判断する上で、子どもや保護者の意見も踏まえた上で判断すべきなのではないですかと伺ったので、もう一度しっかりとお答えいただきたいと思います。","respondent":"勝亦学務課長","answer":"おっしゃるように、アンケート等、そういった考え方もあろうかと思いますけれども、各学校が日々、お子様の様子や保護者の声、お子様の声を聞いてあります。その中で最善の教育ができるように学校も判断をして、意見をいただいて、区のほうで判断しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは、私は子どもの権利条約の精神に反するというか、子どもの声を聞くということを直接やらないといけないし、かなり学校の傲慢ではないかと思います。教育環境に関することですので、しっかりと子ども、保護者の意見を聞いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"私からは３６３ページ、いじめ防止対策費、３７１ページ、図書館運営費、時間がありましたら、３７１ページ、まちの人々に学ぶ授業経費を伺っていきます。現在、品川区で配付されているタブレットのチャット機能の利用について、制限をしているのか、それとも授業中に利用しているのか、もう１点伺います。メリット、デメリットの認識、また、今後の利用についての協議や検討状況をお伺いします。","respondent":"勝亦学務課長","answer":"そういった部分につきましては、このような問題を抑止できるというメリットはあると考えていますが、将来的には、社会に出てから、こういったものがあふれているところに出ていくことについて、すぐには体験できないというデメリットといいますか。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問","question":"その手前として、学校のほうで、まず、チャット利用やＳＮＳを現段階では利用できないようにしているというお考えを把握いたしました。品川区では、現在、配付している端末のＩＤやパスワードの運用について、どのようにされておりますでしょうか。例えば、このようにＩＤやパスワードが統一されていたり、誰でも簡単に類推できるような状況になっていないでしょうか、お聞きします。","respondent":"勝亦学務課長","answer":"パスワードに関しましては、配付の時点では、統一のパスワードですけれども、必ず他人に類推されないようなご自身のパスワードに変更して、他人に教えないということを指導の中で徹底しております。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"例えば、インターネット上の様々なシステム、サービスによってもそうなのですけれども、やはり簡単に類推できてしまうパスワード、誕生日を組み合わせたパスワードや、電話番号、ペットの名前など、どうしてもそういった分かりやすいパスワードにしてしまうという懸念があります。そのセキュリティ面についてお伺いします。","respondent":"勝亦学務課長","answer":"こちらの児童・生徒に設定していただくパスワードにつきましては、こちらは１つでアプリケーションの統一的なパスワードになりますけれども、５回以上間違えますとロックがかかるような仕様になってありますので、ハッキング等のおそれは少ないと考えております。","id":"exchange-027"},{"speaker":"くにば委員","kind":"確認","question":"今、お伺いした形で、基本的には高いセキュリティ意識を持って、今後も運用に取り組んでいただければと思います。それを受けまして、翌平成２０年には、文部科学省は、学校裏サイトについて調査をし、その調査結果である「青少年が利用する学校非公式サイト（匿名掲示板）等に関する調査について」を公表し、それによると、当時確認できた学校非公式サイトは、全国で３万８,２６０件。お聞きします。","respondent":"矢部教育総合支援センター長","answer":"全てにおいてですけれども、やはり担任と生徒がきちんと信頼関係を持って相談できる体制づくりが大事かなと考えておりますが、今後も、情報共有も含め、生活指導主任会のほうで対策も一緒に考えてまいりたいと思っています。","id":"exchange-028"},{"speaker":"くにば委員","kind":"質問","question":"直近３年間で１件程度。それに関して実害はないとお伺いしました。自治体によっては、教育委員会や、もしくは学校単位でネットパトロールを実施しているところもあります。品川区では、そのような学校単位でのネットパトロール、もしくは品川区の教育委員会として、ネットパトロールをどのように実施されているのか、その辺についてお伺いします。","respondent":"矢部教育総合支援センター長","answer":"独自のネットパトロールの方法ですが、現在、システムとしては特段ございませんけれども、やはり人と人とですので、生活指導主任会の情報と、我々の中では相談機関が様々ありますので、ＨＥＡＲＴＳも含め、いろいろな情報共有の中で。","id":"exchange-029"},{"speaker":"くにば委員","kind":"質問","question":"時間が短くなりましたけれども、図書館運営費、しながわ電子図書館についてお伺いいたします。例えば、一案なのですけれども、こちらは児童・生徒を対象にして、アニメ化作品、ドラマ化作品、もしくは小説賞を受賞した作品など、そういった切り口でのジャンル分けのコーナーを設けて、もう少し興味を引くような分かりやすい掲示方法をお考えになられてみてはいかがでしょうか。","respondent":"吉田品川図書館長","answer":"そのような形の中で、今後、蔵書を増やしていく中で、見せ方の辺りにつきましては、考えてまいりたいと思います。","id":"exchange-030"},{"speaker":"くにば委員","kind":"質問・要望","question":"時間がないので最後に伺いたいのが、現在、しながわ電子図書館に導入する選書の方法。どのような方が、どのように選書しているのか。その基準や、私の個人的な希望としては、前回の予算特別委員会でも取り上げましたが、児童・生徒の読書率向上に向けての施策推進ということで、特に子どもに向けての閲覧に関して、推進をしていただきたいのですけれども、その選書について、最後にお伺いします。","respondent":"吉田品川図書館長","answer":"電子図書館で導入できる電子図書につきましては、なかなか一般に販売されているものよりも種類が少ないなど、条件がいろいろあります。その中で、図書館として、図書館の職員が、これはまずは十分なものではないかというところから導入しています。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"教育費全般で、市民科、夜間中学、香害とＣＡＰ、校則について伺います。国は、中学生の不登校や在留外国人の子どもの就学状況が、不就学であったり、就学状況が確認できない状況があることや、虐待やヤングケアラーなどで実質的に義務教育を十分に受けられなかった人の教育機会確保のために、今年の２月に夜間中学の設置促進を各都道府県と各指定都市の教育委員会に依頼の通知をしています。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"先ほどの夜間中学校について、現在、ニーズの把握までは特別行っておりません。協議会のほうも、今のところは行ってございません。そういった直接的な声を、現状、聞いているところではないです。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"マイスクールのことは分かります。意見を聞かせてください。そして、校則についてです。そして、図書館で全校の校則が確認できるよう求めますが、見解を伺います。そして、区が求める生徒自らが考える校則が広がるように、子どもたちの議論により校則が変わった学校があった場合には、成功事例として、議論の様子などを区教育委員会としてホームページ等で広報するなどの取組を求めますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"そのような様々なやり方を通して、子どもたち、または地域の意見を吸い上げて、独自の校則ができていると認識していますので、それは１校の中で進めればよいのかと考えております。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"夜間中学については、ぜひ前向きに取り組んでいただきたいと強く要望いたします。ぜひ子どもたちが議論する場ができるように支援をしていただきたいと思いますが、見解を伺います。ＣＡＰプログラムについて伺います。教員向けプログラムに関しては、小・中全ての教員が、必ず最低でも１度は受講すること、そして、希望する教員に対しては、何回でも受けられるよう拡充を求めますが、見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"少し視点が違うかもしれませんけれども、体罰の防止については、何度も校内で研修していますので、その中からエキスを取って指導しているものと認識しています。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"５年生が残らず、何で３年生が残ってしまったんだろうと。必要なのは５年生のほうだったというご意見を伺っています。教員プログラムについてです。やはり、教員が子どものＳＯＳを受け止める方法を知ることができる、この教員向けＣＡＰの拡充を強く求めたいと思いますが、何かあればご意見ください。そして、あわせて、その相談を受け入れる体制も整えてほしいと求めますが、見解を伺います。","respondent":"工藤指導課長、勝亦学務課長","answer":"そういった意味では、体罰防止研修は、引き続きしっかりと行っていきたいと考えているところです。私からは、香りのことについてお答えいたします。香りに関係します化学物質過敏症の関係ですけれども、給食のかっぽう着等の対応につきましては、お声があれば個別に対応しております。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"ＣＡＰについてです。ですので、ぜひ広げてほしい、ＣＡＰプログラムをしてほしいと思います。要望します。香害のポスターについて、学校で貼ってくださっているのですか。少しそこを確認させてください。市民科に行きます。市民科授業地区公開講座について伺います。全学校の公開講座予定日を一覧にしたものを区教育委員会ホームページで掲載していただきますよう求めますが、見解を伺います。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"文部科学省の啓発のポスターに関しまして、適宜掲示するなど、活用をお願いしますということですので、そういった旨で学校のほうに送付しています。掲出に関しましては、各学校での判断になろうかと考えております。今年度につきましては、できる限りの方法でやるということを学校から聞いております。ホームページにつきましては、各学校から情報をもらっていただきたいと思います。","id":"exchange-036"},{"speaker":"木村委員","kind":"質問・要望","question":"教育費の３５９ページの中ほど、少し上でありますけれども、８３運動経費、７４万７,０００円からの質問をいたします。年末に向けてキャンペーンを実施しているそうですけれども、下校時にあわせて、地域の大人が野外での活動にあわせて子どもたちを見守る運動です。この運動を始めて、以前と現在では、子どもたちの登下校に対し、何が大きく変わったのでしょうか。あればお聞かせいただきたい。","respondent":"有馬庶務課長","answer":"８３運動ですけれども、これにつきましては、かつて小学校ＰＴＡ連合会が、子どもの安全をテーマに取り組んだということで始まってあります。","id":"exchange-037"},{"speaker":"木村委員","kind":"意見","question":"現在では、全国的に広がりを見せているということでありますけれども、この運動は、品川区から広がりつつあるということでいいのか。もしそうであれば、これは大変すごいことだなと思います。本区の考案した８３運動、今以上に全国に広がることを願いますけれども、今後の展開というものは、どのようになるものと想像されますか。","respondent":"有馬庶務課長","answer":"この８３運動は、品川区で生まれたと認識しております。ここからある程度全国に広がっていったということは、設立委員会の方からも話を聞いているところです。","id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"この時期、日暮れが早くなるためということを伺っておりますけれども、そう考えますと、夏は午後６時過ぎから７時近くまで明るいという状況であります。この８３運動を８４運動や８５運動などということは考えられないのかどうか、お聞かせください。","respondent":"有馬庶務課長","answer":"ただ、今はすまいるスクールなどがあって、夕方、帰りが遅くなるという部分も見られるかと思います。今は、別に時間にとらわれることなく、夕方の買物のときに見守っていただければ、その時間にとらわれなくてもいいですよということをあわせて周知していきたいと考えております。","id":"exchange-039"},{"speaker":"木村委員","kind":"質問","question":"臨機応変にお願いしたいと思います。次に、３６３ページの中ほどにあります、人権問題から質問をいたします。昨今、部落差別問題をはじめ、性の多様性など、子どもたちが正しく人権について理解し、互いに人権を尊重できるようにするなど、人権教育の推進が重要と考えます。現在、学校現場ではどのような取組を行いながら人権教育を進めているのでしょうか。お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"毎年１２月の人権週間にあわせまして、人権啓発課と連携いたしまして、品川区立学校人権標語・ポスター展を行っております。全校の児童・生徒が作品づくりを通して人権意識を高めるだけでなく、展示公開することで区民等への啓発にもつなげてあります。","id":"exchange-040"},{"speaker":"木村委員","kind":"質問","question":"いじめについて、先日、都内の小学校でいじめが起因していると疑われる痛ましい事件が発生いたしました。本区においては、これまでいじめ防止対策について、いじめは絶対に許されないという意思を持って取り組んでいることと思います。本区が掲げる、いじめ根絶宣言の実現に向けて、どのような取組を行っているのでしょうか。お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"全ての学校の７年生全員を対象に、学級風土調査というものを行っておりまして、毎年６月と１０月に実施する中で、学級の中で孤立している子はいないか、周りにあわせられない子は誰なのかなどを調査しております。いじめ防止推進デー等で推進しています。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"本日は３７９ページ、学校維持管理費、そして、３６３ページ、生徒指導対策等経費、これは校則についてお伺いしたいと思います。これはまず要望です。教師による児童・生徒へのわいせつ事件なども報じられてきた問題です。そこで、これは予算特別委員会の際もお伺いしたところではあるのですが、改めて教室等、学校内への防犯カメラの設置について検討していただきたいと要望いたしますが、見解を伺います。","respondent":"有馬庶務課長","answer":"カメラをどうしていくか。やはり、一定の抑止力はあることはあるのだろうとは思いますので、春のときは、トイレなどに設置するのはなかなか難しいと申し上げた記憶がありますけれども、拡充していくべきなのか、また今後、少し検討させていただきたいと考えています。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問・要望","question":"引き続きご検討いただければと思います。インターネットのＹａｈｏｏ！ニュースに、「校則で『三つ編み禁止』とまどう黒人ハーフ中学生特有の髪質に配慮求めるも『本数制限』が条件に」という記事が掲載されました。１つか２つに結ぶといった記載がどうしても出てきているのです。こうした校則は、マイノリティの問題もあるので、改めたほうがいいのではないかと思いますが、ご見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"ただ、先ほども少しお伝えしたのですけれども、これまでの経緯があるので、やめればいい、では、何でやめたのというところにもなりますので、その間の経緯は私たちもきちんと入りながら、相談に乗って、また、情報共有しているところですので。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問・要望","question":"もう一つは、これはしっかりご答弁いただきたいなと思うのですけれども、そういった髪質が理由で、１つか２つと校則に書いてあるけれども、それだと健康上、問題が生じるというときに、学校側が、それだったらいいですよという対応をしてくれるようにしていただきたいということを要望したいのですが、ここについてご見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"繰り返しになりますけれども、安全と健康に関わることについては、しっかり学校が向き合って、相談して、対応していきたいと考えています。","id":"exchange-044"},{"speaker":"松澤委員","kind":"確認","question":"そこで、品川区における部活動指導員、議事録では、現状１０校に１１人の配置、今後、１５校全部の配置を目指しているということでしたが、現状を教えてほしいのが１つ。このモデル実施に至っては、国の補助制度を活用し、負担の割合が国、東京都、区でそれぞれ３分の１、この事業について品川区で活用があったのか、２点確認させてください。","respondent":"矢部教育総合支援センター長","answer":"部活動指導員の現状です。昨年度につきましては、委員がおっしゃったとおりですが、現在は１校増えまして、１１校で１２人です。補助の点ですが、モデル実施という名称は異なるかもしれませんが、国や東京都の補助を受けて部活動指導員を活用、配置しております。","id":"exchange-045"},{"speaker":"松澤委員","kind":"確認","question":"１校増えて１２人、確認できました。昨年の９月１日、文部科学省で開催されました、第４回学校における働き方改革推進本部。そうすると、これからは平日の部活動と、休日の地域部活動に区別していかなくてはならないのかなと思いますが、区としてどのように捉えているのか、教えてください。そういった課題が見える中、部活動の委託についても区の考え方を教えてください。","respondent":"矢部教育総合支援センター長","answer":"１点目につきましては、国がこういう方向ですし、働き方のこともありますので、注視していきながら進めていけたら一番いいのかなと思っています。現在、部活動指導員のメンバーに地域の方もおりますので、そういったことは徐々に広がるとよいと考えております。","id":"exchange-046"},{"speaker":"松澤委員","kind":"質問","question":"要は、複数の学校で分担する考え。国が２０２３年度という部分には、これから何ができるか、引き続き考えていきたいと考えています。その中で、合同部活動指導員制度というものを少し耳にしたのですけれども、この制度はどこでやっているということを調べられなかったので、どのようになって、どうつなげているのか、教えてください。そのような考えはどうでしょうか、ご見解をお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"先ほどの小中連携部活動など、様々な地域でもいろいろな発表会を催していただいていますので、そういったところで参加されているのかなと認識しています。","id":"exchange-047"},{"speaker":"松澤委員","kind":"質問・要望","question":"小中連携部活動です。そういった中での小中連携部活動は、ぜひ率先して広げていってほしいなと考えています。一人ひとり、子どもたちが部活動をやりたいというものが少しでもできるような環境の配備を引き続き求めていきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"今、合同部活動、小中連携部活動については確認ができました。９校において小中連携部活動をやっております。追加です。失礼いたしました。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"提案","question":"施設整備のところなのですけれども、予算特別委員会でも、また、何年か前からお伺いしている台場小学校避難通路の件です。３階建てということで、津波や高潮の場合、避難するに当たって非常に心配だということで、隣接する都営住宅との間に避難通路を設けるということで、何年かにわたってこれは要望させていただいて、自治会長からのそもそものご提案だったのですけれども、要望してまいりました。","respondent":"小林学校施設担当課長","answer":"現在は、工事を発注いたしまして、製品の工場作製を行っているところです。工事完了につきましては、今年の１１月末までには設置ができる予定で現在進めております。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"提案","question":"それとあわせて聞いてしまいますけれども、品川区の中学生の英語の達成度、いわゆる一般的に言われるＣＥＦＲというのですか、Common European Framework of Reference for Languages、意味がよく分からないのですが、ヨーロッパ言語共通参照枠と日本語で訳されるようですけれども、つまり、英語レベルを世界的に。","respondent":"工藤指導課長","answer":"英語学習についてのお尋ねです。最初にご指摘いただいたＣＡＮ－ＤＯリストにつきましては、全区立学校でＣＡＮ－ＤＯリストを設定して、それに基づき指導しておりますので、そういう意味では１００％実施しています。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問","question":"かなり高い数値なのかと。教える側です。教える側がどうなのか。英語の授業を担当されている中学校、高校の校長から常勤の講師までを対象にして、ＣＥＦＲ・Ｂ２レベル、英検準１級以上のスコアを獲得しているのが、全国的には３８.１％ということなのですけれども、品川区の中学校においては、この割合というのは何％なのでしょうか。","respondent":"工藤指導課長","answer":"令和２年度、国が実施しました英語教育実施状況調査のところで、本区が回答した内容ですが、昨年度５９名在籍の英語教員のうち、ＣＥＦＲ・Ｂ２レベル以上という者は３９名、割合にして６６％いるということが分かったところです。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今のところ６６％ということですので、今後、スキルアップというものを図っていく上で、何か教育委員会として、例えば、建築課でいえば、建築士の資格を取る際に学校に行くための支援みたいなことをやっているのですけれども、ほかの部局でもそういう、いわゆる区民のために役に立つスキルを職員がつけるために、区が支援をしているというのがあるのですけれども、教育委員会としてもそういう指導というか。","respondent":"工藤指導課長","answer":"時期としては９月になりますけれども、先ほどの英語の各生徒の技能をはかるＧＴＥＣ調査というのを行いますが、それの活かし方ということで、いわゆる授業改善に資するというところで、やはり教員研修を実施して、それぞれの資質を高めているところです。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に、給食運営費、給食の牛乳のプラスチックストローの削減について、何度も質問させていただいていますが、３年前の品川区議会で、平成３０年１２月、「学校給食の牛乳にプラスチックストローを使用しないことを求める請願」というものを、全会一致で採択させていただきました。３年経つのですけれども、なかなか進まないという状況があります。","respondent":"勝亦学務課長","answer":"学務課で把握しておりますのは、品川区とも交流のあります高知県がそういったストローを使わない牛乳パックを使っているということで、実績としては、３分の２程度の学校がストローを使わない状態で牛乳を飲んでいると聞いてあります。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問","question":"そのとおりで、品川区と交流のある高知県、全県の３分の２がストローレスということで取り組まれている。今年の１月から取り組まれているということで、給食だけで年間３トン以上の削減になるということです。学務課にもう一回伺いますけれども、この請願の中にもあるのですが、品川区では、年間で何本のプラスチックストローをごみとして処理をしているのか分かれば教えてください。","respondent":"勝亦学務課長","answer":"ストローの本数です。今、品川の児童・生徒が約２万２,０００人、給食は大体年間１９０食ということで計算いたしますと、年間４２０万本余になるかと思います。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"請願の中に４２９万本ということで書かせていただきましたけれども、０.５グラム換算で約２.１トンぐらいのプラスチックを毎年、子どもたち、教職員の方が食事のために排出をしているという状況があります。自治体でもこれは取り組める話なのです。これについてしっかりと他自治体のことも見ていただきたいと思うのですが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"他自治体の事例も含めて、今後も、ストローの削減等につながる取組を研究してまいりたいと思います。","id":"exchange-055"},{"speaker":"おくの委員","kind":"質問・要望","question":"３８１ページ、給食運営費に関わって、学校給食の無償化をはじめ、義務教育で残されている教育負担費をなくすこと、義務教育の無償化全般について質問いたします。共産党は、この規定に基づいて、かねてから給食費の無償化を求めてきました。今回は、学用品、教材費、修学旅行費などの無償化を求めますけれども、この点、いかがでしょうか。","respondent":"勝亦学務課長","answer":"教育費の無償化に関するお尋ねです。おっしゃるとおり、憲法２６条には、義務教育はこれを無償とするという記載があります。ただ、教育基本法の中におきましては、こちらの規定を受けまして、義務教育等については授業料を徴収しないという記載があります。","id":"exchange-056"},{"speaker":"おくの委員","kind":"質問","question":"しかし、教科書などと同じ授業で使われる、例えば、書道セット、それは同じ授業で使われながら、なぜ有料なのか。同じ授業で使われる以上、同じように無償、無料であるべきなのではないでしょうか。例えば、これらの学用品、あるいは教材費、これは今のところ親の負担となっているわけですけれども、親の負担とする根拠は何なのでしょうか。この点、お伺いいたします。","respondent":"勝亦学務課長","answer":"こちら、様々な意見があるとは承知していますけれども、この考え方に立つものです。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"ですから、国や、ましてや自治体の判断で、無償化にすることができないわけではない。つまり、できるということではないのでしょうか。その点、お伺いいたします。","respondent":"勝亦学務課長","answer":"無償化にできないことはないのではないかというお尋ねですけれども、こちら、自治体によっては、そういったものを無償化にしている自治体もありますので、無償化ができないということでないのは、おっしゃるとおりです。","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、今、この品川区の中では無償となっていないわけですけれども、その点のご判断、品川区で無償となっていない、有償であるままだというのは、やはりどういう根拠なのでしょうか。その点をお伺いいたします。","respondent":"勝亦学務課長","answer":"繰り返しになりますけれども、基本的には、法の定めにあります授業料の不徴収、それから、教科書の無償給与、給食の食材費以外の負担という法の定めに従って考えているものです。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問","question":"それで、品川区がなぜ今有償のままかということをお伺いしているのですけれども、さらに、旭川の学テの判決などでも出ているのですけれども、無償性という憲法２６条というのは、子どもに対する基礎的教育である普通教育の絶対的必要性に鑑み、親に対し、その子女に普通教育を受けさせる義務を課し、かつ、その費用を国において負担すべきことを宣言したものだと。","respondent":"勝亦学務課長","answer":"区としましては、国の取っている法律、施策にのっとった形で対応していると考えております。先ほどのできることをやらないのかという部分につきましては、給食費の無償化等につきましては、区とも関わりのある早川町等もやっているやに聞いてあります。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"卒業アルバム費なども無償化しています。先ほどの私が申し上げました憲法２６条の趣旨からすると、無償化の範囲を広く取ることこそが２６条の趣旨にもかないます。品川区でも、このような趣旨を酌み取って無償化を行うべきだと思うのですけれども、もう一度お伺いいたしますが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"品川区におきましては、法の定めに従って執行していきたいと考えております。経済的に困窮のある方には、就学援助等々で対応していきたいと考えております。","id":"exchange-061"},{"speaker":"せお委員","kind":"質問","question":"ですから、それぞれの特性や状況にあった場所を自治体が用意してあげられるのが理想です。そこでまず、令和２年度は、３か所のマイスクールを何名の児童・生徒が利用しましたでしょうか。令和２年度に比べて令和３年度は現時点で増えていますでしょうか。そして、マイスクールへのニーズの高まりがあり、五反田の指導員は増員してくださったようですが、令和２年度が終わってみての課題は何でしょうか。","respondent":"矢部教育総合支援センター長","answer":"今後につきましては、今、委員おっしゃったように、様々な居場所というか、学習環境を見ながら、指導員を増やしたり、今、オンラインで学習ができたりしておりますので、そのような様々なメディアも通しながら検討していく予定です。","id":"exchange-062"},{"speaker":"せお委員","kind":"質問","question":"ホームスクール＆ホームエデュケーション家族会という当事者団体が、今年の３月１５日から４月１５日の１か月間、日本全国で家庭を拠点とした教育・学びに関するウェブアンケートを実施しました。こちらに参加されている保護者の方にもお話を伺いましたが、ホームスクーリングの現状を知ってもらいたいとおっしゃっていました。１、２年生へはどのような対応というか、支援をしているのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"本当に細かい一人ひとりの対応を保護者と連携をしながら進めていて、丁寧に１、２年生が楽しく学校に通えるような支援をしています。","id":"exchange-063"},{"speaker":"せお委員","kind":"質問・要望","question":"時々学校へ来られるお子さんの場合、どのような支援を学校内でされているのでしょうか。それに関連して、全国で校内フリースクールというのが少しずつ増えてきていますが、マイスクール五反田、浜川のような場所をどこかの学校内に設置してみるというのはいかがでしょうか。３点目、アンケート結果の３位でのオンラインに関連して、不登校のお子さんのタブレットの使用状況はいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ただ、実際には、ローマ字入力を習熟していないお子さんがいて、一人で進められないというお子さんも実際にいることは確かですので、個別の活用は差がありますが、それぞれに対応して、支援しています。","id":"exchange-064"},{"speaker":"せお委員","kind":"意見","question":"学校へはどうしても足が向かないお子さんに対しては、タブレットは効果的かと思うのですが、マイスクールなどに通われていて、今後、学校に完全に戻ったりとか、少しだけ通学することがベストだと判断されているお子さんに対して、タブレットを頻繁に使用してしまうと、戻れなくなってしまうお子さんもいるでしょうし、関わっている職員さんたちの判断はとても難しいだろうと感じています。これは感想です。","respondent":"矢部教育総合支援センター長","answer":"教育委員会としましては、特に生活指導についてはＨＥＡＲＴＳが、また、学校が限られますけれども、学校と家庭の連携事業というのがございまして、そこでは、各支援員が対象のお子さんのところまで迎えに行ったり、相談相手となったりして話をしています。","id":"exchange-065"},{"speaker":"せお委員","kind":"質問・要望","question":"最後に要望だけお伝えすると、アンケートには、学校の環境があわなくて行かなくなったみたいな結果もあるのです。タブレットも効果的に使用していただいて、個別最適化された学びができるよう発展していってほしいと思っています。令和２年は特別支援学級が２校で増えて、全ての義務教育学校に整いました。これはどのようなビジョンなのか、教えてください。交流の今後についても教えてください。","respondent":"矢部教育総合支援センター長","answer":"今年度は、大崎中学校の情緒障害の学級の創設です。２点目、交流活動については大変大事だと認識しております。全ての学校におきまして、特別支援学級の設置校につきましては交流が行われているということがこの前の調査ではっきりしました。","id":"exchange-066"},{"speaker":"せお委員","kind":"質問・要望","question":"神奈川県の大和市にお話を伺いましたが、もちろん時間割が学級によって違うわけなのですが、それを調整するのにすごく苦労するのだけれども、授業によって行き来するのが当たり前だと思っているとおっしゃっていました。頻繁な授業を含めた交流を前提として、そちらも考えていただいて、支援学級のほうも新設していただきたいと要望します。最後に、就学相談です。お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"すまいるスクールについては、ほとんどの学校はすぐ近くで職員が立ち寄れる形になっていると認識しておりますので、今後とも連携して、特に特別に配慮を要するお子さんについては連携してまいりたいと思います。","id":"exchange-067"},{"speaker":"せお委員","kind":"質問・要望","question":"いつか歩けるようになるお子さんに対して成長の機会を奪うようなことをしているので、改めてほしいと。就学相談では、情報をまず共有して、保護者の意向などをしっかり聞いてほしいとお伝えしました。時間がないので、要望だけ。品川区でも起こり得ることですので、そのようなお子さんが入学される際には、成長の機会を奪うようなことがないよう、対応をお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"西村委員","kind":"質問","question":"３７５ページ、学校ＩＣＴ活用経費、３８３ページ、脊柱側わん検診から、子どもの姿勢しつけ教育について、項目はありませんが、学校配布物について、順不同で伺ってまいります。脊柱側わん検診についてですが、モアレ撮影の検査によって、現在、どれぐらい検出されているのか教えてください。先日、量りましたら、小学２年生のランドセルは五、六ｋｇございました。現在の取組と考えをお聞かせください。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"こちら、５年生、それから７年生につきまして、定期検診を実施しています。結果の現状ですけれども、一般的には、大体２％の異常率が出るですけれども、品川区におきましては、現在、０.３から０.４％ぐらいの出現率となっています。大きな行事を中心に全体的に指導ということはありますが、学校によっては、養護教諭から姿勢の指導をしている事例もあります。今後とも、大事なことだと思いますので、推進してまいりたいと考えています。","id":"exchange-069"},{"speaker":"西村委員","kind":"質問・要望","question":"姿勢の授業、すごくいいと思います。ぜひとも広げていただければと思います。子どもたちが自分で気づける機会を提供していただきたいと考えています。学校給食は、大体年間１９０回程度実施されていると思います。この給食の時間を活用しまして、学校の食育を通した箸の指導を行えないでしょうか。もしくは行っていただいている取組がございましたらお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"箸の指導は市民科に位置づいてございまして、指導内容に入ってあります。もちろん箸の指導を普通の授業の時間だけではなく、箸が出たときの給食時、そのときにタイミングを計って、その都度指導して、定着に努めております。","id":"exchange-070"},{"speaker":"西村委員","kind":"質問","question":"なかなか日々のことでもありまして、言い続ける、伝え続けるということ、私も子育てを通しまして、箸の教え方、鉛筆もですが、難しいのは分かっております。家庭に関して関与することもなかなか難しいと思うのですが、近年、家庭教育力も低下していると感じております。家庭でも、なかなか教えていない。現在の取組とお考えをお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"なかなか時間が限られていますので、丁寧にならない場合もありますけれども、お子さんの様子を特に気にされている方については、そのような丁寧な対応で担任もお答えをしています。","id":"exchange-071"},{"speaker":"西村委員","kind":"質問","question":"後で申し上げようと思っていたのですが、連絡帳をタブレットでやり取りをしている学校もあると伺っておりまして、今、ノートが多いかもしれないのですが、それだと、働きながらとか、親御さんも送りやすいのかと思いますので、ぜひとも取組をお願いしたいと思います。次に、民間スクールなどの配布物について伺ってまいりたいと思います。子どもが日々様々な案内を学校から持って帰ってきます。","respondent":"有馬庶務課長","answer":"学校からのそういった民間の案内のチラシの件ですけれども、大きく２つのルートがあるのではないかと考えております。","id":"exchange-072"},{"speaker":"西村委員","kind":"質問・要望","question":"後援の際はしっかりと確認いただいているというのは分かるのですが、保護者にとって、学校からの配布物、大変信頼していると考えています。どのような母体かなどを調べることなく、配布資料だけを見て申込みをする場合もあるかと思います。こちらは要望とします。次に、タブレットの導入状況について伺ってまいります。改めて今の区内状況と見解をお聞かせください。","respondent":"工藤指導課長","answer":"アイデアが浮かばない場合には、活用事例をまねることで取り組めるように、ＩＣＴ推進教員の研修、また、その他のところ、ＩＣＴ通信などを活用しながら、好事例については随時共有を図るようにしておりますので、タブレットを活用しながら教育活動の質を高めていくよう。","id":"exchange-073"},{"speaker":"西村委員","kind":"質問","question":"オンライン配信の進捗について伺いたいのですが、コロナ禍におきまして、コロナ不安や感染、濃厚接触者などをあわせると、１クラス１名は休んでいる時期もあったと学校現場より伺っております。第６波を見越しまして、現在どれくらいオンライン配信が区内で進んでいるのか、また、コロナ禍において実際にオンライン配信を実施した学校がどれくらいあるのか教えてください。","respondent":"矢部教育総合支援センター長","answer":"ただし、新しいものですので、２学期からはということで、１学期、全ての学校が練習をして、例えば土曜日の１時間だけ学校に子どもたちを登校させて、その後、これから配信するよと言って、練習して進めておりますので、大丈夫だと思います。","id":"exchange-074"},{"speaker":"西村委員","kind":"質問","question":"今後、有事の際ですとか、不登校のお子さんにも大変可能性の広がる活用だと思います。オンライン配信を望む家庭と望まない家庭もあると担当課より伺っておりまして、この辺りも運用、難しい部分だと思うのですが、よろしくお願いをしたいと思います。マイクロソフトのＦｏｒｍｓを利用した大変分かりやすいものですが、１年通して実施していただいた所感を伺います。","respondent":"勝亦学務課長","answer":"こちらにつきましては、今、全校で取り組んでおりまして、１１月には全ての学校で、いわゆるオンラインでの欠席連絡ができるようになる状況です。","id":"exchange-075"},{"speaker":"西村委員","kind":"質問","question":"１１月で全校ということですが、今導入されている学校の先生方から、大変助かると。本当に感謝というか、そういったお声をいただいております。なぜかとお伺いしますと、わざわざ職員室に戻らないで、お子さんの様子ですとか遅刻の理由が分かるようになったということで、ファーストアクションが便利になり、効率的になったのかと考えています。一言お願いをいたします。","respondent":"勝亦学務課長","answer":"丁寧な対応が必要な部分につきましては、直接のご連絡を必ず保護者の方に取って、お子さんの様子を伺う等、単純にオンラインで機械的に進めるということではなく、お子様の状況ですとかご家庭の状況にも目を向けていくという形で対応を取ってあります。","id":"exchange-076"},{"speaker":"こんの委員","kind":"質問・要望","question":"順不同でお聞きいたします。現在、こうした児童・生徒の日々の健康観察をしているということをお聞きしているわけですが、まず、どのような方式で、どのような内容の健康観察を実施しているのか、現状を教えていただきたいのと、また、現在行われているこの観察の方式について、保護者の方から何かお声などがありましたら、参考までにお聞かせください。","respondent":"勝亦学務課長","answer":"こちら、紙ベースで作ってございまして、学校名、クラス、お名前、その日の体温、あとは、咳とか喉の痛みがないか、そういったことをご報告いただく紙になってあります。こちらの方式につきまして、具体的には、教育委員会のほうにはお声等は届いていない状況です。","id":"exchange-077"},{"speaker":"こんの委員","kind":"確認","question":"それが担任の先生にとっては一番確実な把握だとは思うのですが、最初のご家庭での把握については、保護者の方から情報をもらって、それを見て先生は観察をするわけですが、その情報をいただく手段としては、こうしたアプリみたいなデジタルを活用するという考え方も、これはあってもいいのではないかと思うところですけれども、こうした自治体も出ている中で、デジタルを使うという情報のやり取り。","respondent":"勝亦学務課長","answer":"そういったものは、コロナに限らず、体温ですとかお子様の体調の情報を負担なく効率的に集めて、状況を確認していくというのは非常に効果的なことだと考えております。そういった意味では、様々な機器、方法を今後研究して、効率化等を考えていきたいと思います。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"今おっしゃってくださった、あらゆる媒体で、どういった形が効率よく情報をもらい、先生たちが学校生活の中でお子さんをきちんと把握できる情報をもらえるかというところは、ぜひ研究をしてみていただきたいと思います。次の質問に参ります。次は、いじめ対策委員会に関連しまして、いじめや不登校、あるいは学校に行きづらい、こうした悩みを抱えているお子さんの相談体制についてお聞きしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"次のチャイルドラインとの連携ですが、こちらについては、市民科の教科書に紹介されている団体ですことと、ほとんどの相談窓口は電話が主になっておりますが、チャイルドラインはチャットができます。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問","question":"現状は分かりました。低い傾向にあると。文科省の実態調査で分かったと。そこで、まもるっちの検討状況というのは今お答えはいただけないのは承知をしているのですけれども、いわゆる悩みを持つ子どもたちが相談窓口にアクセスしやすい環境整備、こうしたことについてまもるっちを活用するということに対しては、教育委員会としてはどのようにお考えなのか、ご所見を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"まもるっちの大きな機能は、やはりブザーの機能で危険を周りに知らせるということが第一義かと認識しております。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひこうしたいろいろな媒体を使って、子どもたちがアクセスしやすい環境をつくっていただきたい。要望で、次の質問に移ります。公共交通機関を利用する場合、中学生などは大人料金になりますので、そうした回数がかさむことで負担が結構あったのではないかと想像するのですが、どんな現状なのか。部活によっても違うと思いますけれども、その辺、分かれば教えてください。","respondent":"矢部教育総合支援センター長、勝亦学務課長","answer":"その前の自由に部活の遠征等ができたときにつきましては、やはり個人負担で負うことになっていたと認識しております。関東大会以上の大会に出場する場合につきましては、支援を一部行っているようです。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"そこで、品川区はどのような計画を提出したのか、伺います。ほかの自治体では、現状でも１０人以上を担当する教員がいるそうですが、これは年度途中で新しく通う子どもがいることが大きな要因ですけれども、品川区では、既に１０人以上を担当している教員はいるのか、人数を伺います。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"委員ご指摘の配置計画につきましては、東京都教育委員会から求めがあったとおり、これまで１０人に１人という割合でございましたけれども、１２人に１人に勘案して、どういった配置になるかということが。ご質問のもう一つ、１０人以上を１人の担任が持っている数です。現状は５校５名です。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"１２人に１人の計画で提出したということですけれども、そうすると、何人教員が減ることになるのでしょうか。伺いたいと思います。それで、子ども１人当たりの指導時数というのは減るのかどうか、ここのところも伺いたいと思います。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"実際に１２人に１人で何人が減るのかというところはありますけれども、いわゆる児童、在籍する学級の子どもの数によってももちろん変わる。必要があって特別支援教室に適切だということで通っていますので、その時間を減らすということは本末転倒になってしまいますので、お子さん中心に、いる教員が指導するということになります。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"減る可能性で提出をしているということですけれども、東京都は、小・中あわせてですけれども、３４０人減らすという計画を求めているのです。区内の教員の方にもお話を伺いました。９人担当しているそうなのですが、既に手いっぱいだと。その後、拠点校に戻って、午後７時、８時になってしまうと。教員を減らすのではなくて、増やすことこそ必要だと思いますが、いかがでしょうか。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"そのため、品川区といたしましても、都教委に対しましては、専門的な、例えば特別支援教論の免許を持っている方であるとか、そういった経験のある方を教員人事の際にはぜひ配置をいただきたいということで要望はしていますが。昨年度も、拠点校というのがありまして、そこから巡回していくのですけれども、３校行っていたところを全部２校にしましたので、比較的連携が取りやすく、巡回の教員も回りやすくなっていると我々は解釈しております。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"しっかりやっているというようなご答弁だったと思うのですけれども、やはり教員を減らせば、見る子どもの数が増えて、大変になってくるということになりますので、教員を増やすことをぜひ区としても考えていただき、都に求めていただきたいと思います。支援教室で学ぶことは、子どもたちの権利です。そのうち３年以上指導を受けている子どもは何人いるのか、伺います。","respondent":"矢部教育総合支援センター長","answer":"現状、特別支援教室の利用者数は、小学校と義務教育学校前期課程のお子さんが６３０名です。中学校と義務教育学校後期課程のお子さんが１１７名でございまして、計７４７名です。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"通っている方の半分が３年以上通っているということで、今回、制限を設けるわけです。やはり教員の方たちも、６年通ってやっと落ち着いた子もいるということですとか、１年だけでは何もできなくなってしまうという声も寄せられています。期間を定めるべきではないと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"必要があれば、次の年度もまたげるように相談ができるシステムと認識しておりますので、今後も、来年からですけれども、指導の様子、また、お子さんの様子を見ながら、保護者とも相談して進めてまいりたいと考えています。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"必要であれば延ばせるということですが、そうすると、今までどおり６年通うことも可能なのか、伺います。","respondent":"矢部教育総合支援センター長","answer":"原則１年と言われていますので、そちらは教員も意識しなくてはいけないと考えております。先については、我々もこれからの取組ですので、注視してまいりたいと考えています。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこういったいろいろな削減、時間もそうですし、教員を削減していくということは、教育が狭まっていくということになりますので、教員も増やして、時数も増やしていくということでやっていっていただきたいと思います。図書館のほうは時間がなくなってしまったので、充実を求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"西本委員","kind":"確認","question":"３７９ページの通学安全確認業務委託、これは恐らくは通学のときの、いわゆる緑のおばさんというのですか、していただいております。結構ご年配の方がされていて、そこのところも、温かく見守るというのとまた違う心配事があるものですから、それの研修はどうなっているのでしょうかということ。区がやる必要があるのですかということ。その家庭環境に対してどう指導していくのですかという質問だったのです。","respondent":"有馬庶務課長、勝亦学務課長、工藤指導課長","answer":"その旗が大分老朽化しているということであれば、調べて、大至急新しいものに取り替えて、業務につく方も、それを見た子どもたちも元気に通えるように。現時点では、ある程度終了も視野に入れて、今後判断するということも考えてあります。ただ、オンライン授業が全てを可能にするわけではございませんので、我々は配りました機器とソフトを活用しながら、リアルな学校教育をもちろん進めつつ。","id":"exchange-089"},{"speaker":"西本委員","kind":"確認","question":"旗振りの旗、ぜひよろしくお願いいたします。それに一役買ってしまうような状況は、やはり教育委員会のほうもしていただきたくはないので、速やかに国のやるべきことは国でやってもらう。そういう意味での教育格差が出てくるのではないのですかということを言っているので、そのお考えをお聞きします。それが一つの出欠確認でも分かるのです。なので、そこの使い方についてもう一度お答えください。","respondent":"工藤指導課長","answer":"そういった意味では、これからも様々な活用を図ってまいりたいと考えています。","id":"exchange-090"},{"speaker":"吉田委員","kind":"質問","question":"今の西本委員の学校給食の放射能測定に関連して、生活者ネットワークとして関連質問いたします。それについて２点伺います。教育委員会としても、終了を視野に入れたとして、同じように考えておられるのか、伺います。一定期間、給食を保存していると伺っております。それについて有償でも結構ですので、それを市民団体に検査のために提供していただくということは可能でしょうか。それについて伺います。","respondent":"勝亦学務課長","answer":"保存の給食食材の提供です。こちらは食中毒の検査に使ってありますので、有償無償問わず、ご提供というのは考えてございません。","id":"exchange-091"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。では、最初のほうの、社会情勢などが必要と思われる状況になったらとおっしゃいましたけれども、それは例えばどのような状況のことを示しておられるのか伺います。放射能測定ですけれども、既に検査のためということですが、それは放射能物質の測定には何も影響はないと思います。それを提供していただきたいと思うのですが、ぜひこれは検討していただきたいのですが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"例えば、そういった放射性物質が出るような事象がまた発生したようなときは、必要に応じて実施する必要があるのかと考えています。食材の提供ですけれども、基本的にご提供することを想定して準備しているものでございませんので、提供については差し控えたいと考えております。","id":"exchange-092"},{"speaker":"吉田委員","kind":"質問","question":"社会情勢なのですけれども、生活者ネットワークとしては、例えば、汚染水を海洋で放出してしまうという事態もそれに当たるのではないかと思います。汚染水の海洋放出については、もっと国民的議論が必要だと考えておりますが、それは風評被害を払拭するためにも、きちんと検査をしていくべきだと考えますが、見解を伺います。","respondent":"勝亦学務課長","answer":"ＡＬＰＳ処理水につきましても、基本的には、環境影響のない水ということで認識しています。","id":"exchange-093"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、３７５ページ、学校ＩＣＴ活用経費、３６５ページのルネサンス推進事業費の中から、市民科授業、プログラミング教育についてお伺いします。学校ＩＣＴについてです。全国の義務教育学校では、４月からタブレットを活用した授業がスタートいたしました。そこで、タブレット教育がスタートしてから、第４波、第５波といった緊急事態宣言を、学校はどのような工夫をして乗り越えたのか。","respondent":"矢部教育総合支援センター長、勝亦学務課長","answer":"こちらも１３回改訂しまして、それに基づいて学校のほうも、３密を避けることや咳エチケット、また、手洗いの徹底というところを中心に進めて、感染防止対策に努めてきたものです。ＩＣＴ支援員につきましては、現在、週に１回、各学校に行っている状態でございまして、児童・生徒への機器の操作支援、それから、教員への支援、技術的な支援、そういった部分と、授業へのＩＣＴの活用の助言や提案、また。","id":"exchange-094"},{"speaker":"湯澤委員","kind":"質問","question":"それぞれ学びを止めない努力をしていただいていると思いますが、どうしてもやはり学級閉鎖や学年閉鎖、そうなってしまうケースもあるかと思います。これは以前、ＮＨＫで４月に放送された番組の中で、品川区が、学校によってはできると回答されていたかと思います。現在はいかがでしょうか。基礎疾患等の理由で自主休校をされている生徒はどれぐらいいて、どう対処されているのか。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"ただ、オンライン上、カメラ等を使いますので、例えば、背景に何かが映ってしまうとか、手元の何かが映ってしまう、そういった危険はありますので、そういったことには。教育委員会としましては、９月２２日付でコロナ不安でお休みしているお子さんの数を取りまして、１１０人という数字が出ました。ただ、ここが、様々おっしゃるような、ご自身の疾患もあれば、家族の疾患もある。","id":"exchange-095"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それぞれご回答ありがとうあります。全ての学校でオンライン授業も開始できるということが分かりました。導入のためには、ハード面や予算面といったハードルがあるかと思いますが、これまで教育分野で先進的な取組をしてきた品川区でありますので、ＶＲやＡＲを積極的に活用し、子どもたちが早い段階で楽しみながら新技術による学習ツールに触れることを要望しますが、ご見解をお知らせください。","respondent":"工藤指導課長","answer":"委員ご指摘いただいているバーチャルリアリティを活用した教材などというのが、現状、開発が進んできているというのは認識しています。現在、児童・生徒に配布するタブレットを活用しながら、現状は授業の中で活用を進めているところが中心です。","id":"exchange-096"},{"speaker":"湯澤委員","kind":"意見","question":"市民科の授業についてお尋ねいたします。平成１８年から品川区独自の科目である市民科の公開講座に参加をしてまいりました。この市民科は道徳に代わる授業であると思いますけれども、道徳とどういったところが違うのか、何を目的としているのか、また、転校生などもすぐに対応できるのか。そういったところもあわせてお知らせいただければと思います。","respondent":"矢部教育総合支援センター長","answer":"市民科についてのご質問です。委員ご指摘の平成１８年度から実施している、本区独自の教科です。特別な教科道徳と総合的な学習の時間、また、特別活動を統合した教科です。","id":"exchange-097"},{"speaker":"湯澤委員","kind":"提案","question":"市民科では、ＳＤＧｓについても、８年生、９年生の教科書で取り上げられているかと思います。そこで、市民科においてＳＤＧｓの実践として具体的にどういったことを行っているのか。あわせて、一般質問でも提案をさせていただきましたが、必修科目になったプログラミング授業、そちらのほうでもＳＤＧｓを取り入れた学習を行っていただきたいと考えますが、ご見解をお知らせください。","respondent":"矢部教育総合支援センター長","answer":"ＭＥＳＨという機材を使っていますが、プログラミング自体の勉強というよりは、繰り返し試行錯誤して論理的思考を育てるというのを目標に進めております。","id":"exchange-098"},{"speaker":"湯澤委員","kind":"質問・要望","question":"本当に幼い頃から実践することで、当たり前に行うこと、そういったことが身につくと思いますので、ＳＤＧｓ教育は様々な学習の中に取り入れていただきながらやっていただきたいというふうに要望いたします。ご見解をお知らせください。","respondent":"工藤指導課長","answer":"様々タブレットを使った活用というのはこれからも進んでいくと思いますので、また授業風景の公開なども、各校、ホームページなどを活用して進めていければと考えているところです。","id":"exchange-099"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３６３ページの生徒指導対策等経費、３７９ページの通学安全確認業務等委託について伺います。生徒指導対策等経費については、ヤングケアラーについて２定で質問させていただきましたが、国の動きも出てきて、また大分いろいろな支援策が出てくると思うのですが、区では既にいろいろこういったケースも対応してきたと伺っております。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"ヤングケアラーについてのご質問です。やはりお子さんを見ただけでヤングケアラーかどうかというのは難しいものでございまして、特に家庭内のことで、学校では元気に過ごしていたりしますと、本当に問題としては表に出にくい現状です。単価につきましては、令和２年度が１,１００円、令和３年度は５０円アップいたしまして、１,１５０円というところになってあります。","id":"exchange-100"},{"speaker":"たけうち委員","kind":"質問","question":"いいと思うのです。もたれかかって、本当に大丈夫かとこちらも思うぐらいの方で、本当に心配しているのですけれども、水分もしっかり取っていただき、夏場などはうまく休憩体制とかを取って少し冷やさないと、逆に危ないのではないかと思ってしまうのですけれども、その辺のところはどのような、指導をされたりとか、また、うまく回せていけないのかと思うのですけれども、どうでしょうか。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"今年度もできる範囲でやっていくというふうに認識しておりますが、まだ緊急事態宣言が長かったものですから、今のところは昨年どおりと認識しております。２点目、スクールカウンセラーがヤングケアラーの事案を知り得たときです。現在、熱中症対策として、例えば３０分、４０分やったら１０分ここで休みましょうとか、具体的な指示を出しているものではありませんが、当然、熱中症対策は必要なことだと思いますので、学校とも状況を確認しながら。","id":"exchange-101"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ヤングケアラー、分かりました。それから、通学路の安全のほう、ぜひお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、３５７ページ、委員会運営費から、教育委員会のあり方についてと、３６０ページ、教育指導費に関連して、性教育について伺いたいと思います。教育委員会のほうですけれども、以前にも共産党から教育委員会の傍聴の改善を求めて質問をしてきました。今回もそこについて伺いたいと思いますけれども、委員会の音声について、区は、発言者にははっきりと大きな声で話してもらうようにすると。伺います。","respondent":"有馬庶務課長","answer":"それで、その程度の部屋なので、マイクなしでもいけるのではないかという判断をしていたのですけれども、基本的には、そういう声もあったということで、一度ワイヤレスマイク等で試してみようということで試しておりますが、委員と理事者の関係で狭い部屋で。","id":"exchange-103"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"デジタル化が進んでいる今ですので、ぜひ早急な改善をお願いしたいですし、やはり教育委員会、住民自治の場です。住民参加が当然の場です。資料の配布、そして、持ち帰り、可能にしていただきたいと改めて強く求めたいと思います。この包括的性教育に取り組んでいる都内の私立高校の先生の話を伺いました。限界があると思うのですけれども、改善が必要だと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"性教育のご質問です。今、私立の事例を伺いました。学習指導要領ですが、公立学校ですので、そこを変えるというのは、我々としてはこれは国がやることだと考えていますので、できる限り国の方針に基づいて進めてまいりたいと思います。","id":"exchange-104"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうした包括的性教育は、本当に将来にわたって豊かで楽しい性認識をつくり出し、人とのコミュニケーション、そして、先ほどからも議論になっています性暴力の抑止、こういったものにも大きく力を発揮するものだと思いますので、抜本的な改善をぜひ国や都にも求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"３６３ページ、中学校進路指導費、３６９ページ、特別支援教育費、３７５ページ、学校ＩＣＴ活用経費、それから３８３ページ、学校施設建設費をお尋ねします。典型的なというか、１つ２つ例を挙げていただき、その成果をお尋ねいたします。このＣのことについては、文教委員会でも質疑があったと伺っています。これによって、現行の９年生への影響、そして、９年生へはどのような指導をされるのでしょうか。","respondent":"勝亦学務課長、矢部教育総合支援センター長、有馬庶務課長、工藤指導課長","answer":"全ての学校におきまして、朝礼等については、少なくとも１回はオンラインで実施をしています。我々としましては、特に特別支援教室については、全校に宛てて説明会をしたところですが、これからも巡回指導員や特別支援教室の教員については。令和２年度に敷地測量を行った鈴ヶ森小学校の件ですが、今年度は、委員おっしゃるとおり、予算計上はありませんが。高等学校入学者選抜における変更点というところでお尋ねですが、委員ご指摘のように、令和４年２月実施の選考から。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。その点が１つ。それから、施設のほうは、今お話がありました。老朽化も進んでいますので、いわゆる改築に乗せていって、検討をぜひ、地域の方々も求めており、期待も高いのでよろしくお願いします。これはお願いです。ですから、特に２学期は私立高校への進路指導とかを決めていく時期でありますので、その点について男子への影響をお尋ねします。","respondent":"工藤指導課長","answer":"高等学校入試の制度の変更によって、委員ご指摘のように、男子の事例として、これまで行っていた緩和実施校が４２校ございましたので、それらの結果からすると、男子が入りにくくなるというのは恐らく生じるだろうと思われます。","id":"exchange-107"},{"speaker":"渡辺委員","kind":"質問","question":"３７５ページ、学校ＩＣＴ活用経費で、本日も様々出ていますが、ネットリテラシーの点から伺おうと思います。そして、何しろこの分野は、本当に超高速的な技術の進化、これ、来年の今頃はまた違う展開になっているかもしれないということで、本当に便利な分、すごく苦慮される部分もあるという前提で伺っていきます。直近のスマホ保持率というのですか。タブレットはタブレットで全校配布の前提で考えます。","respondent":"矢部教育総合支援センター長","answer":"携帯の所持率については、学年によっても違うと考えています。調査をしていませんが、ただ、４年生ぐらいから塾に行くお子さんが多いということで、保持率が高くなるというのは認知しております。中学生につきましても、かなりの割合で所有しているということは認識しております。","id":"exchange-108"},{"speaker":"渡辺委員","kind":"質問","question":"これは正解がある話ではないような気がしながら伺うのですが、切りがないと言ったら切りがないぐらい日々進化することと、ジャンルも大変幅広くて、教える側、あるいは学ぶにしても、どれからというところが、ここは曖昧で仕方ないと思っています。そんなことから、スマホやＳＮＳの安全教室のような趣旨のもの、この必要性を伺いたいと思います。そんなことについての見解をまずお知らせください。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"情報モラルにつきまして、今の事例もありましたとおり、様々な場所でそれぞれの機関でいろいろな取組が行われているのは認識しています。ただ、これも２時間が正しいかどうかというのはその都度議論が必要だというところ、これはもちろん生徒だけではなくて、教員がこういった指導に関わりながら行うところだと認識しています。","id":"exchange-109"},{"speaker":"渡辺委員","kind":"質問・要望","question":"家庭も児童・生徒も教職員もそれぞれが頑張ります。でも、どうしても手に負えない部分があると思っています。それは、先ほど来質問にありましたインターネット上の誹謗中傷、これは社会課題となっています。それは、町田市の自殺事件もそうです。それは、やはりこういった誹謗中傷の書き込みは、一家庭ではどうしても困っても、仮に表現ができても、把握できるのはほんの一部です。ご答弁をお願いします。","respondent":"矢部教育総合支援センター長","answer":"そういった地域の方たちのお声もしっかり取り入れていきたいと思いますし、また、今お話の弁護士の方につきましては、様々なジャンルで、今、士業ということで学校でご指導いただいておりますので、様々なそういった有効な人材について。","id":"exchange-110"},{"speaker":"大倉委員","kind":"質問・要望","question":"前のほかの委員の方の質問のご答弁で、１１校で１２名ということで分かりましたので、そうすると、１校に２名配置されているところがあるということだと思うので、その内訳というか、費用の面でどうなっているのでしょうかということと、あとは、１５校、各学校に１名ずつ配置を目指しているというお話でしたが、１名ずつの配置にならない、１１校１２名にとどまっている理由がどのようなものがあるのか。","respondent":"矢部教育総合支援センター長","answer":"お支払いはできても、なかなかいじめや、子どもたちとの関係性、そういったものを大事に対応する指導員にやっていただきたいというのが学校の願いですので、そういう方を探すまでには少し時間がかかるということが大きな理由です。","id":"exchange-111"},{"speaker":"大倉委員","kind":"質問・要望","question":"活用についてぜひ推進していっていただきたいということで、ご質問しています。天気に左右されないというメリットもあるのかと思いますので、その辺はどうでしょうかということで、ご答弁いただければと思います。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"ただ、いい人材をぜひ部活動の維持のために確保したいという思いは私もありますので、今後も柔軟に検討していきたいと考えています。改築中のプールの利用ですけれども、最近では、後地小学校が第四日野小学校に行ったり、今度、第四日野小学校がやるのに、できた後地小学校へ行くとか、鮫浜小学校と浜川小学校の関係とか。","id":"exchange-112"},{"speaker":"須貝委員","kind":"質問","question":"私、まず、３６０ページ、教育指導費全般についてお聞きしたいと思います。デジタル採点システムについて、分かれば、見解をお聞かせください。システムでは、記号で答えを選ぶ問題について、生徒の解答用紙をスキャナーで読み込ませ、自動で採点することができます。要は、教師の負担軽減につなげるというシステムができたようですが、もし知っていれば、教えてください。","respondent":"工藤指導課長","answer":"委員ご指摘のデジタル採点システムについて、ご紹介の県が所管する県立高校に導入するというのは、報道によって私も認識しています。導入の経緯としましては、ご指摘いただいたように、働き方改革によって教員の負担軽減をするということが目的と聞いているところです。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問","question":"同じ人間ですから、性別関係なく学力レベルで合否を決めるべきで、男女で関係なく実力で平等に選ばれるべきだと私は思います。全国にはありません。これ、子どもたちのためですが、そして、もし平等であるべきだと思うならば、東京都教育委員会に変更の要請を今までしていたのか、教えてください。そして、このことを中学３年の受験生や保護者に毎年きちんと伝えていたのかどうかも教えてください。","respondent":"工藤指導課長","answer":"高等学校入学者選抜の男女別の定員についてのお尋ねです。本制度につきまして、委員ご指摘のように、男女別の定員制が令和４年２月実施から緩和されるところです。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問・要望","question":"私もテレビ報道を見て気がついたのですが、まさかこのような仕組みが長い間、昭和２５年から今日まで続いていたということは本当にショックで、男女別で、ましてや同じテストを受けて、同じ内申点、平等につけられて、女子だけその中で入りにくいというシステムは、やはりこれは教育の根幹に関わることだと思いますので、もし何かあったら、今後、きちんと抗議していただきたいと思います。","respondent":"工藤指導課長","answer":"今、教員の点についてのご指摘の前に、先ほどの高等学校の入試のところでいえば、入学者選抜検討委員会という会が、東京都と、あとは中学校長、また、それぞれ指導室課長も出るような会がありますので、こういった要望等については、そういったところで改善要求はしています。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際、教育委員会でこれだけの教育改革を進めて、予算も使って、子どもたちのために進めている。まして区長は、品川区固有の教員の採用を認めているのです。こんな区はほかにあるのか。品川区で引き取ってくれと。我々は今改革しているのだから、いい教員が欲しいですという意気込みで私はやっていただきたいと思います。そこはしっかりやってほしいのですが、もう一回ご見解をお聞かせください。","respondent":"工藤指導課長","answer":"そういう意味では、初任、また、異動２年目であって、品川区で品川教育に携わった教員が他地区へ異動した後、義務教育学校公募などで戻ってくるということも想定しながら、私どもは品川区の教育の充実に励んでいるところです。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問","question":"例えば、品川区の職員も、やはりいい人を選びます。各企業も、いい人を選ぶでしょう。その中で座っているのですか。そうではないでしょう。あなた方は、教育指導者としては、申し訳ないけれども、少し足りないです。そうしたら、来ちゃいけないでしょう。でも、現場では、５段階ぐらいに分けて習熟度別教育指導をしないと、授業についていけない子どもたちも出てきております。お聞かせください。","respondent":"工藤指導課長","answer":"教員でいえば、全員一律の宿題ではなく、その子にあった宿題を出す。つまり、その子が課題としていることを定着させる。そういった意味では、より基礎・基本の定着を図れるように、今回配布しているタブレットも有効に活用を始めているところです。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、前、ＡＩ先生という話をしました。教育ユーチューバー、葉一さんの授業動画、これを活用できないのでしょうか。１人でも取り残さない教育、それがやはり今は大事な使命になっているのではないかと思うのですが、先ほど見ていた、そちらのタブレットのあれですが、そこには説明も何もないではないですか。こういうことも活用を検討していただきたい。ご見解をお聞かせください。","respondent":"工藤指導課長","answer":"ご指摘のユーチューバーの動画等があるというのは認識していますが、その他様々有料のものも含めて、そういったコンテンツがあるということも認識しています。","id":"exchange-118"},{"speaker":"中塚委員","kind":"質問","question":"３６３ページの生徒指導対策費に関連して、中学校の校則について、髪型と下着チェックを伺いたいと思います。ならば、どういうときになぜ髪を結ぶのか説明をすればよいのであって、校則で決める必要はありません。守らない人がいるから校則で決めるというのは、連帯責任ということでしょうか。こんな連帯責任の校則は理不尽だと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"それで、各学校によって校則が違うのは、その場その場の地域や時代の背景や保護者やお子さんたちの様子によって、これまでの経緯でできてきたものだということは繰り返し述べてまいりましたので、そのような背景から、Ａ校のこの規則がいけないとかいいとかということは。","id":"exchange-119"},{"speaker":"中塚委員","kind":"質問","question":"繰り返し指導していると。しかし、中学生に話を聞くと、例えば、登下校時も含めて常に結ぶように指導される。休み時間も常に結ぶように指導されると伺いました。教育次長は様々な場面を説明しましたが、つまり、それ以外は髪を下ろしたままでもよいということなのか、駄目ということなのか。つまり、常に結ぶという指導は、私は合理的ではないと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"常に結ばなくてよいのかもしれません。ただ、毎回繰り返し、その都度その都度指摘したり、そんなの分かっているというやり取りであれば、最初から決まっているほうが子どもたちにとっては負担なく授業に進めるのかと考えています。","id":"exchange-120"},{"speaker":"中塚委員","kind":"質問・要望","question":"最初から理不尽なことが決まっていることが理不尽だと私は思います。肩より長い髪を下ろしたまま禁止について、この理不尽さについて美容師も強く実感をしております。美容師の話では、肩より長い髪を下ろしたまま、ワンレンが今再流行しているとのことです。なぜ常に結ぶことを求めるのか。場面場面で状況を変えることができることを認めてほしいし、そうあってほしいと思いますが、改めていかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ここ一番というところは、行事の練習もあったり、行事もあったりということで、その場その場のＴＰＯはかなり頻繁に変わる場合もあります。授業も同じです。その中で、このような望ましい服装ですとか髪型について、学校が決めていると認識しています。","id":"exchange-121"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはりこういうのは、よく学校とも話合いを通じて、禁止の髪型の見直しを進めていただきたいと要望したいと思います。本会議で、一つ一つ中身を確認しているものではない、人権侵害には当たらないという答弁がありました。中学生の親の世代でもある４０代の女性に、中学生の下着をワイシャツの上から目視で校則にあっているかどうかを確認していることを聞くと、やめてほしい、嫌だと話しておりました。","respondent":"矢部教育総合支援センター長","answer":"様々事例はあるかと思いますが、下着は見せるものではないと私もそう思います。ただ、目視とかチェックという言葉が、少し私どもと認識が違うのかと感じています。","id":"exchange-122"},{"speaker":"中塚委員","kind":"質問・要望","question":"私がチェックと言ったのは、見て確認して、校則と異なれば指導しているということですから、これはチェックそのものです。見ているもの、目立つことがあれば指導するということですから、それ自身がチェックだと思います。品川区教育委員会も、下着の色指定や指導はやめて、都教委と同じく、下着の色の指定やそれに関する指導は行わないと各中学校に通知すべきだと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"校則は、委員もご存じのとおり、学校で定めるものですので、現時点では、学校に、ならぬということは伝えるつもりはございません。ただ、これまでどおり、校則の見直しのことは働きかけていきますし、その方法についても生活指導主任会等で周知してまいりたいと考えています。","id":"exchange-123"},{"speaker":"中塚委員","kind":"意見","question":"学校に通知するかしないかは一旦置いておいて、東京都教育委員会は、下着の色の指定や、それに関する指導は行わないと通知を出したわけです。この考えは区教委と同じなのか。先ほどからの説明だと、違うということになりますが、何がどう違うのか、ご説明ください。","respondent":"矢部教育総合支援センター長","answer":"ただ、この通知自体が既に都立学校宛てで、我々の区立学校宛てに参考送付もされていないものですので、これはあくまで都立校の進めることだということで、表現とか細かい内容について、我々が意見するところではないと考えています。","id":"exchange-124"},{"speaker":"中塚委員","kind":"質問","question":"区教委は意見するところではないというお話ですが、今、その通知が手元にあるわけですよね。その中には、下着の色の指定やそれに関する指導は行わないと都教委は通知した。つまり、そう考えているということです。教育委員会は、同じなのか、違うのか、改めて伺います。","respondent":"矢部教育総合支援センター長","answer":"ここは例示ですし、主に高校生が多い都立ですので、小・中学生を所管している我々としては、全く同じ意見はございません。","id":"exchange-125"},{"speaker":"中塚委員","kind":"質問","question":"高校生が多いと。中学生は違うと。下着のチェックにおいて、高校生と中学生で何が違うのですか。","respondent":"矢部教育総合支援センター長","answer":"発達段階は大きなことだと考えています。義務教育の中で９年生、本区でいえば９年生でどういう姿を見せたいかというのは、一つそこが区切りだと考えておりますので、特段今回については参考送付もされてございませんので、私たちは考えに変更はございません。","id":"exchange-126"},{"speaker":"中塚委員","kind":"質問・要望","question":"参考送付されていないから考えを表明しないとおっしゃいますけれども、事前に説明もして、通知も手元にあって、私が質問をしているわけですから、区教委は自ら考えを示すべきだと思います。下着のチェックについて、中学生と高校生でどんな発達段階が違うのですか。そして、それが指導でどう変わってくるのですか。しっかり説明いただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"発達段階で違うというのは、中学生の７年と、例えば、高校生はまた少し違うだろうというイメージもありますが、チェックという認識がやはり私たちと違っていまして、校則というより、目立った髪型とか服装になれば声をかけていくという認識の中で指導しています。","id":"exchange-127"},{"speaker":"中塚委員","kind":"質問・要望","question":"チェックという言葉を使わずに、見て確認して指導しているというわけですから、そうした下着の指定があるから確認が求められるのです。ですから、校則で下着の指定をやめれば、確認そのものがなくなってくると私は思いますが、いかがでしょうか。ぜひ、学校は学び、成長する場です。生徒の人権も保障される場です。理不尽な校則の見直しを強く進めていただきたいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"私の手元にある学校だよりには、校則を見直しますと、はっきり学校だよりの前面に書いてあるところがあります。こういう機会を一つ、校則ですけれども、別なことも含めて、いろいろなことで協議したり意見を聞いてつくり上げるということはとても大事だと感じています。","id":"exchange-128"},{"speaker":"鈴木（博）委員","kind":"質問","question":"がん教育についてお尋ねいたします。がん教育については、決算特別委員会、予算特別委員会、一般質問でも継続的に取り上げてまいりました。正しい知識を身につけ、適切に対処できる実践力を身につけるということは、ＨＰＶワクチンの正しい勉強、学習課題そのものだと理解いたしますが、教育委員会の現在の見解をお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"がん教育に関しましては、望ましい生活習慣を身につけることや、喫煙、飲酒、薬物乱用などの行為が健康を損なう原因であるということなどは扱いますが、ＨＰＶワクチン接種については、指導事項としては位置づいておりません。","id":"exchange-129"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"２０２１年１０月１日に開催された厚生科学審議会予防接種・ワクチン分科会副反応検討部会と薬事・食品衛生審議会薬事分科会医薬品等安全対策部会安全対策調査会の合同会議の席上で、国立感染症研究所感染症疫学センター予防接種総括研究官の多屋馨子委員は、リーフレットの充実のほか、学校における養護教諭などにより子どもに教える必要があるとし、学校との連携を強く求めたと報道されています。","respondent":"矢部教育総合支援センター長","answer":"がん教育につきましては、６年生の保健で病気の予防、９年生の保健でも、健康な生活と疾病の予防というタイトルで、単元で学習をしております。中学校、義務教育学校の後期課程におきましては、令和２年度より全ての中学校でがんの専門医による指導を実施しております。","id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２０２０年１２月に、ＨＰＶワクチンが男性にも適用が拡大されました。ユニバーサルワクチネーションについて、男女にＨＰＶワクチンを接種する国も増えてきています。ぜひ教育委員会からも、男児への、男児の保護者へのＨＰＶワクチンの情報提供をお願いしたいと思いますが、教育委員会のお考えはいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"厚生労働省が配布しておりますＨＰＶワクチンのパンフレットは、女子用と認識しております。男子のほうは任意の接種であることからも、現在は男子への指導はしておりません。","id":"exchange-131"},{"speaker":"鈴木（博）委員","kind":"質問","question":"子どもの未来と幸せに責任を持つ自らの職種の社会的使命もよくお考えになっていただいて、ぜひご検討いただきますように切にお願いして、次の質問にまいります。自宅待機となった子どもへの学校からの支援は、どのように行われているのでしょうか。小・中学生の新型コロナウイルス検査陽性者およびその家族に対する、在籍クラスの他の生徒、保護者へはどのような働きかけが行われたのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"濃厚接触等により自宅待機となった児童・生徒に対しては、学習保障の観点から、１人１台端末も活用しながら、紙ベースの資料も含めて課題を与えたり、授業の様子を配信するなど、各校が工夫して個別に対応しているところです。","id":"exchange-132"},{"speaker":"鈴木（博）委員","kind":"質問","question":"現在、新型コロナワクチンの接種が各階層で積極的に進められており、子どもにおいては１２歳からメッセンジャーＲＮＡワクチンの接種が可能です。家庭内感染を減らすためには、保護者の積極的なワクチン接種が必要と思われますが、保護者への学校からのワクチンの情報提供はどのように行っているのでしょうか。ご説明をお願いいたします。","respondent":"有馬庶務課長、勝亦学務課長","answer":"品川区の場合は、９月１日の段階で約８割ですので、これよりもかなりある程度進んでいるのではないかと考えているところです。家庭内での感染防止のために、児童・生徒の保護者の皆さんには、ワクチン接種に関する客観的で正確な情報を提供していくことが非常に重要であると認識しています。","id":"exchange-133"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１８歳以下の自殺は、学校の長期休業明けの時期に増加する傾向があると言われております。繰り返しの質問になるかもしれませんが、特にコロナ禍の中の自殺対策について、保健予防課ではなく、教育委員会としてはどのようなことに力を入れて取り組まれているのか、ご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"さらにこの９月、品川教育の日には、いじめの防止と自殺対策をテーマに、全教員向けの講演会を行いまして、児童・生徒の対応について理解を深めることができました。","id":"exchange-134"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今回のコロナ禍で明らかになった問題の一つは、メディアの事実に基づかないフェイクニュースの連発と、それにいいように惑わされる大人たちによる風評被害です。新型コロナウイルス感染症から子どもを守る最大の課題の一つは、メディアと大人がまき散らす風評被害から子どもを守ることです。現在の品川区のメディアリテラシー教育の現状について、再度、現段階でのご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"内容は、具体的には、ＳＮＳの使い方、著作権に配慮した表現方法のあり方などを事例に、情報発信者の意図を読み取り、自分の意見を発信できる力を育成しています。","id":"exchange-135"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"国語の学習について最後に伺います。国語の学習は、国語の授業の時間だけではありません。現在の理科とか社会の教科書が、平仮名だとか片仮名が多過ぎるような気がするのですが、ぜひ国語を意識した授業を行うように要望させていただきたいと思うのですが、一言お願いします。","respondent":"矢部教育総合支援センター長","answer":"各教科におきましても国語の指導は大変重要だと考えております。今後とも国語を意識して教科指導が充実するよう、推進してまいります。","id":"exchange-136"},{"speaker":"塚本委員","kind":"質問・要望","question":"初めに、学校体育施設整備費なのですけれども、この中で特にグラウンドの人工芝生化、これが決算書では義務教育学校１校、それで、照明ＬＥＤ化、これが決算書で小学校１校、中学校２校ということになっておりますけれども、まず、このグラウンドの人工芝生化とＬＥＤ化はどういう考えに基づいて進めているのかということ、一通り区内の小・中学校に整備が行き届くというのは。","respondent":"有馬庶務課長","answer":"その学校をＬＥＤ化していこうというものです。それで、こちらのほうは、ある程度、１７ということで限定がされていますので、ＬＥＤ化は数年で全部終わるという見込みになっております。","id":"exchange-137"},{"speaker":"塚本委員","kind":"質問","question":"夜間開放をしていなくても、午後６時ぐらいまでやると、今、この時期になりますとこれぐらいの暗さになってくるので、一定の明るさがないと、なかなか自由にそういったスポーツができないというお声がありますけれども、夜間開放していない学校というのは、どういった理由に基づいて開放していないのかということをお伺いしたいと思います。","respondent":"有馬庶務課長","answer":"その後、平成２年度ですけれども、各中学校区域単位で夜間照明をつけていこうではないかという話がありまして、それで最終的に平成１７年に完成して、要するに、ある程度中学校区に１校ぐらい、ナイターができる設備をつけましょうということで整備をしたものですので。","id":"exchange-138"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうしますと、今、夜間開放というか、照明があまりしっかり明るくついていないところというのは、学校等から要望なり、そういうことが出てくれば、地域も関係してくると思いますけれども、一定程度つけていこうということは、特段の障害はないという認識でよろしいのでしょうか。","respondent":"有馬庶務課長","answer":"それを今後また拡大するということになりましたら、恐らく、まず、夜間に使うニーズがあるのか、それから、近隣との関係がどうしても出てきますので、明るさ、まぶしい、騒音、そういったところでその辺をクリアしていかなければいけないので。","id":"exchange-139"},{"speaker":"塚本委員","kind":"質問","question":"プログラミング学習です。先ほど湯澤委員からも質疑が若干ありましたけれども、もう少し具体的に、詳細にお聞きしたいと思います。最初に、決算書では５６５万５,６７３円ということで決算されていますが、主にどういったことに支出されたのか、ご説明ください。","respondent":"矢部教育総合支援センター長","answer":"そのロボットを学校に貸し出して、端末も一緒なのですけれども、そこで子どもたちが様々な指令を出して、何度も試行錯誤する、そういう意味で、なかなか好評の事業です。","id":"exchange-140"},{"speaker":"塚本委員","kind":"質問・要望","question":"先ほどの質疑の中でも、電気を使った授業で、プログラミングをやっていますということでした。できるだけ詳細に教えていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"中学生は技術・家庭の中で、もともとこれはありましたけれども、例えば、自動車をあるマスのところまでプログラミングして動かすような活動を繰り返し、問題解決の連続なのですけども、そういった活動はこれまでも中学生では実施してまいりました。","id":"exchange-141"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうすると、教えていただきたいのは、そういった授業でやったことに対する習熟度をどのようにして今見ていらっしゃるのかというところが気になりまして、いわゆる国語、算数、理科、社会の中に組み込まれているので、そこでのペーパーテストみたいなことで、どれだけできましたかみたいなことを見ていらっしゃるのか、そういうことがそもそも可能なのかというかということも含めて。","respondent":"矢部教育総合支援センター長","answer":"ただ、時数が、そんなにプログラミング教育に時間をかけているわけではないので、例えば、ペーパーテストの中の一部分、大体大きなＢ４のテストが多いのですけれども、一部分、４分の１程度で、実施した中身を、論理的思考を見るようなテストになります。","id":"exchange-142"},{"speaker":"塚本委員","kind":"質問・要望","question":"昨年から必修化ということで始まって、そんな中でコロナ禍になってということで、学校も休校になったりしていろいろ大変な中、こういった新しい取組に対してしっかり取り組んでいらっしゃるというところで、これからの大事な子どもたちにとって、デジタル化というのが盛んに言われる中で、論理的思考というのをしっかり身につけていくということはとても重要な教育的要素と捉えておりまして。","respondent":"矢部教育総合支援センター長","answer":"充足度ですが、人口が増えてきているのと同時に、当然、対象のお子様も増えています。そういったことについては、我々のほうも予算を増額して対応していますが、見方によっては、もう１時間いてくれたらいいとかということはあるかと思っています。","id":"exchange-143"},{"speaker":"塚本委員","kind":"質問・要望","question":"確かに品川区は、他区に比べても、介助員等については大きな予算をつけて、かなり進んでいるという評価をいただいている分野かと思います。ニーズ的にというか、予算的に無理だみたいな話も一方でありますけれども、その件は置いておいたとして、そういったもの、つく・つかない等の説明についてしっかりと実施していただきたいという思いがありますけれども、ご答弁をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"規定はありますので、学校にもきちんと周知できるように、改めて説明してまいりたいと思います。","id":"exchange-144"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私からは、３６５ページ、６・９年生思い出づくり事業から入ります。もう一個は、よく分からないのですが、地域での教育というか、校外学習なのかよく分からないのですが、それについてお伺いしたいと思います。これは本当に感謝をしておりますが、今の６年生を見ると、昨年、林間学園も行けていない。修学旅行もという、今の６年生は本当にかわいそうと特に思っております。は地域の後で言います。","respondent":"有馬庶務課長","answer":"状況によって行けなければ、昨年のような思い出づくり事業をまた継続して考える必要があるだろうと。幸いにして、９年生の修学旅行については、この秋と来春に行けるよう、再計画がまだ立っているので、何とか行ければと思っています。もう一つは、今年の８年生なのです。","id":"exchange-145"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"子どもたちのためにも、ぜひいろいろ実現をしていただきたいと思いますので、これはよろしくお願いいたします。これはまさに私の町会のところの話をすると、品川神社の例大祭、２年中止でありましたけれども、いつも必ず、特に９年生は代表２人を選んで、町会の祭礼委員会の会議、これにも必ず来てもらって、責任感を持って祭礼も手伝ってよということをやっています。そこについての考え方を教えてください。","respondent":"中島教育長","answer":"そういったものに対し支援していきたいと思いますし、２学期からは今、各学校のコミュニティ・スクールの地域の方々が集まる委員会に全部回って参加していますので、そういったところでも具体的にお願いをしていきたいと考えています。","id":"exchange-146"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/685794?Template=document&Id=1510#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":118228,"voices":353}}]);
